WoWFQ[54781] = { t = "برای ناهار چی داریم؟", d = "مزدورهای Shadowtrade من در ازای Stormarion Core می‌جنگند، بدون هیچ سؤالی، ولی آن‌ها هم گرسنه می‌شوند!\n\nاینجا غذا خیلی کمیاب است، پس به آذوقه نیاز داریم!\n\nیک مزدور را با خودت ببر و برایش غذای خوردنی پیدا کن. زحمتت را جبران می‌کنم!", o = { "Stormray Fin", "Domanaar Snack Pack" }, p = "مزدور خوب سیر شده؟", c = "وقتی حرف از مزدور می‌شود، هیچ چیزی مثل شکم سیر... و طلا آن‌ها را وفادار نگه نمی‌دارد." }
WoWFQ[86509] = { t = "دوست یا دیو", d = "با وجود آن نمایش پرشور، تمایل دارم به تو کمک کنم. مگر کمی خشونت میان دوستان، چه اشکالی دارد؟ \n\nو چون دوست هستیم، رازی به تو می‌گویم: خاموش کردن طوفان فقط از درون Nexus-Point‌ها ممکن است. البته نمی‌شود همین‌طور راه افتاد و واردش شد--به Mantle of Predation نیاز داری.\n\n<Decimus seems to savor the words.>\n\nحواسم هست؟ بیا گردوخاک را از تن بتکاندیم و جای... متمدن‌تری برای گفت‌وگو برویم. در املاکم منتظرم.", o = { "به Howling Ridge سفر کن", "کمی بمان و به Lothraxion گوش بده" }, c = "مهمان برای یک domanaar نعمتی کمیاب است. مخصوصاً مهمان‌هایی که با میل خودشان قدم به اینجا بگذارند." }
WoWFQ[86510] = { t = "Domus Penumbra", d = "به نظر می‌رسد همه‌مان می‌خواهیم جلوی Voidstorm را بگیریم. وجه مشترک--چیزی که اینجا کمیاب است. حتی به تو می‌گویم چطور، و در عوض فقط از تو می‌خواهم بگذاری از تماشای نمایش لذت ببرم.\n\nاما حتماً خسته‌ای. خودت را به این‌جا و آن‌جا بزن و از امکانات استفاده کن. بعد گفت‌وگومان را ادامه می‌دهیم.\n\nزیاد طولش نده. چیزهای زیادی برای دیدن هست، و طوفان همچنان می‌غرد.", o = { "با Void Researcher Anomander صحبت کن", "با Innkeeper Hospitus صحبت کن", "به Umbric در برپا کردن درگاه کمک کن", "به Flight Master Malloril کمک کن" }, p = "حیوانات خانگی‌ام را دیده‌ای؟ قول می‌دهم بی‌آزار باشند. البته به شرطی که گرسنه نباشند.", c = "راحت هستی؟ چه لذت‌بخش است که کسی قدر مهمان‌نوازی‌ام را بداند.\n\nحالا بهتر است قبل از اینکه دوست درخشانت دوباره قشقرق به پا کند، سراغ کار اصلی برویم." }
WoWFQ[86511] = { t = "لبه ورطه", d = "من به Decimus بیشتر از بقیه جانوران اینجا اعتماد ندارم. ولی به این اعتماد دارم که او فقط از خودش پیروی می‌کند. به نظر می‌رسد داشتن Xal'atath به‌عنوان ارباب با میلش جور در نمی‌آید. می‌توانیم یکی از دشمنان را علیه دیگری برانیم. حتی Lothraxion هم قبول می‌کرد اگر این‌قدر یک‌دنده نبود.\n\nاگر این Mantle of Predation به ما امکان می‌دهد طوفان را متوقف کنیم، بهترین شانس ماست. گروهی از ren'dorei مشغول شناسایی Obscurion Citadel هستند. با آن‌ها دیدار می‌کنیم تا ببینیم چه چیزهایی یاد گرفته‌اند.", o = { "به گزارش شناسایی گوش بده", "کنار Obscurion Citadel با پیشاهنگان ren'dorei دیدار کن." }, p = "تا حالا از اینجا دوری می‌کردم. زوزه‌ها و بوی تعفن مثل هشداری روی باد می‌آیند.", c = "دوست ندارم نیروهایمان را تقسیم کنیم. وقتی این‌همه در میان است، نه.\n\nمثل Lothraxion هجوم نیاوریم. ببینیم Decimus چه می‌داند. دوست ندارم بی‌آمادگی به شکار domanaar برویم." }
WoWFQ[86512] = { t = "برداشت", d = "دو نشان لازم داری؛ با هر دو می‌توانی خزانه Terminas را بگشایی و mantle را تصاحب کنی.\n\nنخستین نشان از آنِ Torentia است، حاکم حقیر این گودال اندوهناک. برای Terminas بیش از حد جاه‌طلب است تا او را به حلقه درونی‌اش بپذیرد، و بیش از حد ترسو تا راه خودش را برود. پس همین‌جا پشت سپری نشکن از Void لانه کرده است.\n\nاز دست دادن همان قلمرو ناچیزش هم برایش وحشتناک است. چه حیف. راهت را با کشتار در گودال باز کن؛ ظهور شکارچی رأس تازه‌ای چیزی نیست که از چشمش بیفتد.", o = { "جلب توجه Torentia" }, p = "گرسنگی اینجا را حس می‌کنی؟ تعجبی ندارد که Void به اینجا آمده.", c = "حسش می‌کنی؟ هر جانور اینجا یا از تو می‌ترسد یا می‌خواهد بکشدت. حالا دیگر مولای‌شان هم نمی‌تواند نادیت بگیرد." }
WoWFQ[86513] = { t = "در برابر امواج", d = "انتظار ارتشی را داشتم، اما اینجا هرج‌ومرج است. جانورانی که از Void سرازیر شده‌اند، پرخور و در حال گرفتن اسیر برای تفریح.\n\nمأموریت ما تصاحب Mantle است، اما نمی‌توانیم از این چشم‌پوشی کنیم. دیر یا زود، این نیروها علیه Silvermoon آزاد می‌شوند. هر ضربه‌ای که حالا می‌زنیم، در آنجا جان نجات می‌دهد، <name>.\n\nقوایشان را از قوت بینداز، جریان جانوران را از Void قطع کن، و هر اسیری را که ربوده‌اند آزاد کن.", o = { "Void-Tainted Flesh نابود شد", "Void Gate مهر و موم شد", "اسیران آزاد شدند" }, p = "حتی اگر شکست بخوریم--Light ازمان دور باد--حداقل ضربه‌ای زده‌ایم.", c = "این چیزی است که مادرم همه این سال‌ها تنها با آن جنگیده؟ دیگر نمی‌گذارم این بار را تنها به دوش بکشد." }
WoWFQ[86514] = { t = "بانوی گودال", d = "با وجود تمام قدرتشان، این domanaarها هنوز مثل جانوران رفتار می‌کنند. این برای ما خوب است. گرگ‌ها سعی می‌کنند از هم دوری کنند، اما وقتی قلمرو یکی به خطر بیفتد، تا مرز مرگ می‌جنگند.\n\nتا اینجا به‌وفور ثابت کرده‌ای که تهدیدی جدی هستی. اگر Torentia را به چالش بکشی، نمی‌تواند عقب‌نشینی کند--برخلاف سرشتش است.\n\nپس جنگ را به درخانه‌اش ببر، بکشش و نشانش را تصاحب کن.", o = { "Torentia به چالش کشیده شد", "Torentia شکست خورد", "نشان Torentia", "نشان Torentia مصرف شد", "در بخش بالایی Obscurion Citadel کنار Alleria Windrunner تجمع کن." }, p = "نشان Torentia را برداشته‌ای؟", c = "من Lothraxion را هیچ‌وقت این‌قدر بی‌احتیاط ندیده بودم. خرج کردن جان‌ها، یورش کورکورانه--نمی‌داند اینجا فرمانده ارتشی نیست؟\n\nحداقل تو وظیفه‌ات را انجام دادی. ببینیم می‌توانیم مأموریت را نجات دهیم." }
WoWFQ[86515] = { t = "گرسنگی تهی", d = "داوری Alleria تار شده است. زمان زیادی را در Void فرورفته سپری کرده. من لشکرکشی‌هایی را در سراسر کیهان فرماندهی کرده‌ام. تلفات گریزناپذیرند. اگر مرگ هر سربازی اراده‌ام را می‌شکست، نمی‌توانستم فرماندهی کنم.\n\nاطلاعات لازم را داریم: محل دارنده نشان. این شیاطین از یک domanaar به نام Severum زمزمه می‌کنند. بکشش و نشانش را بگیر، تا از دست اینجا خلاص شویم.", o = { "نشان Severum", "نشان Severum مصرف شد" }, p = "کاش می‌شد هر voidspawn را تیغ کشید.", c = "خوب بود. به‌زودی Mantle of Predation را خواهیم داشت و دیگر نیازی به Decimus نیست.\n\nمثل Alleria فایده‌مندی‌شان را با وفاداری اشتباه نگیر." }
WoWFQ[86516] = { t = "همه شکار می‌شوند", d = "Lothraxion طوری رفتار می‌کند که انگار ارتشی در اختیار داریم، اما یک ultradon تنها اگر غافلگیرمان کند، از میان‌مان می‌گذرد. باید زیرک‌تر باشیم.\n\nمن جانوران این جهان را زیر نظر داشته‌ام: مطالعه‌شان کرده‌ام، ردشان را گرفته‌ام، کشته‌امشان. از ضعف شکار می‌کنند و با نخستین نشانه سستی، هم‌نوعانشان را از پا درمی‌آورند.\n\nاز لاشه‌های اطراف دژ Carrion Essence برداشت کن. با آن ultradonها را نشانه‌گذاری کن. جانوران دیگر به آن‌ها حمله می‌کنند و گمان می‌برند زخمی یا در حال مردن‌اند. بگذار همدیگر را از پا درآورند، بعد با هر چه باقی ماند کار را تمام کن.", o = { "برای تضعیف ultradonها از جانداران کشته‌شده Carrion Essence برداشت کن", "Slavering Ultradon کشته شد" }, p = "این جانداران با غریزه اولیه کار می‌کنند. می‌توانیم از آن بهره ببریم.", c = "شکار خوبی بود. با مرگ ultradonها، شاید واقعاً بتوانیم زنده از اینجا بیرون برویم." }
WoWFQ[86517] = { t = "گم‌شده در Void", d = "\"تلفات قابل‌تحمل\"--امیدوارم هیچ‌وقت این‌قدر راحت از مرگ دوستان و همرزمان نگذرم. Light چه سودی دارد اگر ما را مثل دشمنانمان بی‌احساس کند؟\n\nSideras کلاً کشته می‌شد. خوشبختانه از یک شکاف گریخت. Riftblade Maella بقیه را در عقب‌نشینی جنگی رهبری کرد. پیدایش کن، شاید با هم مانده باشند.\n\nنمی‌توانم Sideras را ترک کنم، نه تا وقتی حالش پایدار شود.", o = { "Riftblade Maella پیدا شد", "Lady Darkglen پیدا شد", "Riftwalker Hieron پیدا شد", "دفترچه Hieron" }, p = "Lothraxion باید بهتر از این بداند.", c = "این منصفانه نیست؛ Hieron برای مُردن به اینجا نیامده بود. Light باید از مردم محافظت کند، نه اینکه به مرگشان بکشاند.\n\n<Arator seems lost in thought.>\n\nممنونم. حواسم هست دفترچه‌اش را به بقیه برسانم." }
WoWFQ[86518] = { t = "Mantle of Predation", d = "تند پیش برویم. باید قبل از بازگشت Terminas و قبل از اینکه Lothraxion کار احمقانه‌ای بکند، Mantle را بدزدیم.\n\nمی‌دانم اینجا حوصله‌اش را سر می‌برد، اما باید بداند به غریزه‌ام اعتماد کند. فکر می‌کردم آن‌قدر با هم جنگیده‌ایم که این اعتماد را جلب کرده باشم.\n\nبیایید این را تمام کنیم. هر وقت آماده بودی.", o = { "کمی بمان و به Lothraxion گوش بده", "وقتی آماده بودی با Alleria صحبت کن", "مهرها باز شدند", "Mantle of Predation تصاحب شد" }, c = "خب هستی؟ حتماً چیزی از قلم افتاده برایم. مگر Decimus اصلاً چرا زحمت کمک به ما را کشید؟ هر لحظه می‌توانستند به ما خیانت کنند. هیچ منطقی ندارد..." }
WoWFQ[86519] = { t = "Abyssus, Abyssum", d = "Decimus را نمی‌بینم. با آن همه ذوق برای تحویل دادن ما، انتظار داشتم بخواهد تماشاگر نبرد باشد. برای یک domanaar چه چیزی از لذت بردن از نبرد مهم‌تر؟\n\n<Alleria nocks another arrow.>\n\nجواب‌ها می‌توانند صبر کنند. الان باید زنده بمانیم.", o = { "دشمنان قتل‌عام شدند", "با Alleria Windrunner بجنگ" }, c = "Lothraxion nexus-point‌ها را ریشه‌کن می‌کند، حتی اگر خرجش Silvermoon باشد!" }
WoWFQ[86520] = { t = "شکارِ Light", d = "وقتی نیست؛ Lothraxion جلوتر است. خودت را به Nexus-Point Xenas برسان، <name>، ما آنجا به تو می‌پیوندیم.", o = { "به Nexus-Point Xenas سفر کن." }, c = "خودش اینجاست؛ باید جلویش را بگیریم." }
WoWFQ[86521] = { t = "Nexus-Point Xenas: خسوف", d = "اگر Nexus-Point را نابود کند، همه کسانی که برایشان می‌جنگیم ممکن است نابود شوند. سعی می‌کنم آرامش کنم، اما اگر نشد، اگر مجبور شوم...\n\n<Alleria's face clouds.>\n\nبدون تردید. این را تمام می‌کنیم، به هر شکل ممکن.", o = { "برای صف follower dungeon با Alleria صحبت کن", "کمی بمان و به Alleria گوش بده", "وارد Nexus-Point Xenas شو و جلوی Lothraxion را بگیر", "به Decimus بگو طوفان را تضعیف کند.", "با Alleria Windrunner صحبت کن." }, p = "آن‌قدر راه آمده‌ایم که هیچ چیز نتواند جلویمان را بگیرد.", c = "تمام شد. می‌توانیم نفس بکشیم، اگر فقط برای یک لحظه." }
WoWFQ[86528] = { t = "Holokey ترک‌خورده", d = "<وسیله‌ای اترئالی با ظاهری بی‌همتا روی زمین سرد افتاده است. درگیری‌ای ترکی در امتداد وسطش انداخته.\n\nشاید Alleria بداند این چیست.>", o = { "Holokey ترک‌خورده" }, c = "قبلاً یکی از این‌ها را دیده‌ام. اترئال‌ها با آن‌ها ارتباطات را رمزگذاری می‌کنند.\n\nیافته عالی‌ای بود، <name>." }
WoWFQ[86530] = { t = "نخست، پوسته‌ها", d = "سال‌ها پیش، در جهانی دلگیر از باتلاق، Army of the Light را به manaforge‌ای شیطان‌گرفته رهبری کردم که زیر پیچک‌ها و مه پنهان شده بود. سربازانم آن جهان را در غبار شعله و دود ترک کردند، با بوی mana سوخته و پیروزی در هوا. اکنون همان می‌کنیم که آنگاه کردیم.\n\nکار را با جمع‌آوری مخزن‌های خالی‌ای آغاز می‌کنیم که برای نگه‌داشتن و حمل سوخت به کار می‌برند. اترئال‌ها، و مخصوصاً ماشین‌هایشان، این مخزن‌ها را دارند.", o = { "Empty Manacell جمع‌آوری شد", "کمی بمان و به Lothraxion گوش بده", "Lothraxion را در عمق بیشتری از Ethereum Refinery پیدا کن." }, p = "درست مثل قبل.", c = "خوب. همان مدلی که به یاد دارم. \n\nحالا، کاتالیزور." }
WoWFQ[86531] = { t = "اخلال در کار", d = "Shadowguard شاید روزی سر به طغیان بر Xal'atath بلند کرده باشد، اما حالا جزئی از ارتش اوست. هر کاری هم که با انرژی‌های گردآوری‌شده در اینجا می‌کنند باید متوقف شود.\n\nسربازان، برداشت‌گران و ماشین‌هایشان را از پا درآور. من هم همین کار را می‌کنم و در عمق بیشتر به تو می‌پیوندم.", o = { "Manaforge مختل شد", "Alleria را در عمق بیشتری از Ethereum Refinery پیدا کن." }, p = "چه نقشه‌ای در سر دارد...", c = "خواهند کوشید از نو بسازند، اما این فرصت را به آن‌ها نمی‌دهیم." }
WoWFQ[86536] = { t = "دشمنان قابل‌اعتماد", d = "پیشاهنگان ren'dorei از دشمنی آشنا در این جهان خبر می‌دهند. اترئال‌ها. آن میدان‌دزدان و راهزنان پست که هر گوشه Great Dark Beyond را آزار داده‌اند. Shadowguard بدترینشان است. سرشان را ما می‌آوریم.\n\nاین... چیزی که به اسارت گرفته‌ایم حتماً می‌داند اینجا چه می‌کنند و خیلی چیزهای دیگر. رازهای Void را از وجودش بیرون بکش. ترتیب بده قانع شود آنچه می‌داند بازگو کند، وگرنه از روش‌های خودم استفاده می‌کنم.", o = { "بازجویی از Decimus", "بالای Ethereum Refinery در نقطه دیدبان با هم دیدار کنید.", "با Decimus صحبت کن" }, p = "Lothraxion نقشه‌ای دارد. به او اعتماد دارم.", c = "اگر Xal'atath فانی بوده، آنگاه با همه کارهایی که کرده و با چیزی که امروز شده، هیولاتر از همیشه است.\n\nنبرد درازمان در این جهان به پایان می‌رسد. قسم می‌خورم." }
WoWFQ[86537] = { t = "ناامنی شبکه", d = "با توجه به طراحی و قدرت انرژی این holokey، حتماً برای رمزگذاری ارتباطات مهم به کار می‌رود.\n\nاین سرنخ را امتحان کنیم. ببین با کدام‌یک از کنسول‌های اطراف پالایشگاه سازگار است. با این آسیبی که دیده، باید هر خرده‌اطلاعاتی را که می‌شود کنار هم بچینیم.", o = { "رمزگشایی پیام اول", "رمزگشایی پیام دوم", "رمزگشایی پیام سوم", "رمزگشایی پیام پایانی", "پیام پایانی بازیابی شد" }, p = "چه چیزی پیدا کرده‌ای؟", c = "Xal'atath.\n\nبگذار این پیام پایانی را ببینیم." }
WoWFQ[86538] = { t = "دوم، سوخت", d = "اترئال‌ها گوشه‌هایی از کیهان را می‌یابند تا nether پرقدرتشان را بنوشند. Arcane، Void، fel--برای آن‌ها فقط بازده مهم است. و ما رگه‌ای سرشار برای کار در اختیار داریم.\n\nحالا، آنان را بکش که این انرژی را در اختیار دارند: elementalهای arcane وحشی که از لوله‌هایشان بیرون می‌زنند، یا برداشت‌گران اترئالی‌شان که از انرژی لبریزند. به آن نیاز داریم.", o = { "Arcane Remnant (Voidstorm)" }, p = "برو. کاتالیزور را جمع کن.", c = "پرقدرت. انرژی را حس می‌کنم--درخشان. باشکوه." }
WoWFQ[86539] = { t = "یک Naaru!", d = "نمی‌گذارم naaru دیگری به دست تاریکی بیفتد.\n\nقبل از حرکت، پیشاهنگان خبر دادند که Nexus-Point‌ای به این پالایشگاه متصل یافته‌اند. اگر نیروهای Void naaru‌ای در اختیار داشته باشند، شاید همان‌جا نگهش داشته باشند.\n\nمن manacell‌ها را آماده می‌کنم تا هم‌زمان جست‌وجو کنیم. بیا.", o = { "Lothraxion را در نقطه دیدبانِ Nexus-Point Mid'Ar پیدا کن." }, c = "naaru‌ای در اسارت. Light به این هیولاها رحم نخواهد کرد." }
WoWFQ[86540] = { t = "سوم، منفجرش کن", d = "manacell‌ها آماده‌اند. آن‌ها را کنار ستون و ماشین‌های پشتیبانش بگذار. وقتی کار تمام شد، از راه دور به Alleria دستور می‌دهم آتششان بزند.\n\nاما تا وقتی naaru به امنیت نرسیده، نمی‌توانیم جلو برویم. حالا برو و من مطمئن می‌شوم آزادش کنیم.", o = { "Overcharged Manacell را بگذار", "در تأسیسات اترئالی Nexus-Point Mid'Ar با Lothraxion دیدار کن." }, p = "اینجا چه می‌کنی؟ manacell‌ها را بگذار، همین حالا!", c = "این دارد زیادی طول می‌کشد! هر لحظه تلف‌شده، ما را به نابودی نزدیک‌تر می‌کند!" }
WoWFQ[86541] = { t = "برای پیش‌آمدن احتمالی...", d = "شاید Lothraxion بتواند آن سپر را به تنهایی پایین بیاورد. یا شاید فقط آدمِ پرادعا و پُرحرفی است.\n\nDevouring Host به سربازان مورد اعتمادش تکه‌هایی از یادگاری می‌دهد که هر وسیله اترئالی را دور می‌زند، حتی آن سپر را. باید راهی نسبتاً بلند در میان نیروهایشان باز کنی تا shard‌های کافی پیدا کنی.\n\nولی مگر من چه می‌دانم؟ من فقط voidspawn بی‌ارزشی هستم.", o = { "Fragmented Keystone", "ترکیب Fragmentها", "در تأسیسات اترئالی Nexus-Point Mid'Ar با Decimus دیدار کن." }, p = "<Decimus glances sideways at you.>", c = "یک فانی که به ایده‌های بیرونی گوش می‌دهد. واقعاً نمونه. نیازی به تشکر نیست.\n\nراستی، شاید دوست داشته باشی از این بند آزادم کنی؟ این روزها از دست Light کمی گزگز دارم.\n\nنه؟ باشد که خیر." }
WoWFQ[86542] = { t = "سوسویی در تاریکی", d = "داری وقتی را تلف می‌کنیم! وقت کم است!\n\nآن سپر را پایین بیاور، همین حالا! عذاب T'era رشته‌جانم را پاره می‌کند!", o = { "کنسول دور زدن سپر را هک کن", "نزد T'era برگرد", "Dark Splinter کشته شد", "T'era مهار شد" }, c = "هر چه داشتم. به‌راحتی... بلعیده شد." }
WoWFQ[86544] = { t = "پس از مرگ", d = "همه‌مان در اینجا باری سنگین به دوش می‌کشیم. خودم را به سوی ناامیدی می‌لغزیدن می‌بینم. اما تا وقتی حاضر نشویم دوباره بلند شویم، شکست نخورده‌ایم. می‌دانم مادرم خودش را باز خواهد یافت. اما بقیه باید بدانند این نبرد تمام نشده است.\n\nبا Hieron صحبت کن. او و دیگر پیشاهنگان باید اطلاعاتی داشته باشند. می‌توانیم از همان‌جا شروع کنیم.", o = { "کمی بمان و به Alleria گوش بده", "گزارش Hieron", "گزارش Maella", "کمک به پیشاهنگان درمانده", "حوصله‌سر‌زدگی با Lothraxion", "حوصله‌سر‌زدگی با Decimus" }, p = "مادر... طاقت بیاور.", c = "آن چه بود...؟" }
WoWFQ[86545] = { t = "نشانِ Light", d = "نه! <name>، باید جلویشان را بگیریم! عصبانیت جوشان Lothraxion همه چیز را به خطر می‌اندازد! اینکه همین حالا، از همه وقت‌ها، وقتی مادرم از پا افتاده...\n\nوقتی نیست. باید برویم!", o = { "Lothraxion و Decimus را در حاشیه Locus Point پیدا کن", "برای درمان با Arator صحبت کن", "Burning Light را جمع کن و به Arator برسان", "افشای Decimus" }, p = "باید زودتر می‌فهمیدم... به من بپیوند. <name>، بیایید حقیقت را آشکار کنیم.", c = "Decimus domanaar به‌مراتب تواناترتری است از آنچه خودش را جلوه داده بود." }
WoWFQ[86557] = { t = "از نزاع تا مرگ", d = "ها! دنیایی دور، مملو از هیولاهای شرور و درنده؟ مثل قدیم‌ها.\n\nمن، Alleria و Turalyon هزار سال با دیوها در دنیاهای دور جنگیدیم. راه‌حل حالا هم به همان سادگی است.\n\nیا بکش، یا کشته می‌شوی.", o = { "هیولاهای Ingress کشته شدند", "در لبه The Ingress به Lothraxion بپیوند." }, p = "انکار نمی‌کنم، هنوز هم در هیجان نبرد جان می‌گیرم. تا وقتی که جنگی برای حقیقتی درست باشد.", c = "جنوران پلید. حسش کردی؟\n\nهمه‌شان بوی Void می‌دهند." }
WoWFQ[86558] = { t = "نگه‌داشتنی از آرامش", d = "ren'dorei می‌دانند چه باید بکنند. آن‌ها Shadestar Loci می‌گذارند تا از این منطقه محافظت کنند، اما برای فعال کردنشان به کمک تو نیاز دارند.", o = { "Shadestar Locus فعال شد" }, p = "مواظب باش، <class>. خیانت از هر سو ما را تهدید می‌کند.", c = "void elf‌ها ریسک آلوده شدن را به جان می‌خرند، و با این حال بیش از همه شایسته فهمیدن دنیای اطراف ما هستند. به تخصصشان نیاز داریم، اما نمی‌توانیم بهشان اعتماد کنیم.\n\nجان می‌کند، اما پیشاهنگان بیشتری فرستاده‌ام.\n\nهمه‌چیز را می‌بلعد." }
WoWFQ[86559] = { t = "مرز دور، دورتر", d = "این مکان را امن کردیم. بعضی از void elf‌ها می‌توانند از اینجا اردوگاهی درست‌وحسابی بسازند.\n\nباید نقطه ضعفی باشیم که بتوانیم از آن استفاده کنیم تا طوفان را متوقف کنیم. باید ارتشم را به اینجا بیاورم تا به ارتش‌های Xal'atath کیفر برسانم!\n\nمن و Arator جوان را همراهی کن. ببینیم از آن‌سوی افق چه می‌توانیم برویم بیرون.", o = { "Voidstorm بررسی شد", "با Alleria صحبت کن", "در Nexus-Point Antius به Lothraxion، Alleria و Arator بپیوند." }, c = "بقیه void elf‌ها برای ساختن اردوگاه یا شناسایی پخش شده‌اند.\n\nمن... درباره حضور Alleria در دوندرم. مهارت‌ها و تجربه‌اش فوق‌العاده ارزشمند است، و با این حال...\n\nVoid درونش آن‌قدر قوی است... نگرانم. حواست به او باشد.\n\nبه Void هرگز نمی‌شود اعتماد کرد." }
WoWFQ[86561] = { t = "دنیایی غریب و متفاوت", d = "من از کاربرد این برج‌ها سر در نمی‌آورم؛ فقط می‌دانم نامشان Nexus-Point است و از قدرت Void می‌لرزند. باید اطلاعات بیشتری به دست بیاوریم. \n\ndomanaarها روی جانوران اینجا از فلزی آغشته به Void استفاده می‌کنند تا به ارتش‌های Devouring Host اضافه‌شان کنند. اسمش را shadowgrafting می‌گذارند.\n\nبه آن‌ها قدرت می‌دهد، اما ذهنشان را هم زیر و رو می‌کند.\n\n<Alleria smiles wryly.> \n\nچه قدرتی نیست که چنین کند؟ \n\nبرایش نقشه‌ای دارم. با تو در کنارم، بالاخره می‌توانم عملی‌اش کنم.", o = { "Shadowgraft Fragment" }, p = "فلز روی این جانداران... انگار مخصوصاً رسانای خوبی برای انرژی‌های جادویی است. جالب است.", c = "<Lothraxion scowls.>\n\nچیز تحقیرآمیزی است. Alleria نقشه‌اش را برایم توضیح داد، اما مطمئن نیستم قبول کنم." }
WoWFQ[86562] = { t = "رقص با مرگ", d = "شاید گروه حمله کوچکی باشیم، اما قوی هستیم. مگر تو که نیستی.\n\nلازم نیست کاملاً پنهان‌کاری پیش بگیریم. باید راهی به سوی domanaarهای اینجا باز کنیم.\n\nقوی‌ترین دشمنانی را که می‌توانی از پا درآور. ما هم به نبرد می‌پیوندیم.", o = { "Voidgrasper کشته شد", "Vathen the Rebel کشته شد", "Scytheryp the Slicer کشته شد" }, p = "قوی‌ترین دشمنان اینجا را پیدا کرده‌ای؟ حیرت می‌کنم چه موجودی می‌تواند بشود که تا ابد Void بنوشد...", c = "به نظر می‌رسد اینجا جاندارانی هست که هم جانوری و هم جادویی‌اند.\n\nVoid به سوی خشونت کشیده می‌شود. من دنیاهای بی‌شماری را غرق در آن دیده‌ام.\n\nممکن است درندگی جانوران اینجا Void را خودبه‌خود به اینجا کشیده باشد؟" }
WoWFQ[86565] = { t = "برای شریران دعایی نیست", d = "Alleria نقشه‌ای دارد: با همین ماده shadowgrafting آن domanaar را برای گرفتن اطلاعات به دام بیندازیم.\n\nاما اطلاعات دست‌کم‌گرفته از شریر چه سودی دارد؟ با دیوهای بی‌شماری جنگیده‌ام و هر کدام دروغگو بود.\n\n<Lothraxion scowls.>\n\nفعلاً از نقشه‌اش پیروی می‌کنیم. با این فلز کاری که می‌گوید بکن، بعد جانور دست‌آموز domanaar را بکش.\n\nوقتی با این موجود پلید حرف زدیم، خودم تصمیم می‌گیرم چه مدت زنده بماند.", o = { "Shadowgraft Fragmentها دستکاری شد", "Sinewshredder کشته شد", "تعقیب domanaar در میان Stellar Vortex", "کمی بمان و به Alleria گوش بده", "در The Ingress با Alleria، Lothraxion و Arator دیدار کن." }, c = "کار خوبی انجام دادی، <name>." }
WoWFQ[86810] = { t = "برداشت از Void", d = "برای مقابله اثربخش با ناهنجاری‌های void اینجا، باید نمونه‌های قابل استفاده از خود ناهنجاری‌ها به دست بیاوریم. در منطقه دنبال ظرف‌های نگه‌دارنده‌ای بگرد که ناهنجاری‌های در حال رشد را در خود دارند، و همچنین Unstable Oozelingهایی که از آلودگی زاده شده‌اند. برای ساده‌تر شدن کار از دستگاه جمع‌آوری استفاده کن. فقط Oozelingهای زنده نمونه سالم می‌دهند.", o = { "Anomaly Sample جمع‌آوری شد", "استفاده از Collector روی Oozeling زنده یا Anomaly Barrel." }, p = "نمونه‌های لازم را جمع کرده‌ای؟", c = "خیلی مطمئنم این نمونه‌ها کافی نخواهند بود، اما شروع خوبی است! بعداً برگرد، شاید کارهای دیگری هم داشتم." }
WoWFQ[87388] = { t = "جانوری بزرگ‌تر", d = "برگشتن پیش Umbric؟ اما ما در آستانه درک‌های عمیق‌تری هستیم!\n\nفرضیه: در میان این جانداران شکارچی رأسی وجود دارد که ممکن است قدرتی عظیم در اختیار داشته باشد! و رابطه این شکارچی با Void می‌تواند شناخت ما از تاریکی بی‌کران را عمیق‌تر کند.\n\nچند تا از جانداران کوچک‌تر را نابود کن و ببین آیا چنین جانوری به ندای خشونت پاسخ می‌دهد!", o = { "Vicious Karion کشته شد" }, p = "بین این جانوران و Void پیوندی هست... خیلی شبیه ren'dorei.", c = "شاید برای احتیاط هم زمان و مکانی باشد، اما الان آن زمان و آن مکان نیست.\n\nمن تشنه نتیجه‌ام!" }
WoWFQ[87391] = { t = "چشیدن به طعم بومی‌ها", d = "این جا زنجیره غذایی از درندگی است و دندان‌های بیش از اندازه. مطالعات ما هر لحظه خطرناک‌تر می‌شود، اما اگر Matrean اصرار به ماندن دارد، بهتر است او را یاری کنیم. داریم روی پیوندی میان سرشت این جانداران و انباشت Void در اینجا کار می‌کنیم. چند تا از جانوران پایین را از پا درآور و نمونه‌های بافتشان را برایم بیاور. می‌توانیم با مطالعه‌شان بیشتر درباره پیوندشان با Void بدانیم.", o = { "Exotic Tissue Sample", "نمونه‌های بافت روی میز چیده شد" }, p = "مگر می‌شود برای چنین پادشاهی آشوب‌زده‌ای حاکمی وجود داشته باشد؟", c = "نمونه‌ها را بلعید؟ می‌ترسم چنگ Void بر ذهن Matrean دارد محکم‌تر می‌شود." }
WoWFQ[87672] = { t = "Void در هوا پیچیده", d = "ما void elf‌ها همه یک ریسک مشترک داریم... اینکه اگر تاب‌آوریمان کم بیاید، دیوانگی در انتظارمان است.\n<Kelia frowns in Matrean's direction.>\nغارهای پایین آکنده از لمس پلید Void است. Void Surgeها از دل خاک می‌جوشند و دودکسی از کثافتی می‌سازند که قلمروهای زادوولد را پر کرده.\n<She hands you a magical device.>\nاین را بگیر. امواج انرژی تاریکی‌ای را که از خاک می‌ترکند ثبت می‌کند. در The Ingress در امنیت مطالعه‌شان می‌کنیم.", o = { "Void Surge ثبت شد", "Surge A", "Surge B", "Surge C" }, p = "Voidstorm هستی ما را تهدید می‌کند. نمی‌توانیم زیاد بمانیم.", c = "<Kelia's brow furrows as she concentrates on the energy captured by the device.>\nاین اندازه‌گیری‌ها نگران‌کننده است. باید همین حالا برگردیم." }
WoWFQ[87759] = { t = "Void در قفس", d = "این جانوران با یک رام‌سازی درست‌وحسابی به کار می‌آیند. بعد می‌توانی در نبرد ازشان استفاده کنی.", o = { "مهار جانداران Void یا کشتن بازیکنان" }, c = "دیدی؟ به کار می‌آیند. یادت نرود." }
WoWFQ[88653] = { t = "یولک برای تو", d = "پژوهش‌هایمان ثمربخش بوده. می‌توانم نویدبخش قدرتی را حس کنم که ما را می‌خواند. می‌شنوی، <name>؟ شکارچی رأس ما را می‌خواند. آن جانور باید همین نزدیکی‌ها باشد.\n\nباید هدیه جمع کنیم. بله... باید پیشکشی از جنس زنده‌گی به او بدهیم! باید آغشته به جوهر جوانان به استقبالش برویم...\n\nبعضی از موجودات کوچک‌تر در تونل‌های پایین لانه کرده‌اند. چند تخم بشکن و در شیره‌شان غلت بزن. شاید بعدش، بوی آن جانور را به اینجا بکشاند!", o = { "له کردن تخم‌های Blistercreep" }, p = "این‌همه گوشت و استخوان و پیه. چطور مقاومت کنیم؟", c = "در جوهرشان غلتیدی و حالا با نوید قدرت می‌درخشی، قهرمان.\n\nما هم چشیده‌ایم از قدرتشان. در رگ‌هایمان جاری است. محکممان می‌کند." }
WoWFQ[88679] = { t = "رویارویی با پیش‌بینی‌ناپذیرها", d = "این جانوران با یک رام‌سازی درست‌وحسابی به کار می‌آیند. بعد می‌توانی در نبرد ازشان استفاده کنی.", o = { "مهار جانداران یا کشتن بازیکنان" }, c = "دیدی؟ به کار می‌آیند. یادت نرود." }
WoWFQ[88697] = { t = "شفافت هدف", d = "اترئال‌های فلات نزدیک ما را مجبور کرده‌اند سلاح‌های سنگین‌مان را زمین بگذاریم. قبل از آغاز یورش به Voidspire باید turretهایشان را خنثی کنیم.\n\nبا Umbric صحبت کن تا کمکش کند درک تاکتیکی از میدان نبرد پیدا کنی.", o = { "با Umbric صحبت کن", "آغاز مشاهده", "متحدان زخمی مشاهده شدند", "Stalker Patriarch مشاهده شد", "void elf‌های به دام افتاده مشاهده شدند" }, c = "حالا می‌بینی چه بلایی سرمان می‌آید. از کار انداختن آن turretها و نجات void elf‌های بسته به آن ماشین‌ها، مأموریت‌های اول ما هستند اگر بخواهیم warframeها را به آسمان بفرستیم." }
WoWFQ[88698] = { t = "استاد هرج‌ومرج", d = "<name>، اترئال‌ها مدتی است از Ethereum Overcroft یورش می‌آورند و هر جا نیروهای پیشتازمان را پیدا می‌کنند آزارشان می‌دهند. اگر جنگ را به در خانه‌شان ببری، فشار را از روی بسیج‌مان برمی‌داری.\n\nمی‌توانی این کار را برایمان بکنی؟", o = { "تضعیف نیروهای Overcroft" }, p = "به هم زدن کارشان در Ethereum Overlook به ما این پایین کمک می‌کند، <name>.", c = "ممنونم، <name>. تمرکز اترئال‌ها مدتی به درون خودشان برمی‌گردد و این به ما جا برای مانور می‌دهد." }
WoWFQ[88699] = { t = "بی‌قدرت", d = "نبهود زندگی‌شان را می‌مکند تا به تیربارهای اترئال‌ها سوخت برسانند، <name>! نمی‌توان گذاشت این‌طور ادامه پیدا کند.\n\nوارد Ethereum Overcroft شو و هم‌نژادهای void elf من را از چنگ اترئال‌ها آزاد کن. با آزادی‌شان، turretها بی‌قدرت می‌شوند و Turalyon می‌تواند warframeهایش را به پرواز درآورد.", o = { "Leona Darkstrider آزاد شد", "Lady Darkglen آزاد شد", "Riftblade Kelain آزاد شد", "turretها از کار افتادند" }, p = "نمی‌توانیم بگذاریم مردم‌مان این‌طور شکنجه شوند.", c = "مردم‌م از تو تشکر می‌کنند. مطمئنم Turalyon مشتاق شروع یورش خواهد بود." }
WoWFQ[88700] = { t = "دو تن فلز و آتشِ Light", d = "بالاخره می‌توانیم از قدرت warframeهایمان استفاده کنیم.\n\nبا خاموش شدن توپخانه هوایی Overcroft، warframeهای قدرتمندمان می‌توانند در امتداد باروهای برج پرواز کنند و مقاومت محاصره‌مان را نرم کنند.\n\nاگر دوست داری، افتخار خلبانی یکی از این warframeها را برای شکوه Light به تو می‌دهم!", o = { "سوار شدن بر Warframe", "نابودی مدافعان Voidspire" }, p = "به‌زودی، Devouring Host طعم خشم Light را خواهد چشید.", c = "این باید کمی کارشان را سخت کند و یورش پیش‌روی ما را آسان‌تر." }
WoWFQ[88701] = { t = "خاطره باقی می‌ماند", d = "نیروهای پیشتازمان مدتی است Devouring Host را از پا درمی‌آورند، دنبال نقطه ضعف و اطلاعات می‌گردند.\n\nبدبختانه تقریباً همه‌شان به دست آن ارتش از پا افتاده‌اند. برای یاری سقوط‌کردگان دیر شده، اما شاید بتوانیم چیزی برای یادگاری جمع کنیم.\n\nاین کار را می‌کنی، <name>? یادگارهای افتادگان را پیدا کن تا به بازماندگانی که برای محافظت‌شان جنگیده بودند برگردد.", o = { "یادگار افتادگان پیشتاز" }, p = "هنوز پیدا نکرده‌ای؟ مطمئنم این سوغات‌ها مایه دلگرمی عزیزانشان می‌شود.", c = "کار تلخی است، <name>. اما شاید اندکی آرامش برای زندگان به همراه بیاورد." }
WoWFQ[88702] = { t = "سپرِ نجات‌بخش", d = "ما فقط یک ارتش نیستیم، <name>، حتی اگر پدرم این را نبیند.\n\nما یک گروه هم‌راهیم، متحدشده به خاطر میل به محافظت از کسانی که برایمان اهمیت دارند، و کسانی که حامی خودشان نیستند.\n\nو حالا، این حفاظت به زخمیان میدان نبرد هم می‌رسد.", o = { "نجات نیروهای پیشتاز" }, p = "Devouring Host به‌جا نام‌گذاری شده. هر کس به آن بپیوندد یا با آن بجنگد، بلعیده می‌شود--به یک شیوه یا شیوه دیگر.", c = "تعداد خیلی کمی را توانستیم نجات دهیم، <name>.\n\nاز کاری که کردیم خوشحالم، اما کاش می‌توانستیم بیشتر بکنیم." }
WoWFQ[88703] = { t = "شبِ پیش‌رو", d = "voidbeastهای درنده دارند افسران‌مان را می‌ربایند، <name>. گفته‌اند یکی‌شان را از دور، از پس void scryer Umbric دیده‌ای.\n\nاین جانوران در Void غرق‌اند و با تسلط غریزی‌شان بر تلپورت، به آسیب‌پذیرترین‌هایمان حمله می‌کنند و بعد در سایه‌ها محو می‌شوند.\n\nAlleria به دنبالشان رفته و کمکِ یک جفت چشم دیگر خواسته. او را در اردوگاهی در دهانه تنگه شرقی پیدا می‌کنی. روی نقشه‌ات علامت می‌زنم.", o = { "رسیدن به اردوگاه Alleria", "کمک به Alleria" }, c = "امیدوارم برای شکار آماده باشی، <name>. این شکار از بیشتر طعمه‌ها گریزان‌تر است." }
WoWFQ[88704] = { t = "شکارچی صبور", d = "این void beastها گریزاند؛ می‌توانند درگاه‌های void موقتی باز کنند و با آن‌ها مسافت‌های کوتاه را در یک لحظه بپیمایند.\n\nشاید از چشم Turalyon پایین باشند، اما روحیه پیشتاز را به‌شدت تکان داده‌اند.\n\nمن و تو با هم می‌توانیم از آن‌ها زرنگ‌تر باشیم. مطمئنم.", o = { "سرنخ اول پیدا شد", "سرنخ دوم پیدا شد", "سرنخ سوم پیدا شد", "تعقیب جانور", "دفاع در برابر کمین", "از درگاه بگذر" }, c = "خدا را شکر! فکر می‌کردم خودم طعمه شوم!\n\nمی‌توانی من را از این چیز آزاد کنی؟" }
WoWFQ[88705] = { t = "ضربه نهایی", d = "از این جانورها شنیده بودم اما فکر می‌کردم شایعه است. موجودات Void که از درگاه‌های void بیرون می‌آیند، افسرهای‌مان را می‌ربایند و می‌خورند... برایم مثل داستان پچ‌پچ‌ها بود. باورم نمی‌شد سر من بیاید.\n\nیکی بزرگش گرفت‌ام اما فرار کرد. خواهش می‌کنم، قبل از برگشتنش از اینجا برویم!", o = { "آزادسازی Nadia از زندان Void", "اسکورت امن Nadia", "شکست Stalker Patriarch" }, c = "به‌خوبی انجام شد، <name>. نگران این یکی نباش. خودم حواسم هست که سالم برگردد." }
WoWFQ[88706] = { t = "هیچ‌چیز برای همیشه پابرجا نیست", d = "با شکست Patriarch، این موجودات موذی دیگر نباید تهدیدی جدی باشند.\n\nبه نزد Turalyon برگرد و پیروزی‌مان را گزارش کن. من هم به‌زودی خودم را می‌رسانم.", o = { "در نقطه بسیج Voidspire با Turalyon صحبت کن" }, p = "غریزه شکار همسرم بی‌رقیب است. اگر آن هدف را انتخاب کرده، حتماً هدف شایسته‌ای بوده.", c = "هر گناه و پشیمانی‌ای که در دل دارم، باید تسویه‌حسابش را تا پیروزی در نبرد عقب بیندازم.\n\nالان نباید تمرکزمان را از دست بدهیم." }
WoWFQ[88708] = { t = "نتیجه‌گیری‌های خشونت‌آمیز", d = "پژوهش‌مان در اینجا تمام شد. نتیجه: Void به‌خاطر سرشت خشن این دنیا به اینجا کشیده شده! Voidstorm ظرف ذوب عذاب و وحشی‌گری است. Void به سمت همین هاله رنج بی‌پایان کشیده آمد. اینجا برای ren'dorei تهدیدی جدی است. با این حال، مأموریت ما مهم است. بیایید یافته‌هایمان را به بقیه برگردانیم. می‌توانی کمکم کنی Matrean را به هوش بیاوری؟", o = { "قانع کردن Matrean برای رفتن", "رویارویی با Matrean" }, p = "مگر این‌ها ارزشش را داشت؟ مگر ما sin'dorei اشتباه کردیم که سرنوشت‌مان را به Void گره زدیم؟", c = "در تمام این سال‌ها فکر نمی‌کردم Matrean به دام Void بیفتد. شکستش دادم. اما دیگر به مردمم شکست نمی‌دهم. باید در Voidstorm خیلی مراقب باشیم و فقط تا جایی که لازم است بمانیم." }
WoWFQ[88755] = { t = "پژوهش‌های دانشمندانه", d = "<name>... یک لطف.\n\nهمکار پژوهشی‌ام Matrean و من داریم روی جانوران بومی و رابطه‌شان با Void کار می‌کنیم.\n\nبه نتیجه رسیده‌ام، اما Matrean--همیشه بی‌احتیاط و وسواسی--اصرار دارد هنوز چیزهایی برای کشف مانده.\n\nمی‌توانی کمکش کنی قانع شود برگردد اینجا؟", o = { "در Bladeburrows با Kelia و Matrean دیدار کن." }, c = "Void به عکس‌العمل وا می‌گردد، اما من نگاهم را برنمی‌گردانم." }
WoWFQ[88768] = { t = "عوامل تاریکی", d = "وقتی آن سپر بیفتد، نیروهای Xal'atath به سیل به سمتمان می‌ریزند. اگر می‌خواهم manacell‌ها را از راه دور منفجر کنم، به یک فرصت نیاز دارم. قوی‌ترین‌های Devouring Host را از پا درآور؛ باقی مهره‌های Xal'atath راحت‌تر پس زده می‌شوند.\n\nدر همین حین ما هم کاری می‌کنیم سپر پایین بیاید. خوش بگذرد، <name>.", o = { "Darkened Unbound کشته شد", "Insatiable Watcher کشته شد", "Nethermade Protector کشته شد", "در تأسیسات اترئالی Nexus-Point Mid'Ar با Alleria دیدار کن." }, p = "از پا درآوردیشان؟", c = "امیدوارم Xal'atath تماشا می‌کرد. به‌زودی نوبت خودش است." }
WoWFQ[88992] = { t = "تسلط تصورشده", d = "حالا آن اترئال‌ها؟ چیزی دارند که به کارمان می‌آید. بگیرش. همین حالا.", o = { "کشتن Shadowguardها یا کشتن بازیکنان" }, c = "ببین نقشه‌ام چه خوب جواب داد!" }
WoWFQ[89249] = { t = "زیر آوار", d = "دیر رسیدیم. هر قدرتی که کنار هم داشتیم، کافی نبود.\n\n<Arator looks over his shoulder, wary. Then, he crouches and places his hand on Alleria's shoulder. She responds only with a ragged exhale.>\n\nعقب‌نشینی کنیم. ren'dorei‌ها در حالی که ما دنبال Lothraxion بودیم، بیابان‌ها را شناسایی کرده‌اند. شاید بتوانیم اردوگاهشان را همین نزدیکی‌ها پیدا کنیم.", o = { "در Locus Point با Arator دوباره جمع شو." }, c = "حتی قدرت یک naaru هم کافی نبود..." }
WoWFQ[89267] = { t = "موجودیت ناشناخته", d = "هاله عجیبی اینجا حس می‌شود. این اترئال‌ها را آشفته کن و ببین ماجرا چیست.", o = { "کشتن اترئال‌ها یا کشتن بازیکنان" }, c = "خوب است. آنچه اینجا یاد گرفتی را برای بعد به خاطر بسپار." }
WoWFQ[89347] = { t = "غلبه بر ناشناخته‌ها: Drifter رنجیده از خشم", d = "آن هیولا به تنهایی از پسش برنمی‌آیی. کمی همدم جمع کن و سر و کلاش بگذار.", o = { "کشتن Rage-Riddled Drifter", "پیشنهاد بازیکنان: 5" }, c = "شما حشره‌ها وقتی گله‌ای کار می‌کنید، خوب کار می‌کنید." }
WoWFQ[89377] = { t = "شکار زیر پوشش", d = "این بو چیست؟ برو ببین ماجرا چیست.", o = { "کشتن Behemothها یا کشتن بازیکنان" }, c = "این گوشت باید مدتی باشد بیرون مانده، نه؟ و تو خوردی‌اش؟ جالب است." }
WoWFQ[90571] = { t = "از احوال جانور", d = "نقشه دوستت برای منفجر کردن Nexus-Part خیلی دوست‌داشتنی بود. آن‌قدر مصمم به نظر می‌رسیدید که دلم نیامد بگویم راه‌حل چقدر ساده‌تر است.\n\nMantle of Predation به تو اجازه می‌دهد وارد Nexus-Pointها شوی و طوفان را تضعیف کنی. افسوس که تصاحب کردن Mantle است که واقعاً آزمونت می‌کند.\n\nحیوان خانگی‌ام را قرض بگیر--از چشم‌هایش نگاه کن. نشان می‌دهم Mantle را از چه کسی می‌دزدی.", o = { "شناسایی Devouring Citadel", "کمی بمان و به Arator گوش بده" }, p = "برو. به Ciphus ربطی ندارد.", c = "خب دیدی--به‌سادگی باید Mantle را از Terminas بدزدی. پیشنهاد می‌کنم سریع باشی. چه کسی می‌داند Terminas کِی به Obscurion Citadel برمی‌گردد.\n\nحیف شد Ciphus. قصد داشتم خودم او را بخورم، بعد از اینکه تپلش می‌کردم." }
WoWFQ[90782] = { t = "Nethersent", d = "<مرد draenei اول به زبان خودش با تو حرف می‌زند و وقتی پاسخی نمی‌گیری، خودش را وفق می‌دهد.>\n\nمردانِ Void ما را به اینجا آوردند. از آسمان آمدند. می‌جنگند، می‌کشند. می‌خواهیم برگردیم. به برادر و خواهرها کمک کن.\n\nنشان می‌دهم.", o = { "آزادسازی Juras" }, c = "<زن از تو به ظاهر خوشش نمی‌آید، اما با نزدیک شدن تو تعظیمی می‌کند.>\n\nدوست؟ امیدِ ما." }
WoWFQ[90838] = { t = "سوگندها و یادگارها", d = "تو، غریبه... از Shadowguard که K'aresh را به ویرانی کشاند خبر داری؟\n\nخواهرم در آن درگیری گم شد، قلبش به زور به Void برگردانده شد، اما من به خانواده‌ام سوگند خورده بودم... که دوستشان بدارم، هر قدر هم که گناه کنند.\n\nخواهرم، Veraan، حتماً گم شده، اما اگر گردنبندش را پس بگیرم، لااقل روحِ سوگندهایم پابرجا می‌ماند.\n\nمن تعمیرکار ساده‌ای هستم. این دستگاه را طوری تنظیم کرده‌ام که Shadowguard را ردیابی کند، اما به‌تنهایی نمی‌توانم با آن‌ها روبه‌رو شوم.\n\nکمکم می‌کنی؟", o = { "خارج از Ethereum Overcroft با Kifaan دیدار کن." }, c = "خودت را از دید دور نگه دار. دلم نمی‌خواهد سرنوشتی سیاه در انتظارم باشد." }
WoWFQ[90844] = { t = "لحظه‌های آگاهی", d = "در مدتی که قایم شده بودم، گوش می‌دادم.\n\nبه نظر می‌رسد این Shadowguard‌ها شورشی کوچک در دست دارند. بعضی از اترئال‌ها رفتار نامنظمی نشان می‌دهند. آن‌ها را جمع می‌کنند و بازجویی می‌کنند.\n\nاینجا چه خبر است؟\n\nچند تا از این Shadowguard‌ها را از پا درآور و اطلاعات بازجویی‌شان را بیناپرس. هر چه برایم بیاوری، رمزگشایی می‌کنم.", o = { "داده‌های بازجویی", "نشان دادن داده‌های بازجویی به Kifaan" }, p = "فکر می‌کردم Void‌ای که در رگ این اترئال‌ها جاریست همه‌چیز را می‌بلعد.\n\nو با این حال، به نظر می‌رسد بعضی‌شان می‌توانند در برابر تاریکی بی‌کرانش بایستند.", c = "چیزی آتش شورش را در بعضی از Shadowguard‌ها شعله‌ور کرده است.\n\nببینیم چه چیزهای بیشتری می‌توانیم پیدا کنیم." }
WoWFQ[90845] = { t = "خاطرات دور", d = "به خانواده‌ام سوگند خورده بودم که قدرشان بدانم... سخت است وقتی خواهرم به Shadowguard بدل شده. شاید خودش اینجا نباشد، اما ردیابی Shadowguard مرا به اینجا کشانده.\n\nدنبال گردنبندی می‌گردم که متعلق به خواهرم Veraan بود. عجیب است... یادگارهای زیادی از K'aresh را این اطراف رها شده دیده‌ام. به نظر می‌رسد Shadowguard می‌خواهد هر یادآورِ جهان مادری‌مان را نابود کند.\n\nاگر چند تا از این یادگارها را برایم بیاوری، می‌بینیم چیزهایی که می‌شناسم بین‌شان هست یا نه.", o = { "یادگار K'areshi" }, p = "این یادگارها بعضی از آخرین بازمانده‌های جهان مادری‌مان هستند.\n\nخاطراتی که در خود دارند قدرتمندند. Shadowguard درست می‌کند که از آن‌ها می‌ترسد.", c = "چند تای این وسایل را واقعاً می‌شناسم! متعلق به دوستان و نزدیکان بوده‌اند.\n\nاگر گردنبند خواهرم جایی باشد، همین‌جاست." }
WoWFQ[90847] = { t = "حقیقت از دل قدرت", d = "به لطف اطلاعاتت فهمیدیم شورشیان را Questioner Xen'daan بازجویی می‌کند.\n\nگفته می‌شود بعد از بازجویی، اترئال‌های شورشی را به جایی می‌برند تا «سرشان را باری بیندازند».\n\nرئیس بازجو حتماً چیزهای بیشتری می‌داند. اگر پیدا کنیم شورشیان را کجا برده‌اند، شاید هنوز برایشان امیدی باشد.", o = { "کشتن Questioner Xen'daan", "گردنبند Sombersong" }, p = "با ریسک به راه افتادن دل‌مان... به نظرت ممکن است Veraan بین آن‌ها باشد؟\n\nمی‌توانم حالا رو در رویش بایستم؟ بعد از جنایت‌هایی که به نام Void کرده؟", c = "<name>! این گردنبند مال Veraan است! Veraan همان Sombersong است!" }
WoWFQ[90848] = { t = "او آتش را روشن کرد", d = "Veraan حتماً میان شورشیانی است که به Shadowguard Point برده‌اند.\n\nروح آتشین‌اش من را به شدت مغرور می‌کند!\n\nآمده بودم تا نوعی بدرود بگویم.\n\nآمده بودم تا خواهرم را پیدا کنم.\n\nشاید هنوز دیر نشده، <name>!", o = { "در Shadowguard Point با Kifaan دیدار کن." }, c = "جوهر Veraan ممکن است توسط Shadowguard پیچ خورده باشد، اما شورش به من امید می‌دهد.\n\nممکن است مخالفان را به‌کلی از چنگ Void رها ساخت؟" }
WoWFQ[90851] = { t = "خوردن یکدیگر", d = "به نظر می‌رسد Shadowguard هیچ گلایه‌ای از قفس کردن و شکنجه هم‌نوعانشان ندارد.\n\nآخرین چیزی که می‌خواهم خشونتی دیگر میان مردم K'aresh است، اما بهتر است به رحمت آن‌ها بیفتد تا ما.\n\nکارشان را با مهار بعضی از Shadowguard‌ها به هم بزن.", o = { "کشته شدن مهندسان و آغشته‌کننده‌های Shadowguard" }, c = "خشونت به‌ندرت بهانه جشنی است، اما خوشحالم که دست‌کم سرعت این جنایت‌ها را کند کردیم." }
WoWFQ[90852] = { t = "پالس تکنومغناطیسی", d = "خیانتکاران را در محفظه‌های سکون نگه می‌دارند.\n\nاین قفس‌ها را قبلاً دیده‌ام. طراحی‌شان کارآمد اما شکننده است. با کوچک‌ترین نوسان انرژی از کار می‌افتند.\n\nظرف‌های انرژی جرقه‌زن پراکنده در اطراف را پیدا کن و به سمت محفظه‌های سکون پرتشان کن. با هدف‌گیری درست، از کار می‌افتند و خیانتکاران آزاد می‌شوند.", o = { "آزادسازی Betrayerهای در قفس", "آزادسازی Veraan", "جمع‌آوری Crackling Energy Vessel" }, c = "ممنونم، <name>. کمکم کردی خواهرم را دوباره ببینم. در برابر این، هیچ‌وقت از عهده جبرانش برنمی‌آیم.\n\nVeraan عوض شده. خشمگین. شکنجه‌شده با ناامیدی. باید با احتیاط قدم برداریم." }
WoWFQ[90858] = { t = "سرکوب ستمگران", d = "ما را آورده بودند تا به خشم Soulbinder D'zaar برسیم. او این‌جا فرمانده Shadowguard است. از قدرت Voidstorm برای بدل کردن روح‌ها به انرژی استفاده می‌کند و بعد آن را می‌بلعد.\n\nاو و طرفدارانش به هم‌نوعان‌مان خیانت کرده‌اند!\n\n<Veraan grimaces in pain as the Void courses through her.>\n\nباید جلویشان گرفته شود... دستگاه‌هایشان از هم بچیند... اراده‌شان بشکند...\n\n<name>... همه‌شان را نابود کن!", o = { "اخلال در عملیات Shadowguard" }, p = "<Veraan trembles with rage.>\n\nاین هم‌نوع‌کشان حاضر بودند خودی‌هایشان را قربانی کنند. و در ازای چه؟ اراده Xal'atath؟", c = "هر بار که نگاه‌مان گره می‌خورد، تردید Kifaan را حس می‌کنم. از من می‌ترسد..." }
WoWFQ[90860] = { t = "آزاد کردن از بند", d = "شورشیانی مثل ما را پیش Soulbinder D'zaar می‌آورند. او هیچ خیانتکاری را تحمل نمی‌کند.\n\nسرنوشت ما قربانی شدن بود--روح‌های‌مان به انرژی بدل می‌شد. D'zaar با استادی در arcane گدازه‌ی این روح‌ها را کار می‌کند تا ببلعدشان!\n\nوقت کمی داریم. فشار Void را از درون حس می‌کنم. اگر قرار است با خشونت از این زندگی برویم، D'zaar و گدازه‌اش هم با ما می‌روند!", o = { "کشتن Soulbinder D'zaar" }, p = "فشار دارد زیاد می‌شود... دیگر نزدیک است...\n\nو بگذار، اصلاً لایق زندگی‌ام هستم؟ بعد از همه این‌ها، از من، یک عضو Shadowguard، چه خواهند گفت؟\n\nفکر می‌کنی Kifaan می‌تواند روزی مرا ببخشد؟", c = "Shadowguard همان شد که لایقش بود.\n\nاما من بی‌گناه نیستم، <name>. حتی حالا هم سایه‌هایی در درونم لانه دارند.\n\nبرای امنیت همه، بهتر است بروم." }
WoWFQ[90866] = { t = "زبان جهانی", d = "برای رفتن به خانه، آب زندگی. لازم.\n\n<Tul'amar attempts to discern if you understand what she's talking about with a look. After a pause, she opts to stab her own fingertip with the end of her staff and then displays a bead of her blood to you.>\n\nاین. از اینجا. از جنگ. جنگ، Void. Void، قدرت. با قدرت، خانه.\n\n<She shows her fangs with an exaggerated snarl before pantomiming a claw swipe.>\n\nآب زندگی. از جانور. زیاد. خب؟", o = { "خون شکارچی" }, p = "تو. نمرده‌ای؟ خوب.", c = "خون! این خون است. خب؟\n\n<She looks to one of her kin, who assures her that she's got the right word this time.>\n\nخوب. حالا ببین." }
WoWFQ[90872] = { t = "خیس از آن", d = "<Tul'amar looks away from the blood-soaked and mortified Juras and towards the portal as it flickers to life. She reads it with her powers of the arcane.>\n\nخوب. خون خشن... خشن؟ خشن، قدرت. زیاد لازم. حالا، برادر و خواهرها.\n\n<She gestures to the blood in your possession, and then to her people. Many of them return wary looks your way.>\n\nتو بتوانی. من بگویم.\n\nبعد، برو بیرون. از من ببین.", o = { "پاشیدن خون بر برون‌جهلی‌ها", "جلوی Improvised Waygate روی خودت خون بپاش" }, c = "خوب. حالا، بیشتر. برادر و خواهرها، کمک.\n\nو مردانِ Void، بکش." }
WoWFQ[90873] = { t = "این لذت‌های خشونت‌آمیز", d = "برادر و خواهر. اینجا. کمک.\n\n<Tul'amar connects her thumb and index finger on both hands to make a chain. Then, she breaks the link with a sharp gesture.>\n\nچطور؟ نشان بده.\n\n<She then produces a glimmering arcane relic and holds it over her gauntlet. She spends a portion of her arcane energy Into it. Its newly activated magic forces the straps holding her glove in place loose.>\n\nاستفاده.", o = { "آزادسازی Master's Prospect", "فرستادن احضارشده ناخواسته به خانه", "Relic of Liberation (Provided)" }, c = "<Tul'amar tilts her head at the freed draenei hiding behind her.>\n\nفهمیدم. خوب. تو خوب." }
WoWFQ[90874] = { t = "پایان‌های خشن‌شان", d = "برو خانه. چطور؟\n\n<She offers a dramatic flourish with her fingertips, producing some arcane sparks. Then, she makes an X with her index fingers.>\n\nاز من؟ نه. از آن‌ها.\n\n<Tul'amar gestures to a group of voidwalkers up ahead. She then draws her thumb across her neck.>\n\nکشتن. و.\n\n<She reaches into a pouch on her hip and retrieves a cracked stone of domanaar make. It looks like a spell reagent of some kind.>\n\nمثل این. لازم.", o = { "نشان Abductor" }, p = "<Tul'amar holds still, even as you approach.>", c = "<She counts out the portal runes in your possession and nods in approval.>\n\nخب. خوب." }
WoWFQ[90875] = { t = "میان دنیاها", d = "مرد Void. کلید دارد. لازم. کلیدِ خانه.\n\n<Tul'amar gestures down the way to the northwest. She grimaces back at her injured kin.>\n\nبرگردیم، ما. صبر. امید. برای تو.", o = { "پیدا کردن Lodestar of the Great Dark.", "بازگشت به Exiles' Hovel", "قرار دادن Lodestar of the Great Dark", "تماشا: خانه" }, p = "<Tul'amar smiles sadly at her people.>", c = "بمان. من باید. مردان Void، برادر و خواهرها را پیدا نکنند. تمامش کنم، باید. تنها من.\n\nتو، خوب. دوست. اما. اعتماد، نمی‌شود. اعتماد. فقط وقتی برادر و خواهرها در امنیت.\n\n<She then holds her staff forward, offering it to Juras. Though he seems reluctant to take it, Tul'amar does not waver.>" }
WoWFQ[90910] = { t = "تاریکی فراگیر", d = "حضوری هولناک از همان لانه در جنوب‌شرقی اینجا صدایت می‌کند. خیلی از ren'doreiهای گیجی که در اردوگاه می‌بینی در یک مأموریت شناسایی زیر قدرت خامش له شدند.\n\nبا هم برویم و ببینیم آیا می‌شود از هر چه در آن زندگی می‌کند استفاده‌ای کرد. در نبرد با Xal'atath نمی‌توانیم قدرتی را پس بزنیم.\n\nاما قبل از آن: به Kalgorg نیاز چندانی ندارم. Voidstorm voidwalker مرا سرکش و نافرمان کرده. در قربانی کردنش کمکم کن. به هر انرژی Void‌ای که بتوانیم نیاز خواهیم داشت.", o = { "قربانی شدن Kalgorg", "[DNT] Kill Credit slain", "Reliquary of Darkness (provided)" }, c = "Kalgorg تا این پایین آمد، اما بی‌آمادگی با آن روبه‌رو نمی‌شوم.\n\nاین هیولای نافرمان کوچک. فکر می‌کند بعد از بیست سال، می‌تواند همین‌طور بلند شود و برود؟" }
WoWFQ[90914] = { t = "زاده‌شده برای کشتن", d = "آه، <name>. از وقت‌هایی که با هم داشتیم لذت بردم. برای بیشترش تشنه‌ام.\n\nکاش بیشتر از ذائقه‌ام به طعم رنج فانی‌ها مرا می‌شناختی. یکی از بزرگ‌ترین لذت‌های من، جان بخشیدن به قدرت Void در قالب اشیا و سازه‌های گوناگون است. اشتیاق من است--هنر من.\n\nبگذار نشانشت بدهم. اول، به قدرت نیاز داریم. البته که تو خوب می‌دانی چطور: بکش، بکش، بکش.", o = { "Void Essence (Voidstorm)" }, p = "احساس غریبی است. انگار... به تو کشیده می‌شوم. باید از حضور جذابت باشد.", c = "وای، چه موفقیتی دلخراش و دلپذیر.\n\nعلاقه‌مندم با هم کار کنیم. باید بیشتر از مردممان بدانی و قدرت‌های بیشتری از من ببینی." }
WoWFQ[90915] = { t = "هنرِ پرخاشگری", d = "با آنکه ما domanaarها بیشتر به رهبری ارتش‌ها و لذت بردن از نبرد شناخته می‌شویم، چیزهای دیگری هم هست.\n\nخیلی‌ها، مثل خودم، از تسلط‌مان بر Void لذت می‌بریم که آن را به ساختمان‌ها و اشیایی که می‌بینی شکل دهیم.\n\nبه نظرت Xal'atath چطور یاد گرفت آن برج عظیمش را بسازد؟ تیزهوش است.\n\nبگذار کارهایم را به تو نشان بدهم.", o = { "شروع با صحبت کردن با Decimus", "آهنگری تیغه", "Light Shard", "آغشته شدن تیغه به Light" }, p = "چه عالی که کمی با هم وقت بگذرانیم. شما فانی‌ها به‌طرز عجیبی جالب هستید... تو از همه بیشتر.", c = "این تیغه را هدیه من به تو حساب کن. با هم کاری می‌کنیم از تو سلاحی واقعی از جنس نابودی بسازیم." }
WoWFQ[90916] = { t = "جست‌وجو برای نابودی", d = "به‌هم‌تنیدن Light و Void کار ساده‌ای نیست. حاصلش ناپایدار است، پس باید به پختنش ادامه دهیم.\n\nاین تیغه را در خون دشمنانمان سرد می‌کنیم.\n\nبعضی از domanaarها در تلاش‌اند Nexus-Point Xenas را پس بگیرند و دوباره به کار بیندازند. برای مردم تو خوب نیست. فرض می‌کنم بخواهی جلویشان را بگیری.\n\nشما فانی‌ها چه می‌گویید؟ دو گنجشک با یک سنگ؟", o = { "در Nexus-Point Xenas با Decimus دیدار کن." }, c = "این Nexus-Pointها زمانی چشمه‌های قدرت برای ما domanaarها بودند، خیلی قبل از اینکه Xal'atath ما را براندازد.\n\nروزی دوباره چنین خواهند شد." }
WoWFQ[90917] = { t = "برداشت‌گر درندگی", d = "تیغه گرسنه است! خون دشمنانمان به پایدارتر و تیزتر شدن سلاح تازه‌مان کمک می‌کند.\n\nباید تیغه را درون چند جسد فرو ببری. پس اول باید جسد بسازی.\n\n<Decimus's smile grows broader.>\n\nدر این کار خوبی، نه؟", o = { "سرد شدن Nascent Blade در خون", "Nascent Blade (provided)" }, p = "هیولاهای بومی این سرزمین درنده و خشن‌اند. خون‌خواهی‌شان Void را به اینجا کشید، پس طبیعتاً... ما اینجا مثل خانه‌مان است.", c = "خیلی خوب.\n\nمی‌دانم شما فانی‌ها نگران چیزهایی مثل توازن زیستی و نسل‌کشی گونه‌ها هستید.\n\nنگران نباش: هیولاهای اینجا به‌اندازه‌ای که بی‌رحم‌اند، بی‌شمارند." }
WoWFQ[90918] = { t = "هیچ‌کس نابخشوده نیست", d = "از خیلی قبل از ماجراجویی کوچک‌مان، Nexus-Point Xenas همیشه ضعیف‌ترین حلقه بود. جانوران اینجا یک‌دنده و قدرتمندند، همیشه عمیق‌تر و عمیق‌تر به درون فشار می‌آورند.\n\nبعضی از domanaarها می‌خواهند Nexus-Point را پس بگیرند. آن‌ها را می‌شناسم: تنبل‌مزاج‌هایی که برای خرده‌نانی می‌جنگند. مطمئن شویم شکست بخورند.", o = { "کشتن Noxian", "کشتن Averus", "کشتن Tenebre" }, p = "Noxian، Averus و Tenebre... همگی چاپلوس‌های Xal'atath، مثل اکثریت هم‌نوعان‌مان. حیرت می‌کنم هر کدام چقدر صبر می‌کردند قبل از خیانت به او.\n\nحیف که هرگز دست به تلاش‌شان نمی‌بینیم.", c = "آه، چه جالب، دیدار با دشمنان قدیمی.\n\nما domanaarها زمانی ساختارهای قدرتی پیچیده داشتیم. هر domanaar فقط برای خودش می‌جنگد، اما اغلب سودمند است که خود را با دیگران همراه کنی. موقتی، البته.\n\nقدرتمندترین‌های ما High Lordها بودند. وقتی Xal'atath آمد... همه‌شان را به نمایش گذاشت. آن صحنه چنان تأثیرگذار بود که از ما domanaarها نه فقط ترس بیرون آورد، بلکه چیزی شبیه وفاداری.\n\nبعضی‌مان. نه همه‌مان." }
WoWFQ[90919] = { t = "دیویی که شکست خورد", d = "تیغه سر می‌خورد. برای دگردیسی بعدی‌اش آماده است.\n\nفقط رهبر، Vortensiun، باقی مانده است.\n\nاو را می‌شناسم. روزی برای شکست دادن رقیبی با هم پیمان بستیم. وقتی وقت خیانتش رسید، کاری ناشیانه کرد.\n\nگذاشتم زنده بماند، تا طعم پشیمانی‌اش را بچشم.\n\nحیرت می‌کنم آن درد چقدر پخته شده باشد؟ بیایید بفهمیم. وقتی تیغه در جوهرش پخته شود، قدرتی تازه می‌روید.", o = { "کشتن Vortensiun" }, c = "به حرف‌های Vortensiun درباره غذا اعتنا نکن.\n\nدوستان خوبی داریم می‌شویم، نه؟" }
WoWFQ[90920] = { t = "گرمای روح", d = "از منظره لذت می‌بری؟\n\nتیغه حالا قوی‌تر است، اما هنوز کامل نشده. سلاحی شایسته تو جز بی‌نقصی نمی‌طلبد.\n\nاما بگذار لحظه‌ای آرام بگیریم. می‌دانم شما فانی‌ها به... گپ‌های دوستانه برای بهتر شناختن هم علاقه دارید.\n\nمفهومش را می‌شناسم، اما دوست دارم ببینم در عمل چطور است. مفیس می‌کنی؟", o = { "با Decimus صحبت کن" }, c = "شگفت‌انگیز است که چطور بی‌درنگ اطلاعات ظریف درباره خودت می‌دهی.\n\nانتخاب می‌کنم باور کنم دروغ نگفته‌ای. حالا دیگر دوستیم، تو و من. مفهوم فانیِ جالبی است." }
WoWFQ[90922] = { t = "بیداری افتادگان", d = "<The shade flickers. You can barely make out its whisper.>\n\nتو... ول کردی‌ام... تا بمیرم...\n\n<Its arm reaches toward you, then dissipates. Somehow, the presence is a familiar one. You feel that you know this spirit.\n\nYou see more flickers in the distance. What are these shades?>", o = { "آزادسازی Familiar Shade", "آزادسازی Glowering Shade" }, p = "چه جای عجیب و هولناکی. نگران نباش--اگر دوست داری بیشتر حرف بزنی تا آرام بگیری... من همین‌جام برایت.", c = "واقعاً متأسفم که باید چنین چیزی را تحمل می‌کردی. حرف‌های این ارواح دلخورت کرده، نه؟\n\n<Decimus peers at you.>" }
WoWFQ[90923] = { t = "چوپان ترس", d = "سفرمان ادامه دارد... آخرین میدان نبرد. اینجا جانوران درنده فراوانی هست. Void آن‌ها باز هم تیغه را سیراب می‌کند.\n\nو قدرت تازه تیغه فقط با نزدیک شدن، Void آن‌ها را به درون خود می‌کشد!\n\nاما اینجا فرق دارد. شاید چیزهایی ببینی که انتظارش را نداری.\n\nحواست جمع باشد.", o = { "جذب Void Essence در Gnawing Reach", "آغشته شدن بیشتر تیغه به Unstable Light", "بازگرداندن تیغه به Decimus" }, p = "حواست پرت نشود، خوب؟ همه این‌ها وقتی ارزش دارد که سلاحی نیرومند در دست داشته باشی.", c = "بالاخره..." }
WoWFQ[90924] = { t = "پایان پلید", d = "زمانش رسیده. آخرین قدم.\n\n<Decimus pauses, savoring something.>\n\nبگذار بزرگ‌ترین سلاحی را که هم‌نوع تو دیده بسازیم.", o = { "تعقیب Decimus", "بازجویی از Decimus" }, p = "صبر تو... قابل قدردانی است.", c = "تیغه، همان‌طور که قول دادم. دیدی؟ هرگز قصد نداشتم برای خودم نگهش دارم. حتی هر شکلی که برایت مناسب‌تر باشد به خودش می‌گیرم.\n\nطعم رنج تو تنها چیزی بود که می‌خواستم." }
WoWFQ[90962] = { t = "یورش Stormarion", o = { "تکمیل کل رویداد Stormarion Assault", "موج 1 کامل شد", "موج 2 کامل شد", "موج 3 کامل شد", "[DNT] Kill Credit slain", "فعال شدن موقعیت دفاعی" } }
WoWFQ[91145] = { t = "قهرمانان به‌اسارت‌درآمده", d = "یک domanaar خطوط پشتی‌مان را آزار می‌داد. با بقیه void beastها فرق داشت... انگار می‌جنگید نه اینکه بازی کند. هم‌قطارم، Callum، گروهی را برای شکارش برد. دیگر برنگشتند.\n\nCallum یک Arathi واقعی است. اینجا نمی‌افتد--می‌دانم.\n\nفرمانده Lightblood حاضر نشد گروهی برای جست‌وجو بفرستد. گفت تفاوتی است میان شخصی و مهم. خب، Vanguard می‌تواند جنگش را داشته باشد، اما من دنبال Cal می‌روم. مسیرش را می‌دانم، اما به‌تنهایی نمی‌توانم جست‌وجو کنم.", o = { "پیدا شدن گروه مفقود", "بررسی اجساد", "کشتن Confessor Revik", "کشتن Knight Riandron", "کشتن Scout Danna", "رسیدن به Anais" }, c = "جانوران Imperia به سمت‌ام ریختند. ردشان را گم کردم.\n\nنباید تو را جا می‌گذاشتم، اما دیدن آن هیولا که Callum را کنترل می‌کند... او را از دست نمی‌دهم. تا وقتی نفسم می‌کشد." }
WoWFQ[91146] = { t = "نوری سوسوزن", d = "ردپاهایی از Light اینجا حس می‌کنم--کم‌سو، پراکنده روی دشت، اما بی‌تردید. مال Callum است. Light او را مثل Light خودم می‌شناسم.\n\nآن domanaar یک هیواست: دیگران را مثل اسباب‌بازی به کار می‌گیرد، به هم می‌کوبد تا بشکنند. پیدایشان می‌کنیم، <name>، و بعد آن void beast را خاکستر می‌کنم.\n\n<Anais grips her spear.>\n\nیک چیز در هر لحظه. Light را پیدا کن، و Callum را پیدا کرده‌ایم.", o = { "پیدا شدن رد Light", "Tinder Box Callum", "سپر Callum", "گردنبند Callum" }, p = "او قوی است. هر چه بکند، تاب می‌آورد. باید تاب بیاورد.", c = "دارند آزارش می‌دهد، یکی پس از دیگری به نبرد می‌اندازدش. وقتی برای جست‌وجوی کل این دشت لعنتی نداریم.\n\nنمی‌توانم تمرکز کنم. جادوی Void اینجا بیش از حد آشوبناک و بی‌ثبات است." }
WoWFQ[91147] = { t = "پاره کردن بند‌هایش", d = "Revik، Riandron، Danna... آن domanaar کاری کرد همدیگر را بکشند. جانداران اینجا با همین Shadowgraftها بسته‌اند: همان جادوی پیچ‌خورده.\n\nاگر Imperia این‌طور قربانیانش را کنترل می‌کند، باید راهی برای جدا کردنش پیدا کنیم. جانوران را مهار کن و من تلاش می‌کنم بند‌هایشان را بشکنم. اگر با Void آهنگری شده، Light باید بتواند بر آن غلبه کند.", o = { "تلاش برای جدا کردن Shadowgraftها", "تلاش اول", "تلاش دوم", "تلاش سوم", "تلاش پنجم" }, p = "خم کردن موجودات دیگر به میل خودش؟ این domanaar هیولایی پیچ‌خورده است. سر و کلاهش را می‌گذاریم.", c = "جدا کردن Shadowgraftها می‌کشدشان... Light چه سودی دارد اگر نتواند یک نفر را نجات دهد؟" }
WoWFQ[91148] = { t = "بند کشیده‌شده", d = "وقتی Light خواند، هر دوی‌مان را خواند. چرا؟ تا Callum روی سنگی زخم‌خورده از void بمیرد؟\n\nاینجا نمی‌توانم فکر کنم. تمام چیزی که می‌بینم این است که Callum دارد از خون خالی می‌شود. بیا، به اردوگاه برگردیم. با وسایلش باید بتوانم پیدایش کنم.\n\nبعدش... نمی‌دانم. اگر بند‌های shadowgraft را نشکنیم، مهارش می‌کنیم و اگر لازم شد می‌کشیمش تا Silvermoon. او را از دست نمی‌دهم.", o = { "تجمع در اردوگاه", "با Anais صحبت کن", "پیدا شدن Callum Ashvow" }, p = "...", c = "رسیده بودم بهش. یک فرو بردن نیزه و تمام می‌شد... اما هنوز همان Cal است--حتی با آن هیولا که کنترلش می‌کند.\n\n<Anais clutches at ragged cut in her side. Blood and foul Void magic flow from the wound in equal measure.>\n\nببین دوباره دنبالش دویدن چه بلایی سرم آورد." }
WoWFQ[91149] = { t = "من را اینجا دفن نکن", d = "می‌دانستیم پیر با هم نمی‌شویم، اما فکر می‌کردم وقت بیشتری داریم.\n\n<Anais coughs, blood pooling beneath her. Flecks of the Void shimmer in the spreading crimson.>\n\nنگران نباش. نمی‌ترسم. به خودم قول داده بودم بدون او به خانه برنگردم... یک شب در تخت خالی نخوابم. فقط دارم به همان قول عمل می‌کنم.\n\nنگذار او را داشته باشد. Tinder boxاش را بردار. می‌دانی چه باید بکنی.", o = { "Light-Infused Tinder Box", "استفاده از Void Portal", "شکست Callum Ashvow", "نابودی Imperia" }, p = "پدر و مادرم همیشه می‌گفتند عاشق شدن یک انسان به دل‌شکستگی ختم می‌شود.\n\n<She doesn't lift her head.>\n\nوقت هیچ‌وقت کافی نیست، نه؟", c = "حس کردم. وقتی تو--وقتی او--ممنونم. ببخشید. فکر کردن دارد سخت می‌شود.\n\n<She accepts the tinder box and holds it to her chest. Her eyes seem to focus on something you can't see.>\n\nCal...؟ خیلی خسته‌ام. بیا بریم خانه.\n\n<Anais slumps over, her hand falling away from the wound at her side. She is at peace.>" }
WoWFQ[91207] = { t = "Prey: شکارچی رأس", d = "دشمنان را شکست بده تا طعمه اصلی‌ات را بیرون بکشی", o = { "کشته شدن جانداران", "دفاع در برابر کمین" } }
WoWFQ[91339] = { t = "خفه در گهواره", d = "اولین imp‌ام را در لنجی کثیف و مه‌گرفته زیر Murder Row احضار کردم، بعد از دوازده بار شکست. هر بار، بیشتر در خود می‌کاویدم که چه چیزی باعث می‌شود قدرت‌هایی به‌اصطلاح برتر در برابر فانی‌ها زانو بزنند. بالاخره بعد از خیس کردن دست‌هایم با خون داغ یک خرگوش جوان موفق شدم. Bloodthistle دیگر هرگز مرا سیر نکرد. از آن به بعد فنم را پخته‌تر کردم. به بچه‌های این جانوران برو. انرژی‌شان را به [reliquary of darkness] من بکش. از قربانی‌شان، قدرت شکست Kalgorg را می‌کشیم بیرون.", o = { "کشته شدن NPC #252849", "تخلیه جانوران جوان", "به Lucia بگو نمی‌خواهی بچه‌ها را بکشی", "[DNT] Kill Credit slain" }, p = "از قدرت نترس، <name>: از کسانی بترس که آن را در دست دارند.", c = "این هم نظم طبیعی است." }
WoWFQ[91340] = { t = "به بهانه خشونت", d = "مثل خیلی از جادوان، دیوهای‌مان را با شرط‌های قراردادی بند می‌کنم. باید می‌فهمیدم Void و خشونت این دنیا می‌تواند قوانینی را که بدیهی می‌انگشتم تغییر دهد. Kalgorg با همان قدرت بند‌هایش را شکست و به قرارداد‌مان پایان داد.\nوقتی با Kalgorg روبه‌رو می‌شویم، باید بوی خون و خشونت با ما باشد. جانورانی را که پیدا می‌کنی بکش تا به Kalgorg نشان دهیم حاضریم همین کار را با خودش بکنیم. تسلط بر Void در یک پلک زدن پیدا و گم می‌شود.", o = { "کشته شدن حیات‌وحش", "Trigore Denguard", "Netherhunter Infestor", "Scavenging Biledrinker", "Bane of the Vilebloods" }, c = "<Lucia looks you over and then rewards you with a cruel smile.>\nعالی. همان‌قدر که به نظر می‌رسی، توانایی هم داری." }
WoWFQ[91341] = { t = "بی‌حد", d = "حالا، پایین می‌رویم. انرژی Void آن پایین شبیه هیچ چیز دیگری نیست؛ انگار خود جاذبه هم در برابر Void تسلیم می‌شود. وقتی وارد غار شوی، نفوذش بر تو مستولی می‌شود. Kalgorg از قبل جانداران درون را کشته و از قدرت‌شان گرایده است. مرگ‌های خشن‌شان نوعی زمین نفرین‌شده به جا گذاشته، اما باید جلو برویم و قدرت درون را تصاحب کنیم. reliquary را تا لبه پر کن. نمی‌دانم از voidwalkerم چه انتظاری داشته باشم. به تمام قدرتی که بتوانیم جمع کنیم نیاز داریم.", o = { "جمع شدن Void Power", "کشته شدن Void Tear", "کشته شدن Shadow Essence", "کشته شدن Shadow Essence", "وارد شدن به Gravity Anomaly برای سفر به بالا", "پر شدن Reliquary of Darkness" }, p = "رد پای کشتاری که به جا گذاشته... تقریباً به من افتخار می‌کند.", c = "Kalgorg پیش روی ماست. حالا قدرتی را که جمع کرده‌ای خرج می‌کنیم تا آن را پس بگیریم." }
WoWFQ[91343] = { t = "پاداش جاه‌طلبی", d = "reliquary را با قدرتی پر کردی که می‌توانم از آن بهره بگیرم. حالا نتیجه آماده‌سازی‌های‌مان را می‌رویم.\n\nKalgorg همان بالای سر است، مشغول نوشیدن از جانوری که زمانی این غار لانه‌اش بود. Kalgorg را تضعیف کن و من همان‌طور که سال‌ها پیش کردم بندش می‌زنم.", o = { "مهار شدن Kalgorg" }, p = "...", c = "Kalgorg انرژی Void زیادی از آن غار بلعید، یعنی نفوذش کمتر می‌تواند بر هم‌نوعانم مستولی شود. به نظرم کار خوبی هم شد.\n\nباید کمترین تعریفی از Kalgorg بکنم. اگر من یک void beast مهارشده بودم، من هم فرار می‌کردم. به همین، احترامش را دارم.\n\n<Lucia turns to Kalgorg with a sharp smile.>" }
WoWFQ[91363] = { t = "برداشت تاریکی", d = "تو... خودت را مفید کن.\n\nبه‌عنوان استاد جانوران هولناک، کار من این است که از این بچه‌ها هیولاهای ترسناک بسازم. آن‌ها را به جان هم می‌اندازم و روز به روز خشن‌تر می‌شوند.\n\nاما الف‌های اینجا اصرار دارند با کمی... مهربانی و مراقبت نتیجه بهتری می‌گیرم. بگذار امتحانش کنیم.\n\nاین کوچولو Fidoficus است. تو با او مهربانی و محبت کن، بعد می‌بینیم چقدر وحشی می‌شود.\n\nچند تا خوراکی خوشمزه برایش جمع کن و پیش من برگرد.", o = { "Void-Infused Morsel", "Glaring Glowcap" }, p = "این مواد خوراکی، غذایی بسیار مقوی و به همان اندازه خوشمزه می‌سازند.", c = "Fidoficus روزی به درندگی‌اش معروف خواهد شد.\n\nخشونتی را که در او رشد می‌کند می‌بینم.\n\nروزی، حیوان خانگی شایسته‌ای برای یک domanaar مثل من خواهد بود." }
WoWFQ[91380] = { t = "دل جانور", d = "معمولاً جانوران‌ام را با رژیم جسدهای خام و خونین و روح‌هایی که Void از هم می‌پاشد بزرگ می‌کنم.\n\nاما رژیم فانی‌های شما را امتحان می‌کنیم.\n\nشنیده‌ام شما... می‌پزید؟ و این غذا را خوشمزه‌تر می‌کند؟\n\nبکنش. بعد ببرش یک دور این Howling Ridge قدم بزنید. حتی من هم می‌دانم ورزش برای هضم غذا خوب است.\n\nفقط درنده‌ترین موجود لایق خدمت به من است. امیدوارم نه تو، نه Fido ناامیدم نکنید.", o = { "افزودن Uncooked Void Meat به cookpot", "افزودن Unprepared Glowcaps به cookpot", "دادن خوراکی به Fidoficus", "اعمال تسلط بر شکار", "اعمال تسلط بر الف‌ها", "اعمال تسلط بر استخوان‌ها" }, p = "هنوز کوچک است، اما روزی به هیولایی هولناک بدل می‌شود.", c = "درندگی جانور دارد زیاد می‌شود؟\n\nمطمئنم به‌زودی از اطرافیان Howling Ridge درباره خشونتش حرف می‌شنوم." }
WoWFQ[91382] = { t = "قدرتمند و برتر", d = "جانور غذا خورد و ورزش کرد. تصور کن، فانی... روزی آرواره‌اش آن‌قدر بزرگ می‌شود که هزار بار تو را درونش جا می‌دهد.\n\nحالا، پتانسیل واقعی‌اش برای خشونت را آزمایش می‌کنیم.\n\nجانوری است که لانه‌ای در جنوب Howling Ridge را تصاحب کرده.\n\nFidoficus حالا به تو اعتماد دارد. با او برو و شاهد قدرتش باش.", o = { "تماشای کشتن Den-Gorger Zitoc توسط Fidoficus", "کشته شدن Den-Gorger Zitoc", "تقسیم پیروزی با Ravenia" }, p = "Fidoficus ترسناک شده، و شاید تو هم سهمی از رشدش داشته باشی.", c = "بد شد که جانور آخرش به اندازه شما فانی‌ها بی‌چاره و نحیس از آب درآمد.\n\nشایسته یکدیگرید." }
WoWFQ[91417] = { t = "به دنبال Arator", d = "می‌بینم پسرم وقتی‌اش را با زخمی‌ها می‌گذراند. یک لطف ساده به پدرش بکن و ببین به کمک تو نیاز دارد یا نه.", o = { "کنار زخمی‌های پیشتاز با Arator صحبت کن." }, c = "این‌ها ان‌قدر سخت برای ما می‌جنگند. باید هر کاری از دست‌مان برمی‌آید برای حفاظت ازشان بکنیم." }
WoWFQ[91419] = { t = "برتری elementalها", d = "نیروهای گرانشی اینجا می‌توانند قدرت اضافه‌ای بدهند. برو و با آن چند اترئال را از بین ببر.", o = { "شلیک Void Missile به Elementalها یا کشتن بازیکنان" }, c = "کار تمام است." }
WoWFQ[91426] = { t = "قهرمان مردم", d = "فکر می‌کنم فعلاً هر کاری از دست‌مان برمی‌آمد انجام دادیم، <name>. به نقطهٔ بسیج برگردیم.", o = { "با Arator به نقطهٔ بسیج برگرد." }, c = "کار خوبی آن بیرون کردیم، <name>. این بیشترِ چیزی است که همیشه می‌شود امیدش را داشت." }
WoWFQ[91458] = { t = "شکار: شکارچی استقامت", o = { "تعقیب شکارت (1)", "تعقیب (20)" } }
WoWFQ[91523] = { t = "شکار: تهدید پنهان", o = { "Voidsphere توانمندساز نابود شد (5)" } }
WoWFQ[91533] = { t = "آنچه از خود به جا می‌گذاریم", d = "Lothraxion لایق آن بود که با جانش تاوان تکبرش را بدهد. Hieron نه. بدون او من مرده بودم. می‌دانم Maella و Darkglen هم همین حس را دارند.\n\nدفترچهٔ Hieron، همان که برایمان پیدا کردی، دست من رسید. من Hieron را می‌شناختم، اما Astre بهتر می‌شناختش. این دو قرابتی پیدا کرده بودند که به آن رشک می‌بردم. Astre لایق است آن را نگه دارد.\n\nآخرین باری که Astre را دیدم، Hieron در Locus Point زخم‌هایش را بست.\n\nتو وقتی Hieron از دنیا رفت آنجا بودی. باید از قهرمانی و فداکاری‌اش برایشان بگویی.", o = { "متعلقات Hieron جمع‌آوری شد", "متعلقات Hieron را در Locus Point به Riftblade Astre برسان." }, p = "از وقتی اینجا از هم جدا شدیم کمی حالم بهتر شده، اما زمزمه‌ها هنوز عذابم می‌دهند. نیش‌دارند؛ با چیزی که ندارم و جایی که شکست خورده‌ام شکنجه‌ام می‌کنند. و--\n\nصبر کن. این که...؟ این را از کجا آوردی؟", c = "<Astre accepts Hieron's journal and the letter with an empty and distant expression.>" }
WoWFQ[91535] = { t = "خانه، گورِ شیرین", d = "<Astre مدت‌ها در سکوت می‌گذرد و دفترچهٔ Hieron را ورق می‌زند.>\n\nدر دنیایی دیگر کشته شد، در دفاع از شهری که او را نمی‌خواست. آن‌قدر نقشه و آرزو داشتیم که با هم انجام دهیم. حالا...\n\n<Astre ناگهان ساکت می‌شود و نگاهش به صفحات دفترچه خیره می‌ماند.>\n\nآه. دستور چایی که Hieron برایم می‌گفت. ذوق داشت برای خواصش--به آن ملینِ روح می‌گفت. هرگز نرسید دمش کند.\n\nمی‌دانم احمقانه به نظر می‌رسد، <name>. فقط می‌خواهم طعم چای Hieron را بچشم. برگ‌ها باید همین نزدیکی باشند.", o = { "8 برگ Ghostflower را از اطراف پایهٔ Locus Point جمع‌آوری کن.", "برگ Ghostflower (8)" }, p = "<Astre با حالتی بی‌تفاوت دفترچهٔ Hieron را ورق می‌زند.>", c = "کتری را آماده کرده‌ام." }
WoWFQ[91536] = { t = "مثل علف هرزه", d = "<Astre از دفترچهٔ Hieron به نامهٔ پاره‌پاره نگاه می‌کند. حالت چهره‌اش از خشم می‌لرزد.>\n\nالف‌های خون. آن‌ها هم‌قوم ما بودند تا آنکه Void را در آغوش گرفتیم. در نادانی‌شان، ما را تبعید کردند. با این حال راحت از ما می‌خواهند جنگ‌هایشان را بجنگیم.\n\nمی‌گویند ما برای Sunwell خطرناکیم. حقیقت این است که از ما می‌ترسند.\n\nبگذار از چیزی که واقعاً ارزش دارد محافظت کنیم. هر جانوری را که به سراغ آن گل‌ها برای چای Hieron می‌آید بکش. Silvermoon خودش را نجات بدهد.", o = { "کشتن حیات‌وحش اطراف Locus Point.", "حیات‌وحش اطراف Locus Point کشته شد (1)", "Ridge Consumptor کشته شد (20)", "Ridge Scavenger کشته شد (50)", "Predatory Voidscythe کشته شد (10)" }, c = "دقیق مطمئن نیستم قرار است این چای چه کمکی کند. اما به یادداشت‌های Hieron اعتماد دارم." }
WoWFQ[91537] = { t = "مقابله با آن", d = "کتری را روی اجاق گذاشته‌ام. اگر زحمتی ندارد، دم کردنش را به تو می‌سپارم. نباید بیشتر از یک لحظه طول بکشد تا چای آماده‌ی نوشیدن شود.\n\nبگذار اول من امتحانش کنم، چه‌بسا سمّی باشد. من بودم که درخواست چشیدنش را دادم.", o = { "چای Ghostflower را برای Astre دم کن.", "NPC #248770 کشته شد", "چای دم شد", "Shade of Grief کشته شد" }, p = "<Astre پیشانی‌اش را در دست گرفته است.>", c = "فکر می‌کردم با فرو خوردنش می‌توانم خودم را از شرّ این درد خلاص کنم.\n\nتو حتی مرا خوب هم نمی‌شناسی. اما تا همین حالا کار‌های زیادی برایم انجام داده‌ای. متشکرم." }
WoWFQ[91541] = { t = "هیجان‌های مهارنشده", d = "ren'doreiها از همان اوایل یاد می‌گیرند هیجان‌هایشان را بازبینی کنند. اینکه با مهار خود، می‌توانیم Void را مهار کنیم. وگرنه، احساسات سرکوب‌نشده می‌تواند ما را به نابودی بکشاند.\n\nاما همین حالا قدرتِ روبه‌روشدن با احساساتم را حس کردم. شاید می‌توانستم به تنهایی از پسش برآیم... اما چای و یاری تو کار را آسان‌تر کرد.\n\nباید دستور Hieron را با بقیه در میان بگذاریم. کتری‌ای را که دم کردی برمی‌گردانم.", o = { "با Riftblade Astre در Howling Ridge دیدار کن." }, c = "هرگز در جادو بهترین نبودم، اما ورد‌هایم دست‌کم چای را گرم نگه می‌دارند." }
WoWFQ[91542] = { t = "شهری در درون من", d = "نمی‌توانم بگویم نوشیدن این چای تجربهٔ خوشایندی است. اما کمک می‌کند. می‌خواهم بقیه هم این را تجربه کنند.\n\nاینکه Hieron چنین هدیه‌ای برایمان به جا گذاشت، خیلی... شبیه خودش است. او همیشه همین کارها را برای دیگران می‌کرد. برای من.\n\nچای را با بقیه در میان بگذار، بعد به من در Obscurion Citadel بپیوند. می‌دانم تنها ماندن در جایی مثل آنجا کارِ خردمندانه‌ای نیست.", o = { "چای Ghostflower را در Howling Ridge به Umbric، Maella و Sideras تعارف کن.", "به Umbric چای داده شد (1)", "sideras tea credit (1)", "به Sideras چای داده شد (1)", "به Maella چای داده شد (1)" }, c = "پس اینجاست که اتفاق افتاد.\n\nتنها برای سوگواری آمده بودم. اما... چیز دیگری هم اینجا هست." }
WoWFQ[91543] = { t = "بازپس‌گیری کنترل", d = "این دنیا خشن و خطرناک است، اما برای چیزها نظمی دارد. بعد از اینکه تو و بقیه، domanaar‌ای را که این دژ و میدان نبردش را اداره می‌کرد انداختید، زنجیرهٔ غذایی باید به هم ریخته باشد.\n\nHarrowerها آسمان را اشباع می‌کنند و افق را تاریک می‌سازند. نگرانم اگر رسیدگی نشوند، به دنبال شکارگاه‌های تازه‌ای نزدیک سکونتگاه‌هایمان بگردند.\n\nآن‌ها را به من نشان بده تا با قلاب پرتابی‌ام به زمین بکشمشان. تجهیزات بقای Hieron همان‌طور که همیشه، وقتی لازم است ثابت می‌کند که به کار می‌آید.", o = { "کشتن Harrowerها و siphoidهای پرنده در Obscurion Citadel.", "علامت دادن به Astre برای قلاب کردن یک harrower یا siphoid (1)", "harrowerها و siphoidهای پرنده کشته شدند (8)", "Prowling Harrower (1)", "Bleakwing Harrower (1)", "Siphoid Drone (1)", "Scavenging Harrower (1)", "Obscurion Broodlord (1)" }, p = "کارشان تمام شده؟", c = "شاید بی‌آنکه این هیولاهای پرنده شکارچی‌شان باشند، نژاد تازه‌ای از جانوران سر برآورد. بیایید امیدوار باشیم به‌جای ما سراغ domanaarها بروند." }
WoWFQ[91544] = { t = "انرژی‌های آشنا", d = "می‌دانم Hieron اینجا مرد، اما پژواک دیگری را حس می‌کنم--از یک جدال بزرگ، جایی که Void به Void برخورد کرد. Hieron باید تیغش را با کسی... چیز دیگری تلاقی داده باشد. چیزی که هنوز همان بیرون است.", o = { "در Obscurion Citadel همراه Riftblade Astre در Void Riftها فالگیری کن.", "Echo of a Last Stand بازرسی شد (1)", "Second Echo ردیابی شد (1)", "Third Echo ردیابی شد (1)", "Fourth Echo ردیابی شد (1)", "Final Echo ردیابی شد (1)" }, c = "آن domanaar دارد پرتالی به سوی Silvermoon باز می‌کند! این دیگر چطور ممکن است؟" }
WoWFQ[91545] = { t = "قوی‌تر از قبل", d = "باید همان هیولایی باشد که Hieron را کشت. دارد درگاهی از پشت باز می‌کند تا نیروهای Void به داخل Silvermoon سرازیر شوند.\n\nاین شهر لعنتی. برای آن‌ها این کار را نمی‌کنم.\n\nبه Umbric علامت بده. بزن بریم. با هم.", o = { "به Umbric، Maella و Sideras علامت بده", "Notatus the Riftscarred کشته شد", "در Howling Ridge با Riftblade Astre صحبت کن." }, c = "دنیایی غریبه و خشن می‌تواند خانه شود، تا وقتی آدم‌های درستش را داشته باشی.\n\nمن مال خودم را همین‌جا دارم." }
WoWFQ[91557] = { t = "پیامی به Molt", d = "آه، قهرمان! این‌قدر نمونهٔ یکتا برای شناسایی و ثبت اینجا هست که از پس‌اش برنمی‌آیم.\n\nراستش Lady Darkglen از میان برنامه‌های شلوغش وقت گذاشت و یک اکتشاف به منطقه‌ای به‌خصوص خطرناک در شمال اینجا هماهنگ کرد. به قدرتش اعتماد دارم، اما مدتی است نه از او خبری و نه از تیمش و نگرانم شده‌ام. به امید خیر، فقط سرشان گرم تحقیقات خودشان است.\n\nبا این حال، می‌شود لطف کنی Lady Darkglen را در Molt پیدا کنی و حالش را بپرسی؟", o = { "Lady Darkglen را در Molt پیدا کن." }, c = "Verigien تو را فرستاده؟ چه زمان‌سنجی خوبی. اکتشاف ما به مشکلی غیرمنتظره برخورده است." }
WoWFQ[91558] = { t = "گلبرگ‌های مسری", d = "حضوری بیماری‌زای عجیب هم‌نژادهای ren'dorei من را آلوده کرده است.\n\nوقتی رسیدیم، از شادابی رنگ‌های این درهٔ پوسیده و گل‌های خونین فراوانش مسحور شدم. دلم می‌خواست چند تا برای کلکسیونم بچینم... البته برای مطالعه، اما این بیماری در همان برکه‌های آلوده‌ای زندگی می‌کرد که این گلبرگ‌های خونین در آن می‌رویند. شاید به‌طور طبیعی مقاوم‌اند، یا خواصی پاک‌کننده دارند که می‌توانیم برای درمان از آن بهره بگیریم؟\n\nعزیزم <name>، لطفاً با احتیاط برای پژوهشم گلبرگ خونین جمع کن.", o = { "گلبرگ خونین بالغ" }, p = "به‌قدر کافی جمع کردی؟", c = "به‌طرز فوق‌العاده‌ای زیبایند! فقط امیدوارم این گل‌ها سرنخی برای درمان برادرانم داشته باشند." }
WoWFQ[91559] = { t = "آفت‌های مسری", d = "به نظر می‌رسد بیماری در میان حیات‌وحش Molt یک‌نوع پخش نمی‌شود.\n\nوقتی هم‌نژادهای ren'dorei من آلوده شدند، گیج و بی‌پاسخ شدند. جانوران بومی مقاوم‌تر به نظر می‌رسند. گمان می‌کنم بعضی از ساکنان Molt مقاومت قوی‌تری دارند. شاید با بررسی این جانوران بتوانیم اجزایی برای یک معجون شفابخش بیرون بکشیم.\n\nمی‌شود از جانداران نزدیک کبد جمع کنی؟", o = { "کبد ویژه" }, p = "شکار چطور پیش می‌رود؟ آنچه لازم داریم را جمع کرده‌ای؟", c = "شگفت‌انگیز است. سریع کالبدشکافی‌شان کنیم، قبل از اینکه خراب شوند." }
WoWFQ[91560] = { t = "پاک‌سازی کاشفان", d = "امیدواریم بتوانیم از موادی که آوردی درمانی بسازیم.\n\nمعجون پایه را از قبل آماده کرده‌ام، اما حالا باید گلبرگ‌های خونین و کبدهایی که تهیه کردی را با وسواس در آن بریزیم. با کمی پشتکار محاسبه‌شده و اندکی اقبال، باید بتوانیم پادزهری بسازیم و به پیشاهنگان ren'dorei بیمار نزدیک اینجا بدهیم.\n\n<name>، به Blocciniux کمک کن تا مواد جمع‌آوری‌شده را ترکیب کند.", o = { "له کردن گلبرگ‌های خونین", "پودر کردن کبدها", "پادزهر بیماری", "تجویز پادزهر", "بهبود Riftwalker Lorn", "بهبود پیشاهنگ ren'dorei" }, p = "موفق شدی؟ پادزهر اثر کرد؟", c = "Riftwalker Lorn مُرد؟ خبر نگران‌کننده‌ای است.\n\nبه‌خاطر نجات هر تعداد ren'dorei که توانستی، از تو ممنونم." }
WoWFQ[91561] = { t = "بیماری خون‌زاد", d = "بیماری خون‌زاد جهش پیدا کرد!\n\nحاملان لجن‌مانند این بیماری معمولاً زود می‌میرند، اما این نوع تازه حتی بدون میزبان پایدار است. اگر از اینجا فرار کند، می‌تواند ren'doreiهای بیشتری را آلوده کند و در کل Voidstorm پخش شود، یا بدتر از آن، در Azeroth. کل عملیات ما در خطر است.\n\nباید قبل از پخش شدن، جلوی این نوع جهش‌یافته را بگیریم!", o = { "کشته شدن بیماری جهش‌یافته" }, p = "جلوی پخش این بیماری کشنده را گرفتی؟", c = "با سر و کله پید کردن با بیماری جهش‌یافته و پادزهر در دست، باید از شیوع‌های بعدی در امان باشیم. ممنون بابت کمکت، <name>." }
WoWFQ[91565] = { t = "میدان نبرد Voidscar: Grief Spire", d = "تو، قهرمان!\n\nVidious همین‌جا با دشمن دیرینه‌اش، Ziadan، می‌جنگد؛ کسی که بی‌رحم‌ترین و بی‌ثبات‌ترین اعضای Horde را آورده تا برایش بجنگند. قاتلان و خیانتکاران!\n\nرهبران Alliance به فریادهای‌مان برای اقدام و انتقام گوش نمی‌دهند! باید کار را به دست خودمان بگیریم و از Vidious پشتیبانی کنیم.\n\n<Amari looks you up and down and raises an eyebrow.>\n\nو اگر انزجار از Horde نیست که تو را به اینجا می‌کشاند، فکر کن چه اطلاعات ارزشمندی ممکن است با کمک به یک domanaar قدرتمند به دست بیاوری.", o = { "سوار شدن به درگاه Grief Spire" }, c = "آه، یک <class> دیگر از Alliance. چه چیزی تو را به پیش می‌راند، دوست دارم بدانم؟\n\nاین‌همه داستان نفرت‌انگیز شنیده‌ام! Horde خانواده‌ات را قصابی کرد؟ خانه‌ات را نابود کرد؟ در میدان نبرد به تو خیانت کرد؟\n\nیا از همان نرم‌دلان هستی؟ که فقط برای دانش و قدرت به نفع خانه‌ات آمده‌ای، نه انتقام؟\n\nبرایم مهم نیست، تا وقتی که به نام من بجنگی." }
WoWFQ[91566] = { t = "Voidscar Arena: The Hate Spire", d = "Lok'tar ogar, <class>.\n\nاین domanaar، یعنی Ziadan، با دشمن دیرینه‌اش، Vidious، در جنگ است؛ او خون‌خوارترین و کینه‌توزترین اعضای Alliance را برای جنگیدن به نامش به اینجا، به Slayer's Rise، آورده است.\n\nZiadan اکنون به Horde فرصتی می‌دهد تا برای افتخارمان بایستیم. شاید رهبرانمان این درگیری را تأیید نکنند، اما ما کِی گذاشته‌ایم کسی مانعمان شود تا در راه حق نجنگیم؟\n\nحتی اگر شکایتی از Alliance نداری، تلاش‌های Ziadan مانع می‌شود Vidious چشمش را به Azeroth بدوزد. برای گرفتن دستور‌هایت، نزد او برو.", o = { "از دروازه‌ی Hate Spire استفاده کن و نزد Ziadan گزارش بده.", "Portal to Hate Spire گرفته شد" }, c = "تو. به‌نظر می‌رسد برای یک نبرد آماده‌ای.\n\nHorde تو نجیب است. برای افتخار می‌جنگی. برای شکوه. گاهی هم، صرفاً برای لذتش.\n\nستیز جاودانه‌ی تو با Alliance لذیذ است. من لذتش را خواهم برد." }
WoWFQ[91583] = { t = "Voidscar Arena: The Bastion of Valor", d = "Ziadan به‌تازگی دشمنان بزرگ شما، Horde، را به صفوفش افزوده است. با این حال، آنهایی که خانه‌ام را در محاصره گرفته‌اند، هم‌نوعان فانی شما نیستند.\n\nنه، در عوض هیولا‌هایی از Voidstorm می‌بینم؛ تحریف‌شده و سرشار از قدرت. ماجرایی در جریان است. آیا Ziadan نیروی تازه‌ی دیگری هم به ارتشش افزوده است؟\n\nبرو و با این هیولا‌ها بجنگ. هر سرنخی از منبع قدرت تازه‌شان پیدا کردی، برایم بیاور.", o = { "12 عدد Spiteful Shadowgraft را از جانداران وحشی در Bastion of Valor جمع‌آوری کن.", "Spiteful Shadowgraft" }, p = "چه چیزی پیدا کرده‌ای؟", c = "آه، البته! Shadowgraft.\n\nاین فلز موجی از قدرت در موجود جاری می‌کند و او را به جنونی کور و خشونت‌آمیز می‌کشاند. بدون کشتن جانوران نمی‌توان آن را جدا کرد." }
WoWFQ[91597] = { t = "Voidscar Arena: برای Alliance", d = "دژم دوباره محاصره شده... به دست Ziadan! شما Alliance‌ای‌ها به من ثابت کرده‌اید که قوی هستید. مشتاقم شما را در میدان نبرد به کار ببینم. نیروهای خودم می‌توانند از جرئت شما بچشند. این Voidclarion را بگیر و موجودات دون‌پایهٔ void‌ای را که برای من می‌جنگند دلیر کن. بگذار بدانند پشتیبانشان هستی. بگذار شکوه Alliance‌ات را حس کنند!", o = { "نیروهای Griefbound توانمند شدند (8)", "Voidclarion رازآمیز" }, c = "عالی. نبرد آن‌وقت واقعاً متعادل است که به سود من متمایل شود." }
WoWFQ[91598] = { t = "Voidscar Arena: خشونت پیش‌تحریک‌شده", d = "پس Ziadan تا این حد پست می‌شود که از shadowgraft استفاده کند؟ مگر نمی‌تواند خون‌خواهی زیردستان Horde‌اش را به‌قدر کافی برانگیزد؟ دستش دیگر گرم نیست. برای درهم‌کوبیدن او به چنین ارتشی نیاز ندارم. تو را دارم. نشانش بده که چطور انجام می‌شود. پیش از آنکه از محدودهٔ Slayer's Rise بیرون بزنند، نیروهایش را درهم بکوب. مگر می‌شود که مأموریت ارزشمندت اینجا تهدید نشود.", o = { "کشتن بازیکنان یا نیروهای Hatebound", "بازیکنان کشته شدند (7)", "T2 (8)", "T1 (14)" }, c = "چی؟! اگر Ziadan هم توسط موجودات shadowgraft‌شده محاصره شده، یعنی اینکه...\n\nیک مزاحم." }
WoWFQ[91599] = { t = "میدان نبرد Voidscar: کینه‌ای آشنا", d = "وقتش رسیده جنگ را به در خانه Ziadan ببریم.\n\nبدون شک حیوان خانگی محبوب خودش را دارد--کسی از دنیای تو که این درگیری را شخصی می‌گیرد. او به‌خصوص عاشق طعم‌های خشم است.\n\nمن خودم غم دل‌شکن و تیر کشیدن دل را ترجیح می‌دهم، و ثابت خواهیم کرد کدام‌تان فانی‌ها را با قدرت بیشتری سوخت‌رسانی می‌کند.\n\nدر میان نیروهایش جادوی تاریکی‌ای هست که از هم‌نوعان تو کشته بسیار ساخته است. طعم خشمش را در هوا چشیده‌ام.\n\nبرو. از نبرد لذت ببر.", o = { "Manus Deathwake کشته شد" }, p = "...", c = "خیلی خوب. Horde پر است از چنین روح‌های پرکینه و خشنی." }
WoWFQ[91600] = { t = "Voidscar Arena: کنار گذاشتن اختلاف", d = "می‌دانستم که shadowgraft کردن زیر شأن Ziadan است. حاضر نیستم بی‌نهایت طولانی با کسی این‌قدر بی‌فرهنگ درگیری داشته باشم. پس بازی کوچک ما مهمانی ناخوانده‌ای دارد. البته نه تو. عاشق این هستیم که ببینیم چطور برایمان می‌کشی. در دورترین شمال، Voidscar Arena است. آخرین باری که domanaar دیگری خواست میان ما بیاید، آن دژ را ساختند. قرن‌هاست خالی مانده. اگر domanaar دیگری قصد به چالش کشیدنمان دارد، نیروهایش را همان‌جا آماده کرده است.", o = { "دیدار با domanaar در Voidscar Arena در Slayer's Rise." }, c = "پس دشمن ما کیست؟ چه کسی می‌خواهد در غفلت Xal'atath قد بکشد و قدرت بیشتری تصاحب کند؟\n\nTenebre؟ Chrysalius؟ Decimus؟" }
WoWFQ[91603] = { t = "Voidscar Arena: دو در برابر یک", d = "تو. ضعیفه‌ی Alliance.\n\nShadowgraft برای تأمین قدرتش به سرچشمه‌ای پرتوان نیاز دارد—با این همه موجود، احتمالاً بیش از یکی. حتماً همین نزدیکی‌ها هستند. منابع قدرت را نابود کن، بعد در گردنه‌ی بعدی به ما بپیوند.\n\nیادت باشد: اگر این domanaar پیروز شود، فتوحاتش در Slayer's Rise پایان نمی‌یابد. راهی به دنیای مادری‌ات پیدا خواهند کرد. حتی خودِ Azeroth را هم shadowgraft می‌کنند. به این ماجرا پایان بده.\n\nدر این میان، به‌گمانم از همین فرصت برای تماشای ضعف‌های Vidious از نزدیک لذت خواهم برد.", o = { "Graftnode‌های Shadowgraft را در بالای Voidscar Arena در Slayer's Rise تخلیه کن.", "Graftnode of Grief نابود شد", "Graftnode of Hate نابود شد" }, p = "تخلیه شده‌اند؟", c = "این کار مانع گسترش بیشتر پیوند خواهد شد. با این حال، هنوز باید خودمان با آنچه باقی مانده درگیر شویم.\n\nچه دردسری." }
WoWFQ[91605] = { t = "Voidscar Arena: سمت اشتباه", d = "راستش Voidscar Arena یک‌بار دیگر از Void لبریز شده است. یک domanaar بر اینجا حکم می‌راند، شکّی ندارم.\n\nهنوز برای گفت‌وگو پدیدار نشده است. پس آن مزاحم مرموز ما اینجا حاضر نیست. چه خوب.\n\nبگذار تو به این نمایش پایان بدهی. نیرو‌هایشان را نابود کن. منابعشان را نابود کن. و ابزار‌هایشان را علیه خودشان به کار بگیر. بگذار تحقیری را که من نسبت بهشان دارم بچشند.\n\nZiadan و من درباره‌ی این مزاحم تحقیق خواهیم کرد.", o = { "12 هیولای Spiteful را بکش، 4 عدد Graftshaper Tool را به کار بگیر، و 6 عدد Shadowgraft Energy Container را نزدیک بالای Voidscar Arena در Slayer's Rise نابود کن.", "هیولا‌های Spiteful کشته شدند", "Shadowgraft Energy Container‌ها نابود شدند", "Graftshaper Tools" }, c = "بالاخره در نبردی شکوه را خواهیم یافت." }
WoWFQ[91606] = { t = "میدان نبرد Voidscar: تسویه‌حساب", d = "حیف شد یک هیولای عظیم. تصور کن اگر جنون نمی‌گرفتش چقدر زیرک بود! همراه خوبی برای کلکسیونم می‌شد.\n\nاین shadowgrafting باید تمام شود. شک دارم این domanaar خودش این کارها را بکند. حتماً graftکننده‌ای همین نزدیکی‌هاست.\n\nوقتی من و Ziadan مشغول تضعیف این هیولاییم، پیدا کن graftکننده را بکش. بعد دیگر این هیولاهای shadowgraftشده هرگز به دنیای گران‌بهای تو راه نمی‌یابند.\n\nلااقل با این کار، بالاخره دشمنمان را بیرون می‌کشیم.", o = { "Trelus the Grafter کشته شد", "به domanaar بگو آماده‌ای" }, p = "graftکننده مرده است؟", c = "پس Charonus دشمن ماست. تعجبی برایم ندارد. او همیشه از هر راهی که شده قدرت جمع می‌کرد؛ حتی تا حد تعظیم و تلمبه به Xal'atath پایین می‌آمد. نفرت‌انگیز است.\n\nبا این حال، بشنویم پیشنهادشان چیست." }
WoWFQ[91694] = { t = "میدان نبرد Voidscar: شکستن سه‌گانه", d = "آن برق در چشم‌هایت! همین حالا مرا دشمن شنخته‌ای و داری فکر می‌کنی چطور بکشتم، نه؟ خوب.\n\nنیروهای‌ام را به دژهای Ziadan و Vidious فرستادم تا سرنگون‌شان کنم. بعد فرمان Xal'atath مرا از اینجا کشید و همهٔ هیجان را از دست دادم.\n\nخوشبختانه حالا تو اینجایی. به نظر سرگرم‌کننده‌تری از تماشای این دو احمق عاشق که یادشان نمی‌آید بالاخره یکدیگر را نابود کنند می‌آیی.\n\nپس بیا! میدانم را آماده می‌کنم و نمایشی واقعی می‌گذاریم! بکشم اگر می‌توانی!", o = { "رو در رویی با میدان نبرد Voidscar Charonus", "پیشنهاد بازیکنان: 5" }, p = "انجام شد، <race>c؟", c = "می‌شنوم Charonus ارتشش را با اسیرانی از Azeroth تقویت کرده. بعضی‌شان شاید ناخواسته می‌جنگیدند، اما نه همه. آن روح‌ها از دست رفته‌اند، <class>. برایشان غصه نخور.\n\nخیلی خوب، <class>. کار تمام است و Charonus دیگر میان من و Ziadan نمی‌افتد.\n\nقدردانتم و قول می‌دهم روی میدان نبرد Slayer's Rise جبران کاملش را ببینی." }
WoWFQ[91700] = { t = "تاریکیِ از هم‌گسیخته", d = "انرژی‌های void متمرکز در این دژ موجوداتی نابه‌هنجار زاده است.\n\nحیات‌وحشی که با انرژی پس‌مانده جهش یافته و هول‌هایی که از آن‌سوی ناهنجاری‌ها می‌آیند، همچنان از انرژی اینجا تغذیه می‌کنند و می‌مکند. واقعاً ناخوشایند است!\n\nبرای امنیت کارهای آینده‌ام، این تهدیدها باید خنثی شوند.", o = { "کشته شدن جانداران کمیاب", "پیشنهاد بازیکنان: 3" }, p = "تهدیدها را از بین بردی؟", c = "خیالم راحت‌تر است که بدانم آن تهدیدها حذف شده‌اند." }
WoWFQ[91884] = { t = "توهم حرکت", d = "تو! مگر تو دیده‌ایشان؟\n\nمأمور شده‌ام سر از گم شدن بعضی از پیشاهنگان‌مان دربیاورم. شناسایی‌ام تا همین اواخر به بن‌بست خورده بود.\n\nحالا هر از گاهی لحظه‌ای پیشاهنگان گم‌شده را می‌بینم، اما... انگار از انرژی خالص Void ساخته شده‌اند.\n\nهر بار دنبالشان می‌دوم، مرا هرچه بیشتر می‌کشانند و بعد محو می‌شوند!\n\nبقیه فکر می‌کنند دیوانه شده‌ام. تو هم چیز شبیه این ندیده‌ای، نه؟", o = { "در جنوب‌شرق Den of Predaxas با Nefina دیدار کن." }, c = "می‌بینی‌شان؟ فریادهای استمدادشان... پژواک می‌گیرد... از همه سو..." }
WoWFQ[91885] = { t = "خالی کردن از تو", d = "می‌بینی...؟ دنبالم می‌کنند... التماس... می‌کنند... برای کمک...\n\n<The voidwalker strains and shudders as it tries to communicate.>\n\nخیلی ضعیف... خیلی گرسنه...\n\n<It feebly hands you a shard of dark matter.>\n\nاین... مرا سیر می‌کند... بعد با هم... الف‌های گم‌شده را پیدا می‌کنیم...", o = { "سیر کردن Voidwalker گرسنه", "Void Splinter (provided)" }, c = "الان بهترم... پایدار، اما خستگی‌ای هنوز بر تنم چسبیده.\n\nاگر بخواهیم پیشاهنگانت را پیدا کنیم، به کمکت نیاز دارم." }
WoWFQ[91886] = { t = "صداهای فال‌گیر", d = "صدای متحدان الف‌ات گوی در سرم می‌پیچد.\n\nراهی می‌شناسم که می‌توانیم پیدایشان کنیم. راهی هست برای یافتن چیزهای گم‌شده... با دستگاه‌های پویش قدیمی domanaar.\n\nاما برای کار کردن به انرژی عظیمی نیاز دارند. با هم می‌توانیم با این دستگاه‌ها تصویر دوستان گم‌شده‌ات را متمرکز کنیم. فریادهای استمدادشان واضح‌تر می‌شود، و بعد تو پیدایشان می‌کنی.\n\nبیا. قدرتت را با من قسمت کن.", o = { "به کار انداختن Scrystone اول", "به کار انداختن Scrystone دوم", "به کار انداختن Scrystone سوم" }, c = "voidwalker همه این مدت داشت از ما تغذیه می‌کرد... اما این گمراه‌سازی برای چه؟ هر چه که هست، وقت تمام کردن این ماجراست.\n\nو این بار، عنصر غافلگیری با ما خواهد بود." }
WoWFQ[91887] = { t = "قلمرو فریب", d = "در احتیاط‌مان درست بود. تهدیدهایی که در Voidstorm پیدا کرده‌ایم فاسد و بی‌بازگشت‌اند.\n\nاین فریب‌های وسواس‌گونه voidwalker غیرعادی است... نمی‌توانم نپرسم برای چه این‌همه دردسر را به خودش خرید.\n\n<She looks up at you from weary, withered eyes.>\n\nاما من بیش از حد ضعیفم که ادامه دهم. واقعاً حال‌مان را گرفته. حالا تو دست بالا را داری! فکر می‌کند داری به دامش قدم می‌گذاری.\n\nبا سلاح آماده و طلسم‌ها مهیا وارد شو!", o = { "کشته شدن Voidwalker فریبکار" }, c = "این موجود این‌همه از ما را در تار عنکبوت دروغ‌هایش گرفت.\n\nباید پابرجا بمانیم. Voidstorm جای به‌شدت خصمانه‌ای است." }
WoWFQ[91928] = { t = "برای ناهار چی داریم؟", d = "مزدورهای Shadowtrade من در ازای Stormarion Core می‌جنگند، بدون هیچ سؤالی، ولی آن‌ها هم گرسنه می‌شوند!\n\nاینجا غذا خیلی کمیاب است، پس به آذوقه نیاز داریم!\n\nیک مزدور را با خودت ببر و برایش غذای خوردنی پیدا کن. زحمتت را جبران می‌کنم!", o = { "Trigore Flank", "Shadow-Grown Berries" }, p = "مزدور خوب سیر شده؟", c = "وقتی حرف از مزدور می‌شود، هیچ چیزی مثل شکم سیر... و طلا آن‌ها را وفادار نگه نمی‌دارد." }
WoWFQ[91929] = { t = "برای ناهار چی داریم؟", d = "مزدور‌های Shadowtrade من برای هسته‌های Stormarion می‌جنگند، بدون چون‌وچرا، اما گرسنه هم می‌شوند!\n\nاینجا غذا خیلی کمیاب است، پس به آذوقه نیاز داریم!\n\nیک مزدور را با خودت ببر و برایش غذایی پیدا کن تا بخورد. زحمتت را جبران خواهم کرد!", o = { "Unstable Oozeling‌ها را برای 12 عدد Void Malgrease بکش و 3 عدد Domanaar Microwell جمع‌آوری کن.", "Void Malgrease", "Domanaar Microwell" }, p = "آیا آن مزدور سیر است؟", c = "وقتی پای مزدور‌ها به میان می‌آید، هیچ‌چیز مثل شکمی پُر وفادارشان نگه نمی‌دارد... و طلا." }
WoWFQ[91963] = { t = "آشوب بی‌مهار", d = "از دیده‌بان‌های دیگر درباره‌ی آن فلز شنیده‌ام—shadowgraft. domanaar‌ها از آن برای تحمیل سلطه‌شان بر دیگران استفاده می‌کنند.\n\nباید این‌طور فرض کنم که هنوز کسی افسار کار را در دست دارد. شاید Xal'atath باشد، شاید هم کس دیگری. تکه‌هایی از shadowgraft‌شان را جمع کن، شاید آن‌وقت بفهمیم که کیست.", o = { "Shadowgraft را از دشمنان در Obscurion Citadel جمع‌آوری کن.", "Latent Shadowgraft" }, p = "به‌قدر کافی جمع کرده‌ای تا بتوانیم مطالعه‌اش کنیم؟", c = "در نمونه‌هایی که جمع آوردی چند سبک shadowgraft دیده می‌شود. به‌نظر می‌رسد چندین domanaar برای تصاحب خلأ قدرتی که در Obscurion باقی مانده با هم رقابت می‌کنند. پس Xal'atath اینجا فرمان نمی‌راند.\n\nبا همین یک دشمن کنار می‌آییم و می‌گذاریم بقیه‌ی domanaar‌ها بین خودشان بجنگند." }
WoWFQ[92155] = { t = "جن‌گیری از اشیاء", d = "دستم را دراز کردم تا کنسولی را بررسی کنم که انرژی تاریکی در آن در حرکت بود، اما چیزی درست توی صورتم جیغ کشید. خیلی غافلگیرکننده بود.\n\nحسِ یک هشدار نمی‌داد؛ بیشتر شبیه چیزی... درنده. عصبانی. گرسنه. تقریباً حس می‌شد که می‌خواهد مرا بگیرد.\n\nوحشتناک. و جالب!\n\nیک دور اطراف را بگرد و ببین چه چیزهایی می‌توانی یاد بگیری. بررسی کن که آشفتگی‌های آشکاری وجود دارد یا نه.", o = { "بررسی مناطق پژوهشی در Shadow Rise.", "روی Whispering Chair بنشین", "دست به داخل Strange Barrel کن", "Sinister Weapon Rack را بگرد" }, p = "وقتی این ناحیه را بررسی می‌کنی محتاط باش. هنوز نمی‌دانیم با چه چیزی طرفیم.", c = "پروازت را در هوا دیدم. و جیغ‌ها را هم شنیدم.\n\n...چه جالب." }
WoWFQ[92156] = { t = "دنبالم می‌آید", d = "باید گوش کنی. موجود شروری مدتی پیش خودش را به من چسباند. هر جا می‌رفتم دنبالم می‌آمد؛ با خشم اشیاء را پرت می‌کرد، کلک می‌زد و هر چه را می‌توانست می‌بلعید.\n\nهمین حالا دست از دنبالم آمدن کشید. فکر کنم حالا تو را دوست دارد.\n\nاگر به آن غذا بدهی، باید مدتی تو را رها کند. شکست‌خورده‌ها را در Sparring Grounds با این داغ نشانه‌گذاری کن. باید آن‌ها را مصرف کند و این‌طور ما فرصت بیشتری برای حرف زدن خواهیم داشت.", o = { "8 Shadowguard شکست‌خورده را در Sparring Grounds علامت بزن.", "Shadowguard شکست‌خورده داغ خورد" }, c = "هنوز گرسنه است. غذاها هیچ‌وقت کافی نیستند.\n\nبرای همین این‌قدر ضعیف شده‌ام. دائم داشت از من غر می‌زد و اذیتم می‌کرد. اما به نظر می‌رسد تو به‌قدر کافی قوی باشی." }
WoWFQ[92157] = { t = "فعالیت آیینی", d = "تو که نبودی، ما سرمان شلوغ بود.\n\nایده‌ام این است که آن موجود بدخواه را وادار کنیم به میانه بیاید—بیرون از مخفی‌گاه‌هایش. Havazza وسایلی را جمع کرده که آن موجود به آن‌ها چسبیده. من به او اعتماد ندارم، ولی اگر او حاضر است وسایل سنگین بلند کند، دست‌کم لازم نیست من بلند کنم.\n\nبا نابود کردن وسایل پراکنده‌ای که آن موجود در آن‌ها حلول کرده، آن را از مخفی‌گاهش بیرون می‌کشیم!", o = { "با نابود کردن مخفی‌گاه‌ها، آن موجود را وادار به ظاهر شدن کن.", "Strange Barrel", "Disorienting Book", "Haunted Weapon کشته شد", "تسخیر آن موجود نابود شد", "مقاومت در برابر Whispering Chair", "جن‌زده؟!" }, p = "مخفی‌گاه‌ها را نابود می‌کنیم و آن را بیرون می‌کشیم.", c = "ببخشید. گذاشتم این ماجرا خیلی طول بکشد. کنجکاوی‌ام بر عقل‌سلیمم غلبه کرد." }
WoWFQ[92158] = { t = "بگذار داخل بیاید", d = "آن موجود قطعاً به تو چسبیده، <name>. حتی از تو تقلید کرد. شرط می‌بندم بدن هدف اصلی‌اش را تقلید می‌کند و بسته به چیزی که می‌خورد تغییرش می‌دهد. حالا که آن را در حال عمل دیدم، مطمئنم می‌توانم ظرفی برای نگه داشتنش بسازم.\n\nبه من اعتماد داری، نه؟\n\nدرست بیرونِ Shadow Rise، روی صخره‌های بالایی Claw's Edge یک ناحیه باز و خالی هست. می‌خواهم آن را از این وسایل دور کنم؛ مثل آن صندلی.\n\nبه خودت داغِ شکست‌خورده بزن و منتظر بمان. می‌آید. وقتی فرصت مناسبی دیدی، کمینش را بزن. تله‌اش می‌کنیم!", o = { "روی تپه در Claw's Edge خودت را مرده جا بزن و وقتی آن موجود سراغت آمد مغلوبش کن.", "خودت را مرده جا بزن و در Claw's Edge داغ بزن", "Insidious Reflection کشته شد", "بگیرش!" }, p = "تو آن اترئال احمق نیستی، و من هم برای کمکت هستم. حالت خوب می‌شود.", c = "ریز است، بی‌آزار است و در تله است.\n\nفقط یک کار آخر باقی مانده." }
WoWFQ[92159] = { t = "مقصد نهایی", d = "Havazza به ما خیانت کرد و گذاشت تو پاک‌کاری بعدش را بکنی. می‌توانست بکشدت. باید تاوان کارهایش را پس بدهد.\n\nمطمئنم برگشته به دوئل‌هایش، لذت می‌برد از قدرت برگشته‌اش به قیمت تو. بهتر است از منطقه Shenzar Refinery کنار Sparring Grounds شروع کنیم.\n\nاو را به یک دوئل واقعی به چالش بکش!", o = { "Lanlae را در Shenzar Refinery پیدا کن", "Havazza کشته شد" }, p = "او به تو رحم نکرد. تو هم رحم نکن.", c = "کار Havazza را خوب انجام دادی. از فکر اینکه بدون تاوان از دستمان در برود حالم گرفته می‌شد.\n\nدر جنبهٔ مثبت، برای آشوب‌های آینده می‌توانم چیزهای زیادی از این موجود یاد بگیرم." }
WoWFQ[92365] = { t = "ساختن دفاع‌ها", d = "به کار انداختن دفاع‌ها برای حفاظت از عملکرد Singularity Anchor حیاتی است. باید مطمئن شوم که تو این فرایند را کاملاً می‌فهمی.\n\nاول، هسته‌های Stormarion را که در انبار دارم جمع کن. بعد، موقعیت‌های دفاعی را فعال کن، و در آخر، در هر موقعیت یک دفاع انتخاب و به کار بگیر.\n\nوقتی این کار تمام شد، می‌توانم هسته‌های Stormarion بیشتری به تو بسپارم تا هر طور صلاح می‌دانی استفاده‌شان کنی.", o = { "مراحل را دنبال کن و دو دفاع به کار بنداز.", "Stormarion Core Selune", "موقعیت‌های دفاعی فعال شدند", "1", "2", "در هر موقعیت دفاع به کار انداخته شد" }, p = "دفاع‌ها را به کار انداخته‌ای؟", c = "خوب کار کردی؛ احساس می‌کنم سپردن این هسته‌های اضافی Stormarion به تو امن است. عاقلانه استفاده‌شان کن!" }
WoWFQ[92390] = { t = "خطر در راه پژوهش", d = "در Shadow Rise در شمال‌شرق فعالیت عجیبی در جریان است. ظاهراً نفرین شده! Shadowguard معمولاً حضور سنگینی آنجا دارد، ولی شنیده‌ام که در حال ترک آن مکان هستند.\n\nمی‌خواهم بفهمم چه حقیقتی پشت رفتن‌شان است. مرا همراهی می‌کنی؟", c = "<Lanlae درد حمله را از خود می‌تکاند و لبخندی اجباری روی لب‌هایش می‌نشاند.>\n\nچه هیجان‌انگیز! واقعاً ترس خوبی بود." }
WoWFQ[92407] = { t = "لانهٔ امن", d = "وقتی Xal'atath رفت، انبوهی ناهنجاری از خود باقی گذاشت؛ ابعاد جیبی کوچکی که دشمنان می‌توانند در آن پنهان شوند. به قول Romuul، «لانه‌های امن».\n\nاستادِ صنعتی دستگاهی سرهم بسته که باید کار را راه بیندازد.\n\nباید این لانه‌های امن را فرو بریزیم و هر دشمنی که درون‌شان کمین کرده را بیرون بیندازیم.", o = { "فروریختن لانه‌های امن" }, p = "ناهنجاری‌ها را برداشتی؟", c = "کارت عالی بود. مطمئنم ناهنجاری‌های بیشتری هم قایم شده‌اند، اما با کمکت تهدیدهای فوری را حذف کردیم." }
WoWFQ[92505] = { t = "حقیقت گذشته", d = "ممنون بابت آزاد کردنم از آن قفس‌های اترئالی در Ethereum Overcroft. Void اینجا به شیوه‌هایی قدرتمند است که هنوز تازه داردیم می‌فهمیمش، و همین خطر فرصت‌های تازه‌ای می‌آورد.\n\nاگر یادت باشد، تلاش من برای ترکیب قدرت Void با توان Illidari تغییری نکرده است.\n\nپشتیبانی از Adarus اشتباه بود، اما برای پیشرفت ضروری. و حالا معلمی داوطلب در وجود Allari پیدا کرده‌ام. باز هم کمک می‌خواهم، <name>. کمکم کن قدرت محافظت از مردمم را پیدا کنم.", o = { "ورود به درگاه Illidari" }, c = "سال‌هاست پا به Argus نگذاشته بودم. دنیایی مرده، پر از مردمی شکسته و خاطراتشان." }
WoWFQ[92507] = { t = "دشمنی قوی‌تر", d = "هر چه لازم بود در دست داریم.\n\nخودت را آماده کن تا رویارویی Illidan با آن naaru را از سال‌ها پیش ببینی.", o = { "تماشای رؤیا", "سوار شدن به درگاه به Voidstorm" }, c = "همیشه فقط یک چیز می‌خواستم: از مردمم محافظت کنم. درست مثل اینکه شکارچیان دیو از Azeroth محافظت می‌کنند." }
WoWFQ[92508] = { t = "نشانِ فداکاری", d = "خالکوبی‌هایی که تن‌مان را نشان‌دار می‌کنند فقط جوهری بیش نیستند. قولی هستند که بر تن‌مان حک شده است.\n\nقولی که با پیکر خودمان جلوی تاریکی و دوزخیان را می‌گیریم. که خون‌مان سکه‌ای است برای خریدن آیندهٔ Azeroth.\n\nتعجب کردی؟ ما فقط تجسم خشم و سرکشی نیستیم، هرچند آن هم هستیم.\n\nبه Leona کمک کن جوهرِ حیات جانداران void را در Nexus-Point Antius جمع کند. با آن خالکوبی‌هایش را می‌کشد و سوگندش برای محافظت از مردمش را مهر می‌کند.", o = { "در Nexus-Point Antius به Leona بپیوند", "جمع‌آوری «جوهر» Void" }, p = "با این جوهر و ابزاری برای حکش، Leona یک قدم به سرنوشتش نزدیک‌تر می‌شود.", c = "بله، این انرژی void اسیرشده به‌خوبی کارمان را راه می‌اندازد." }
WoWFQ[92509] = { t = "ابزاری بی‌رحم", d = "Voidstorm دنیای موجودات رأس است. یکی از آن‌ها، ultradon، از همه در قدرت و درندگی بالاتر ایستاده است.\n\nاما اشتباه نگیر، <name>. ما شکارچیان دیو هرجا برویم شکارچیان واقعیِ رأس‌ایم، چون برای تسلط حاضریم تا هر حدی برویم. موجودی بهتر از این نمی‌شناسم که ابزار حک کردن خالکوبی‌های Leona را از او برداشت کنم.\n\nبا Leona به Nexus-Point Antius برو. هر تعداد ultradon لازم است شکست بده تا ابزار بی‌نقص را پیدا کنی.", o = { "در Nexus-Point Antius به Leona بپیوند", "چنگال Ultradon برج‌بلند" }, p = "چنگال را پیدا نکرده‌ای هنوز، <name>؟ بدون آن نمی‌توانیم مراسم Leona را شروع کنیم.", c = "دیگر جای تردید نیست، <name>. شکارچیان دیو شکارچیان رأس این سیاره‌اند." }
WoWFQ[92510] = { t = "آغشته به تاریکی", d = "مراسم داغ‌گذاری‌ای که در پیش داریم اقتباسی است از آنچه شکارچیان دیو در Fel Hammer تجربه می‌کنند. اما با توجه به سرشت یکتای Leona و جایگزینی آزمایشی انرژی Void به جای fel، ریسک قابل توجهی در کار است. حتی بیشتر از همیشه.\n\nLeona در طول این فرایند آسیب‌پذیر خواهد بود، من هم. جای خلوتی برای انجامش پیدا کرده‌ایم، اما از لحظه شروع به حفاظت تو نیاز داریم.", o = { "موج‌ها کامل شد", "به Leona علامت بده مراسم را شروع کند", "مراسم کامل شد", "همراهی Leona", "بازگشت به Magister Umbric در Howling Ridge" }, p = "کاری که می‌کنیم پرریسک است، <name>. اما راه Illidari همیشه همین بوده.", c = "فکر می‌کنم تجهیزاتی داریم که می‌شود برای بازگرداندن Leona به سراغمان به کارشان گرفت." }
WoWFQ[92511] = { t = "افق رویداد", d = "شاید تعجب نکنی اگر بگویم پایدارسازی نقاط ورود درگاه تخصص من است.\n\nاگر Leona زنده باشد--و باور دارم هست--به نشانگرهایی برای مثلث‌بندی نقطهٔ خروجش نیاز دارد. این نشانگرها را بردار، همان‌جاها که روی نقشه‌ات علامت زده‌ام نصب‌شان کن، و برگرد.\n\nاگر Leona زنده باشد، با این نشانگرها می‌تواند نقطهٔ خروجش را شناسایی و پایدار کند.\n\nاگر نباشد--\n\n<Umbric pushes the thought away.>\n\nفعلاً بیایید روی کار پیش رو تمرکز کنیم.", o = { "نصب نشانگر شمالی", "نصب نشانگر شرقی", "نصب نشانگر جنوبی", "بازگشت پیش Umbric", "مراسم کامل شد" }, c = "آن صدا. یک domanaar. فکر می‌کنم حالا می‌توانم حسش کنم. اگر اول ما او را پیدا نکنیم، او به سراغ‌مان می‌آید." }
WoWFQ[92512] = { t = "بلعنده", d = "مطمئن نیستم کجا بودم وقتی از آن درگاه گذشتم، <name>. جایی میان راه؛ انرژی Void دورم می‌پیچید و در تنتنم رخنه می‌کرد.\n\nبدون Umbric برنمی‌گشتم. حالا خودم را متفاوت حس می‌کنم، اما فکر نمی‌کنم ماجرا تمام شده باشد تا وقتی با آن domanaar روبه‌رو نشویم.\n\nدر Voidspire به ما می‌پیوندی؟", o = { "به Leona علامت بده Ravenor را به خشم بکشد", "شکست Ravenor", "بازگشت پیش Umbric در Howling Ridge" }, p = "با اشتیاق و کمی هراس منتظر Leona هستم.", c = "اراده و میل Leona به جنگیدن برای مردم‌مان ستودنی است.\n\nسخت جنگید و فدیه‌های زیادی داد تا به اینجا برسد، و زندگی‌اش تا همیشه با آن آزمون‌ها نقش خواهد بست. اما ren'dorei از این قوی‌تر شده است.\n\nکه چه کسی فکرش را می‌کرد دنیایی این‌قدر تاریک و شکاپرور بستر آینده‌ای روشن‌تر باشد؟" }
WoWFQ[92546] = { t = "شکارچیان در حال نزدیک شدن", d = "این منطقه لو رفته. برای مأموریت‌مان حیاتی است که امنش کنی.", o = { "کشته شدن Shredclaw نزدیک‌شونده" }, c = "این دنیا خطرناک است. اما ما هم هستیم." }
WoWFQ[92549] = { t = "Void از آسمان", d = "دشمن جمع می‌شود. قدرت واقعی Void را به آن‌ها نشان بده!", o = { "پراکنده شدن ناهنجاری‌های Void" }, c = "برای‌مان وقت خریدی. بیایید امیدوار باشیم هوشمندانه خرجش کنیم." }
WoWFQ[92558] = { t = "قدردانی از شعله", d = "یاد جشن‌های Dawnsummer Festal در Eversong هستم و به خودم گفتم «چرا یکی از همین آتش‌بازها را در Howling Ridge روشن نکنم؟»\n\nخوشبختانه ساکنان بومی چندان سر باز نکردند.\n\nبه آن‌ها گفتم آتش‌ها چاه‌های قربانی برای ظرف‌های جادوی رازآمیزند و... بگذریم، این هم توصیفی است برای شکوفه‌های نیم‌تیر ماه، نه؟\n\nمی‌شود لحظه‌ای وقف voidflame کنی؟", o = { "قدردانی از آتش‌باز نیم‌تیرماه در Voidstorm." }, c = "قدردانی از voidflame در Voidstorm." }
