WoWFQ[92603] = { t = "ای ستاره‌ی تنها", d = "<void elf در خوابی بی‌قرار دست‌وپا می‌زند، آزرده از سایه‌ی نزدیک.\n\nشاید بهتر باشد سعی کنی بیدارش کنی.>", o = { "بیشتر درباره‌ی سایه‌ای که Orin را آزار می‌دهد بدان", "Orin Straylight را بیدار کن", "با Orin صحبت کن" }, c = "ممنون که همراهی‌ام کردی. راستش کس دیگری نداشتم که از او خواهش کنم.\n\nدیگر ren'dorei... Void چیزهای زیادی را دگرگون می‌کند، اما من در Telogrus همان‌قدر احساس بی‌جایی می‌کنم که در Silvermoon احساس می‌کردم." }
WoWFQ[92604] = { t = "با خون سخن گفتن", d = "بعد از آفرینشِ ناکامم، به جست‌وجوی خرد از Void رفتم، و Void از این جا برایم گفت.\n\nصدایی بود—غریب، اما آشنا. ابزاری برای شکل دادن به Void و سایه وعده می‌داد—چیزی که مرا از شکستم رها می‌کرد، اما Void هیچ‌چیز را مجانی نمی‌دهد. باید بر آن فرمان برانیم، و خشونت زبان مادری این سرزمین است.\n\nجانوران این‌جا را بکش و مایه‌ی خونشان را برایم بیاور. با آن خواسته‌هایمان را می‌نویسیم.", o = { "50 Viscous Ichor از موجودات Fangfall جمع کن", "Viscous Ichor" }, p = "آن را داری؟ سایه ساکت نمی‌شود. قرار نبود این‌طور وجود داشته باشد.", c = "امیدوارم زحمت زیادی نداشته باشد. این جور کارها همیشه از دستم برنمی‌آمد. هیچ‌وقت نتوانستم هنرهای خشن‌تر Void را درک کنم." }
WoWFQ[92605] = { t = "صادق مثل استخوان", d = "اگر قرار است مایه‌ی خون پیام ما را حمل کند، استخوان رنگدانه‌ی آن خواهد بود. این جا جای لاشه‌خورهاست، با استخوان‌هایی که از سراسر این سرزمین دزدیده شده‌اند: قدیمی، نو، همه در بردارنده‌ی پژواک خشونتی که به پایانشان انجامید.\n\nبرایم Bone Splinter بیاور تا برای مرکبمان پودرشان کنم.\n\nلطفاً عجله کن. این سایه چیز نادرستی است، و من باید آن را اصلاح کنم.", o = { "8 Bone Splinter از Fangfall جمع کن", "Bone Splinter" }, p = "این لاشه‌خورها باید استخوان‌ها را از همه‌جای Voidstorm آورده باشند.", c = "عالی. چند لحظه فرصت بده تا این را پودر کنم، و به‌زودی رنگدانه‌ای را که نیاز داریم خواهیم داشت." }
WoWFQ[92606] = { t = "هدیه‌ات را بر دار", d = "این‌جا--این زخم--همان چیزی است که آن صدا از دل Void به من گفت پیدا می‌کنم. چیزی درون انتظار می‌کشد... چیزی برای پایان دادن به این آفرینش شکسته. <Orin winces and glares at the shade.> نمی‌شنویش؟ می‌زند. گاهی از خشم. گاهی آن‌قدر تنهاست که دلم را می‌لرزاند. بی‌اعتنایش. با رون‌های مناسب که در عفون و استخوان نوشته شوند، باور دارم می‌توانیم این شکاف را بازتر کنیم. بعد هر چه درون است را تصاحب می‌کنی.", o = { "کشیدن دایره‌های مراسم", "دایره 01", "دایره 02", "دایره 03", "از شکاف بگذر", "Shadow Chisel" }, p = "صدا راست می‌گفت. چیزی همین‌جا در انتظار بود.", c = "شگفت‌آور است. این قلم برای تراشیدن سنگ یا فلز ساخته نشده، بلکه برای خود Void. می‌تواند مرا از این سایه برهاند." }
WoWFQ[92607] = { t = "و شکل‌های تازه تراشیدن", d = "این همان چیزی بود که آن صدا از Void به من وعده داده بود: وسیله‌ای برای رها شدن از این سایه.\n\nتو باید آن را به دست بگیری. نگران نباش—به من آسیبی نمی‌رساند. مرا از سایه جدا می‌کند. بعد هم باید به‌سادگی محو شود؛ چیزی جز سایه‌ای بی‌لنگر باقی نمی‌ماند.\n\nشروع کن. آماده‌ام.", o = { "Orin را از سایه‌اش جدا کن", "Orin را از سایه‌اش آزاد کن", "سایه‌ی Orin را مهار کن" }, c = "سایه نمی‌خواست عذابم دهد—خودش در عذاب بود. من آن را در عمق تنهایی‌ام آفریده بودم و بازتاب همان بود: بسته به من، ناتوان از زیستن به‌تنهایی، می‌کوشید آرامشی بخشد که توانش را نداشت، در حالی که در قالب سایه‌ام گیر افتاده بود.\n\nبرای فرار از تنهایی‌ام به بیرون نگاه کردم. یافتن Void، ren'dorei شدن، همراهی با بقیه تا این‌جا... فکر می‌کردم اگر فقط جای درست را پیدا کنم، دیگر این‌طور حس نخواهم کرد.\n\nاما اشتباه می‌کردم. همیشه درون من بود. نمی‌توانستم بیرونش بریزم؛ تنها می‌توانستم در آغوشش بگیرم." }
