WoWFQ[93801] = { t = "کشتار حساب‌شده", d = "این بیماری به‌سرعت در میان ساکنان Molt در حال گسترش است.\n\nگروهی از netherwasp اندکی پس از رسیدن ما از تخم بیرون آمدند. همان‌طور که بر سر قلمرو با هم می‌جنگیدند، آلودگی در سراسر منطقه پخش شد. اگر شمارشان به رشد ادامه دهد، ممکن است بیماری را به بقیه‌ی Voidstorm ببرند.\n\n<name>، می‌توانم از تو بخواهم تعداد موجودات آلوده در Molt را کم کنی؟", o = { "موجودات بومی Molt را حذف کن.", "هیولا‌ها در Molt کشته شدند", "[DNT] Molt Proxy کشته شد", "[DNT] Molt Proxy T0 کشته شد", "[DNT] Molt Proxy T2 کشته شد", "[DNT] Kill Credit: Molt Proxy T3 کشته شد" }, p = "این مکان چه سرزندگی‌ای دارد. تعجبی ندارد که بیماری این‌قدر راحت پخش شده.", c = "تلاش و کمکت هم به چشم دید و هم قدردانش هستیم." }
WoWFQ[93904] = { t = "سرکشی از جاذبه", d = "انرژی Void متمرکز از درون آن غار می‌تابد. جمعش کن تا با قدرتی بیشتر در برابر Xal'atath به میدان برویم.", o = { "جمع شدن Void Power", "0/1 فعال کردن Gravity Anomaly برای سفر به بالا" }, c = "ذخایر mana ما به لطف تو نوسازی شد. کار درخشانی بود." }
WoWFQ[93905] = { t = "سرکشی از جاذبه", d = "این اترئال‌ها سوخت‌رسان نیروهای Xal'atath هستند. آن‌ها و ماشین‌های‌شان را نابود کن.", o = { "Manaforge مختل شد" }, c = "بگذار بازسازی را امتحان کنند. تو آنجا خواهی بود تا دوباره جلویشان را بگیری." }
WoWFQ[93933] = { t = "گنج‌های محافظت‌شده", d = "سفرمان به این دنیا شناخت ren'dorei از Void را عمیق‌تر از همیشه کرده است. این domanaarها که دشمن مشترکی با ما دارند به‌طرزی عجیب با دانش‌شان دست‌ودل‌بازند. گمان می‌کنم می‌خواهند ما هم به تهدیدی مثل خودشان بدل شویم.\n\nلنگرگاهی از جنس Singularity در Stormarion Citadel هست. یاد گرفته‌ام چطور از بخشی از قدرتش برای ساختن شیئی نیرومند برای تو بهره بگیرم.\n\nاما اول باید مطمئن شویم به دست دشمنان نمی‌افتد.", o = { "دفاع از Singularity Anchor" }, p = "لنگرگاه را از یورش نیروهای void محافظت کردی؟", c = "خوب بود، <name>." }
WoWFQ[94425] = { t = "خون‌ریزان کردن برج", d = "ثابت بمان. گرسنگی Void نباید قربانی دیگری از مردم‌مان بگیرد.", o = { "با Scout Adaephus صحبت کن", "کشته شدن نیروهای نخبهٔ Voidspire", "خرد شدن ستون‌های احضار" }, c = "مثل همیشه، بر تو می‌شکنند." }
WoWFQ[94581] = { t = "محکم بایست", o = { "تمام رویداد حمله به Stormarion را کامل کن", "موج 1 کامل شد", "موج 2 کامل شد", "موج 3 کامل شد", "[DNT] Kill Credit کشته شد", "موقعیت دفاعی فعال شد" } }
WoWFQ[94623] = { t = "ساختن Voidforge", d = "داشتم فکر می‌کردم چطور قدرتی بیشتر به تو هدیه کنم، دوست من. به چیزی رسیدم، اما برای ساختن Voidforge‌ای درست‌وحسابی به کمکت نیاز دارم.\n\nچه؟ آه، نترس؛ همهٔ نیات پنهان من هنوز هم‌راستا با هدف توست. فعلاً.\n\nبرای شروع، یک Elementary Voidcore لازم دارم. از دشمنان قدرتمندی که همیشه با آن‌ها درگیر می‌شوی shard پیدا می‌کنی. خشونت معمولت را اجرا کن، shardها را بیاور، و من می‌توانم آن‌ها را به Voidcore حقیقی ببافم تا بنیاد کوره باشد.", o = { "Elementary Voidcore Shard" }, p = "هنوز برگشتی، <name>؟ زخم تازه‌ای برداشته‌ای؟", c = "آه، Voidforge نوزاد آماده است! اوه، کارهایی که من... منظورم ما، با این می‌توانیم بکنیم..." }
WoWFQ[94625] = { t = "یک Elementary Voidcore", d = "کار ادامه دارد. shard کافی پیدا کن تا بتوانیم دوباره‌شان به یک Elemental Voidcore ذوب کنیم.\n\nتا این‌جا موادی کافی برای دگردیسی مجموعاً 6 هسته فراهم کرده‌ام. Voidforge نوزاد قبل از شکل‌گیری کامل به 6 تا نیاز دارد و تو تا الان به‌طرز دست‌ودلبازی X تا کمک کرده‌ای.\n\nبرو بیرون و کمی بیشتر به خشونت مشغول شو، قبول می‌کنی؟", o = { "Elementary Voidcore Shard" }, p = "این یکی را قطعاً با عجله نیاوردی، <name>. حدس می‌زنم دروازه‌های زمان را هم نمی‌شود تند کرد، نه؟", c = "عالی. یک Elemental Voidcore دیگر برای Voidforge!" }
WoWFQ[94675] = { t = "بازآهنگری Voidforge", c = "بعد از همه‌ی این مدت، Voidforge نوپا زمزمه‌ی قدرت سر می‌دهد!" }
WoWFQ[94736] = { t = "بدرخش", d = "Trial of Style به ما این فرصت را می‌دهد که خوش‌قیافه به نظر برسیم، <class>.\n\nدوربین مطمئن می‌شود که همچنان خوش‌قیافه بمانیم.\n\nپس روی من و دوربینم تمرکز کن، طبق دستورهایم عمل کن و من کاری می‌کنم که فوق‌العاده به نظر برسی!", o = { "روی عکاس تمرکز کن و طبق دستورهایش عمل کن.", "عکس‌های شیک از تو گرفته شد" }, p = "روی من تمرکز کن و طبق دستورهایم عمل کن.\n\nمن کاری می‌کنم که عالی به نظر برسی.", c = "دوربین دروغ نمی‌گوید، <name>.\n\nتو واقعاً یک <class> شیک هستی." }
WoWFQ[94790] = { t = "کنسول پژوهشی: کاوش در Void", d = "به قول معروف، برای پژوهشگران وقتی برای استراحت نیست.\n\nهر قدر هم دوست دارم در این سرزمین مخروبهٔ void پرسه بزنم، باید سر پستم بمانم. اما تو! تو می‌توانی چشم و گوش ما در این پرتگاه باشی.\n\nبرو و Voidstorm را بگرد، شاید نمونه‌های بیشتری برای تغذیهٔ کنسول پیدا کنیم.", o = { "تکمیل World Questها در Voidstorm" }, p = "این‌قدر زود برگشتی؟", c = "نمونه‌های بیشتر، عالی! کنسول گرسنه است..." }
WoWFQ[95268] = { t = "ابزار تازه، اوج‌های تازه", d = "نوع دیگری از قدرت Void هست که می‌دانم به تو مربوط می‌شود. Ascendant Voidcore به‌سختی پیدا می‌شود و کار کردن با‌اش حتی سخت‌تر است. حالا که Voidforge کامل شده، می‌توانم Nilhammer باشکوهی ببافم که توان چنین کارهایی را دارد. البته برای مواد به کمکت نیاز دارم. وقت می‌برد.\n\nاین تکهٔ Hungering Oblivium را بگیر. می‌تواند لحظه‌های خشونت افراطی را ببلعد تا به اوج‌های تازهٔ قدرت کاتالیز شود، اما مشکلی برای فراهم کردنش نخواهی داشت، نه؟", o = { "کاتالیز شدن Hungering Oblivium", "Hungering Oblivium (provided)" }, p = "هنوز به سنگ خانگی‌ات خوراک نداده‌ای، <name>؟ پیشنهاد نمی‌کنم Oblivium را مدت طولانی روی خودت نگه داری...", c = "می‌توانم ببینم Hungering Oblivium دارد قدرت ساطع می‌کند! کارت خوب بود، <name>. نخستین قدم را به سوی قدرتی بزرگ‌تر برداشتیم. تهیهٔ Oblivium بیشتر برای ادامهٔ کارمان کمی طول می‌کشد." }
WoWFQ[95269] = { t = "سیر کردن Nilhammer", d = "Nilhammer نوپای‌مان دارد شکل می‌گیرد! اما قبل از اینکه کاملاً صورت بگیرد، باید انرژی‌های Void را از Hungering Obliviumهای بیشتری در آن ببافم. خوشبختانه تکهٔ دیگری برای کاتالیز کردن برایت آماده کرده‌ام. خشونت افراطی، یادت نرفته؟", o = { "کاتالیز شدن Hungering Oblivium", "Hungering Oblivium (provided)" }, c = "آه، آفرین. یک کاتالیز شدن موفق دیگر Oblivium. Nilhammer نیرومندتر می‌شود!" }
WoWFQ[95271] = { t = "Nilhammer صعودکننده", c = "Ascendant Netherhammer! سلاحی که واقعاً لایق استادکاری‌ای مثل من است. کارهایی که می‌توانم بسازم... البته برای زحمتی که کشیدی پاداش خواهی گرفت. این Ascendant Voidshard را بگیر. چند تای دیگر لازم داری قبل از اینکه بتوانی‌شان را به Ascendant Voidcore ذوب کنی. من کمکت می‌کنم انرژی‌هایش را در Voidforge به نیرومندترین تجهیزاتت منتقل کنی." }
WoWFQ[95279] = { t = "Voidcoreهای مه‌آلود: طلا", p = "باز برای Voidcoreهای مه‌آلود برگشته‌ای؟ آماده‌شان کرده‌ام، اما انتظار دارم در خرج‌های‌مان سهیم شوی. و حتی بیشتر. مگر چه اشکالی دارد که این علاقهٔ دلپذیرت به خشونت سود بدهد، بعد از همه؟\n\nحتی در Voidstorm هم می‌شود برای طلا کاربری پیدا کرد. زیر شرایط درست و با کمی انرژی Void، خواص جالبی از خود نشان می‌دهد!", c = "می‌دانستم نمی‌توانی نه بگویی. مطمئنم از این Voidcoreهای مه‌آلود استفادهٔ خوبی می‌کنی، <name>." }
WoWFQ[95290] = { t = "Voidcoreهای مه‌آلود: Voidlight Marl", p = "باز برای Voidcoreهای مه‌آلود برگشته‌ای؟ آماده‌شان کرده‌ام، اما انتظار دارم در خرج‌های‌مان سهیم شوی. و حتی بیشتر. مگر چه اشکالی دارد که این علاقهٔ دلپذیرت به خشونت سود بدهد، بعد از همه؟\n\nVoidlight Marl ماده‌ای شگفت‌انگیز است! همیشه برای آزمایش بیشتر خوشحال می‌شوم. پیدا کردن مواد واکنشی لمس‌شده با Light در Voidstorm معمولاً دشوار است.", c = "می‌دانستم نمی‌توانی نه بگویی. مطمئنم از این Voidcoreهای مه‌آلود استفادهٔ خوبی می‌کنی، <name>." }
WoWFQ[95304] = { t = "Voidcoreهای مه‌آلود: Veteran Dawncrest", p = "باز برای Voidcoreهای مه‌آلود برگشته‌ای؟ آماده‌شان کرده‌ام، اما انتظار دارم در خرج‌های‌مان سهیم شوی. و حتی بیشتر. مگر چه اشکالی دارد که این علاقهٔ دلپذیرت به خشونت سود بدهد، بعد از همه؟\n\nآن نشان‌هایی که برای تقویت تجهیزات به کار می‌بری، می‌توانند در کارگاه من استفادهٔ بزرگی داشته باشند. همیشه برای آزمایش به مواد تازه نیاز دارم.", c = "می‌دانستم نمی‌توانی نه بگویی. مطمئنم از این Voidcoreهای مه‌آلود استفادهٔ خوبی می‌کنی، <name>." }
WoWFQ[95373] = { t = "تلاشی مه‌آلود", d = "حالا که Voidforge کامل شده، می‌توانم از قدرتی که جمع می‌کند برایت Nebulous Voidcore ببافم. البته برخی هزینه‌ها را باید تو بپردازی.\n\nبرای دگردیسی آن‌ها به سلاح و زره، باید کمی خون‌ریزی دلپذیر بیشتری به خرج دهی. دشمنان خطرناک‌تر دو تا می‌خواهند. هر Nebulous Voidcore ذره‌ای از جوهر ویژهٔ... قربانیانت را در خود ثبت می‌کند تا بدل شود به همان شیء براقی که می‌دانم رهایش نمی‌کنی.", o = { "گرفتن Nebulous Voidcore از Decimus", "خرج کردن یک Nebulous Voidcore بعد از تکمیل محتوای واجد شرایط" }, p = "این‌قدر زود برگشتی، <name>؟ Nebulous Voidcore را دگردیسی دادی؟", c = "آه، معلوم است بالاخره چیزی براق پیدا کردی! Voidforge به‌مرور مواد واکنشی بیشتری برای بافتن Voidcoreهای مه‌آلود به من می‌دهد، پس بعداً سر بزن." }
WoWFQ[95392] = { t = "یک دوست کافی است", d = "به نظر می‌رسد این elementalها وقتی کوچک‌اند کاملاً بی‌آزارند، اما وقتی بزرگ می‌شوند به‌شدت خصمانه می‌شوند. ببین می‌توانیم از این برای نفع تو استفاده کنیم.", o = { "بررسی تودهٔ برف", "انباشت سرمای افسون‌شده", "شکست دادن نیروهای Void" }, c = "این کار عملیاتشان را به‌طور چشمگیری عقب می‌اندازد. عالی بود، <name>." }
WoWFQ[95393] = { t = "نجات ساکن غار", d = "به نظر می‌رسد پیشاهنگان فانی‌ات مشکل یخ‌زدگی دارند. شاید بتوانی راهی پیدا کنی که گرم و مشوق باشد.", o = { "ایمن سازی غار" }, c = "تقریباً چنگ‌شان را از این دنیا کندی. فشار را نگه دار." }
WoWFQ[95394] = { t = "رهایی نابه‌هنجارها", d = "Imperator باغچه‌ای از جانوران درنده را زیر سلطهٔ خود نگه می‌داشت. بگذار ما سر و کلاهشان بگذاریم، قبول می‌کنی؟", o = { "آزاد شدن Devourerهای Shadowgraft‌شده" }, c = "این کار عملیاتشان را به‌طور چشمگیری عقب می‌اندازد. تلاش فوق‌العاده‌ای بود، <name>." }
WoWFQ[95395] = { t = "تا وقتی تمام شود", d = "...", o = { "رهایی Ultradon Slayer", "شکست دادن نیروهای Void" }, c = "..." }
WoWFQ[95396] = { t = "آیین آلوده", d = "دشمنانمان حضور باقی‌ماندهٔ Burning Legion را در کمین همین دنیا یافته‌اند. جلویشان را بگیر--همین حالا!", o = { "اخلال در آیین" }, c = "لحظه‌ای نفس تازه کن. دشمنانمان هنوز از پا نیفتاده‌اند." }
WoWFQ[95397] = { t = "استقبال سرد", d = "طبیعی است که «تهدید» دیگری هم مأموریت تو را تهدید می‌کند. نابود کن، از بین ببر، موفق شو.", o = { "یاری به نیروهای اکتشافی" }, c = "این تلاش‌های ناامیدانه برای قدرت، تقریباً قابل تحسین‌اند. بگذریم." }
WoWFQ[95398] = { t = "اختلاف و تفرقه", d = "بعضی از ستوان‌های domanaar دارند ایمانشان را از دست می‌دهند. شاید بتوانی قانعشان کنی به Decimus بپیوندند.", o = { "پوشیدن مبدل", "ورود به درگاه", "قانع کردن domanaar به شورش" }, c = "لحظه‌ای نفس تازه کن. دشمنانمان هنوز از پا نیفتاده‌اند." }
WoWFQ[95399] = { t = "نقشه‌های سایه‌وار", d = "متحدان Illidari ما کشف کرده‌اند domanaarهای رده‌بالا کجا نقشه‌های نبردشان را می‌ریزند. پس گرفتنشان همان برتری‌ای است که نیاز داریم.", o = { "پوشیدن مبدل", "ورود به درگاه", "دزدیدن نقشه‌های نبرد" }, c = "حالا ترازو کمی متعادل شد. کارت خوب بود، <name>." }
