WoWFQ[96051] = { t = "از دل Rift سرد", d = "کلیدسنگ Legion و ذرات تاریکی‌ای که پیدا کردی، سوزنی شد برای یافتن آنچه در انبار کاه بی‌کران Twisting Nether پنهان است.\n\nبا Cynosure of Twilight، یادگاری که راه ورود به Voidstorm را گشود، می‌توانیم از این سوزن بگذریم و riftی باز کنیم که تا در خانهٔ دشمن می‌رود.\n\nبا فراهم شدن قطعه‌ها، riftwardenهای من آماده‌اند.\n\nCynosure را بردار و نشانه بگیر و آماده باش، <name>.", o = { "بازیابی Cynosure of Twilight", "باز شدن rift", "گذر از rift", "انتظار برای فرمان Riftblade Maella" }, c = "<Maella shields herself from the cold gust of howling wind.>\n\nموقعیت‌مان مناسب است اما هوا نیست.\n\nدست‌کم این منطقه پاک‌سازی شده. می‌توانیم همین‌جا سنگر بگذاریم.\n\nوقتی Y'mera مشغول آوردن بقیهٔ نیروها و آذوقه است، بیایید خودمان را با مکان وفق دهیم." }
WoWFQ[96052] = { t = "از دل Rift mana", d = "انرژی از هستهٔ باتری Hal'hadar و ذرات تاریکی به ما کمک کرد رد کم‌رنگی از انرژی nether بازسازی کنیم.\n\nبا Cynosure of Twilight می‌توانیم این رد را روشن و شعله‌ور کنیم و مستقیم تا در خانهٔ دشمن برویم.\n\nلنگرها سر جایشان‌اند و riftwalkerهای من منتظر حرکت تو هستند.\n\nCynosure را بردار و نشانه بگیر. ببینیم آن‌سو چه در انتظارمان است.", o = { "بازیابی Cynosure of Twilight", "باز شدن rift", "گذر از rift", "انتظار برای فرمان Riftblade Maella" }, c = "<Maella squints, her eyes narrowing at the heavy fog and plumes of arcane energy in the distance.>\n\nمطمئنم جای درست آمده‌ایم. از همین‌جا بوی تعفن mana سوخته به مشامم می‌رسد.\n\nمحل فرودمان جای امنی برای سنگر بستن نیروهایمان است.\n\nوقتی Y'mera بقیهٔ نیروها را منتقل می‌کند، بیایید خودمان را با اوضاع وفق دهیم و ببینیم این دنیا چه در دل دارد." }
WoWFQ[96053] = { t = "شناسایی بیابان‌های یخ‌زده", d = "هنوز عنصر غافلگیری با ماست و همین فرصتی می‌دهد تا مواضع‌مان را محکم کنیم.\n\nوقتی Y'mera شبکهٔ سفر پایدارتری برای بقیهٔ نیروها باز می‌کند، پیشاهنگان‌مان رفته‌اند زمین را شناسایی کنند.\n\nدر میدان به آن‌ها بپیوند و نشانگرهای دیدبانی‌مان را فعال کن.\n\nمن اینجا می‌مانم تا رسیدن نیروهای کمکی را پوشش دهم.", o = { "با Allari the Souleater صحبت کن", "Beacon تالاعان", "Beacon بارا", "فعال کردن Surveillance Beacon", "فعال کردن Beacon واپسین" }, c = "این نشانگرها به ما اجازه می‌دهند دشمنان را از نزدیک زیر نظر بگیریم و تهدیدهای منطقه را رصد کنیم.\n\nبالاخره همهٔ تیم حمله‌مان مثل من چشم ارواحی ندارند.\n\nحالا که چشم‌مان به دشمن باز شد، فرصت تازه‌ای داریم تا در این بیابان نفرت‌انگیز هرج‌ومرج بپا کنیم." }
WoWFQ[96054] = { t = "شناسایی باتلاق mana", d = "آمدن ناگهانی‌مان لحظه‌ای کوتاه به ما می‌دهد تا این‌جا محکم شویم.\n\nوقتی Y'mera مشغول انتقال بقیهٔ نیروها از شبکه‌ای پایدارتر است، پیشاهنگان‌مان رفته‌اند زمین و دشمن را شناسایی کنند.\n\nدر میدان به آن‌ها بپیوند و نشانگرهای دیدبانی‌مان را فعال کن.\n\nمن همراه Y'mera و Decimus اینجا می‌مانم تا اگر آن قایق‌های بالاسر هوس دیدارمان را کردند، سرشان را ببینم.", o = { "با Allari the Souleater صحبت کن", "Beacon بالث", "Beacon بارا", "فعال کردن Surveillance Beacon", "فعال کردن Beacon واپسین", "کنار Command Point: Primos با Commander Tala'saan صحبت کن." }, p = "به قول Illidari، طبق اسناد Legion، ساکنان پیشین این دنیا به‌اش «Naigtal» می‌گفتند.\n\nاینکه Hal'hadarها — یا اصلاً Burning Legion — جز گِل و باتلاق دنبال چه چیزی در اینجا می‌گشتند، از من دور است.", c = "این نشانگرهای نقاب‌دار به ما اجازه می‌دهند از دور دشمنان را زیر نظر بگیریم و حرکت‌شان را رصد کنیم.\n\nبه‌پای پیشاهنگ واقعی نمی‌شود، اما فعلاً کارمان را راه می‌اندازد.\n\nحالا ببینیم چه‌قدر منظم‌اند.\n\nبا این Hal'hadarها، احتمالاً گمان می‌کنند امن‌اند و هیچ تهدیدی به‌شان نمی‌رسد.\n\nاشتباهی که روزی تاوان سنگینی برایشان خواهد داشت." }
WoWFQ[96210] = { t = "شست‌وشوی دردسرها", d = "تا وقتی به devourerها غذا بدهیم، رام کردنشان چندان سخت نبود. اما این‌های آلوده؟ فکر می‌کنم نابود کردنشان بهتر باشد...", o = { "کشته شدن Aberrationهای آلوده" }, c = "به نفع خودت امیدوارم همهٔ مأموریت‌هایت این‌طور تمام نشود." }
WoWFQ[96217] = { t = "قطع برق پراکنده", d = "اترئال‌ها روی حیات‌وحش بومی و قارچ‌های گوناگون آزمایش می‌کنند. پیشنهاد می‌کنم قبل از اینکه به نتیجه برسند و چیزی بسازند که از عهده‌اش برنیایی، جلویشان را بگیریم.", o = { "به دست آوردن keycodeهای Hal'hadar Keeper", "آزادسازی Spore Moteها" }, c = "حالا ترازو کمی متعادل شد. کارت خوب بود، <name>." }
WoWFQ[96268] = { t = "هاگ‌های Mana مردابی", d = "به نظر می‌رسد هاگ‌های شارژشده با Arcane از این قارچ‌ها بیرون می‌آیند. پیش از آنکه اترئال‌ها راهی برای سلاحی‌کردنشان پیدا کنند، آن‌ها را جمع‌آوری کن.", o = { "پریدن روی قارچ جهنده", "Mana Spore (5)" }, c = "حالا این باید ترازو را به تعادل برگرداند. کارت خوب بود، <name>." }
WoWFQ[96272] = { t = "در هم کوبیدن ماشین‌های قارچیِ mana", d = "این قارچ‌ها اثر انرژی‌های arcane را که به آن وصل‌اند تقویت می‌کنند. عملیات برداشت‌شان را به هم بزن تا کند شوند.", o = { "از کار انداختن ماشین‌های برداشت" }, c = "حالا ترازو کمی متعادل شد. کارت خوب بود، <name>." }
WoWFQ[96293] = { t = "قارچ‌تاز!", d = "هاگ‌های این قارچ‌ها با نرخ رشد شتاب‌یافته دستکاری شده‌اند. روی این برداشت‌گران هرج‌ومرج آزاد کن.", o = { "پرتاب باتری به قارچ‌های فرّار", "کشته شدن Hal'hadar Cultivator" }, c = "خب، دست‌کم از پس‌اش برآمدی." }
