WoWFQ[96310] = { t = "به هم زدن نظم", d = "کار شکست دادن نیروهایشان را خوب انجام دادی. هر قدمی که برمی‌داریم Azeroth را امن‌تر نگه می‌دارد.\n\nاما غاصبان هنوز در تلاش‌اند کنترل را به دست بگیرند. Baraat همین حالا domanaarهای رده‌بالایی را دیده که به منابع باقی‌مانده چشم دوخته‌اند.\n\nباید Umbrawardenها و هر نیرویی که در مسیرشان است را شکست بدهیم.", o = { "کشته شدن Domanaarهای Umbrawarden", "کشته شدن نیروهای domanaar" }, p = "نمی‌گذاریم دوباره پا محکم کنند.", c = "با خسته شدن نیروهایشان و کشته شدن رهبرانشان، این پایگاه بدتر از قبل فرسوده شد.\n\nکارت خوب بود، <name>." }
WoWFQ[96338] = { t = "درگاه ورود", d = "<name>، یک نگاه به آن سکوی بالا بینداز. به نظرت از آن چه کاری می‌کنند؟\n\nموجودات void حیات‌وحش را از Azeroth می‌ربایند و برای شکستن به اینجا می‌آورند و بعد به نیروهایشان اضافه می‌کنند. آن سکوت حتماً جایی است که اولین بار موجودات را وارد می‌کنند.\n\nراهمان را از میان هر دفاعی که آن بالا هست باز کنیم و آن درگاه را نابود کنیم!", o = { "سوار شدن به درگاه به سکوی حمل", "نزدیک شدن به درگاه حمل اصلی", "محافظت از Baraat در حال ریختن Light به درگاه" }, p = "باید زنجیرهٔ تأمین‌شان را قطع کرد. اگر این کار را بکنیم، شاید بتوانیم برای همیشه به تهدید اینجا پایان دهیم.", c = "عملیات domanaar به‌شدت فلج شد، اما تا وقتی این موجودات پلید زنده‌اند، آرامشی در کار نیست." }
WoWFQ[96382] = { t = "رویکردی تازه", d = "برای این تهدید باید کمی شبیه domanaarها فکر کنی. خوشبختانه من دقیقاً می‌توانم همین کار را بکنم.\n\nآنچه لازم داریم عروسکی دست‌نشانده است. کسی که افسارش را به‌شان بدهیم و دلی در دل نداشته باشد برای Azeroth گران‌بهای تو. آن domanaarهای تازه‌ای که دیدی باید بررسی شوند.\n\nاین نقاب را بگیر. با آن می‌توانی در میان‌شان محو شوی و تماشاگر باشی. می‌فهمم هوس زدن داری، اما صبور باش. وقتش که برسد، هر که در سر راهت است را حذف می‌کنی؛ همان‌طور که هم‌نوع تو به آن علاقه دارد.\n\nببین می‌توانی گزینهٔ مناسبی پیدا کنی.", o = { "پوشیدن مبدل.", "بازجویی از Periculus.", "بازجویی از Ignedus.", "بازجویی از Gladius Reginax.", "Veilcaster (quest item) (provided)" }, c = "هوم.. بله. به نظر می‌رسد Impotus کسی است که با او کارمان راه می‌افتد." }
WoWFQ[96389] = { t = "جایی برای مذاکره", d = "وقتی تو مشغول هم‌آوا کردن گوهر با Void بودی، من موفق شدم یکی از دستگاه‌های تصویر Impotus را به دست بیاورم.\n\nاز آن استفاده می‌کنیم تا او را به سمت‌مان بکشیم، بعد جلوی فرارش با گوهر را بگیریم.\n\nاما نه اینجا. برویم جایی خلوت‌تر.", o = { "در Steam Ravine با Leona Darkstrider دیدار کن." }, c = "خوب. حالا فقط باید قانع کنیم Impotus پای می‌آید." }
WoWFQ[96432] = { t = "اضافه‌بار قدرت", d = "فرآوری این قارچ‌ها شاید بازده انرژی‌شان را بالا ببرد، اما هاگ‌هایشان ویرانی به راه می‌اندازند در ماشین‌های اترئال‌ها. ببین می‌توانی کارشان را به هم بریزی.", o = { "اضافه‌بار شدن Fungal Processorها" }, c = "لحظه‌ای نفس تازه کن. دشمنانمان هنوز از پا نیفتاده‌اند." }
