WoWFQ[96440] = { t = "پیروزی در نگاه به گذشته", d = "کارت عالی بود، <name>! همین حالا هم می‌توانم دیوارهای Acropolis در حال فروریختن را تصور کنم.\n\nراستش چرا همان حالا نمی‌رویم آنجا و از برتری‌مان استفاده نمی‌کنیم؟ Light از ریژ‌ترین شکاف‌ها هم می‌گذرد.\n\nمن پیش می‌روم و در راه به تو می‌پیوندم.", o = { "بیرون درگاه Glacial Reservoir به Baraat بپیوند", "با Baraat صحبت کن تا نقاب بگیری" }, c = "به نظر می‌رسد به همان‌جا برگشتیم که شروع شد.\n\nاین هیولاهای طمع‌کار در دزدیدن هر قدرتی که پیدا کنند درنگ نمی‌کنند؛ حتی از هم‌نوع خودشان.\n\nنقشهٔ تازه‌ای لازم داریم." }
WoWFQ[96472] = { t = "نخبهٔ Nexus", d = "شاید Hal'hadarها هنوز از آمدن ما خبر ندارند، اما با این حال برتری با آن‌هاست.\n\nNexus Captain Leth'ir و همکارش Mertei پشت همین گردنه‌اند و ارتشی کوچک دورشان را گرفته.\n\nاگر به‌قدر کافی متحد جمع کنی و رهبرانشان را غافلگیر کنی، قبل از آنکه بفهمند چه شد ضربه‌ای ویرانگر به‌شان می‌زنیم.\n\nبا احتیاط پیش برو، <name>، و حتماً تنها نباش.", o = { "کشته شدن Nexus-Captain Leth'ir", "بازگشت به Riftblade Maella در Umbral Basecamp در Naigtal.", "پیشنهاد بازیکنان: 15" }, p = "خبر از Hal'hadarها چیست؟", c = "موفق شدی؟ Leth'ir مرده؟\n\n<Riftblade Maella offers a rare smirk.>\n\nشاید Hal'hadarها حالا بفهمند اینجاییم، اما مرگ نخبه‌شان آن‌ها را در باتلاق سرگردان می‌کند.\n\nکردار تو به ما، و به Azeroth، فرصت نفس کشیدن داد.\n\nتا می‌توانی استراحت کن. تهدید اینجا هنوز خیلی مانده." }
WoWFQ[96475] = { t = "علمِ فریبنده", d = "به نظر می‌رسد domanaar به نام Impotus را می‌توان قانع کرد چشمش به جای دیگری بیفتد.\n\nصحبت مستقیم با آن‌ها دشوار خواهد بود. به هم بی‌اعتمادند، حتی به هم‌نوع خودشان؛ همان‌طور که از دستگاه‌های تصویرشان می‌بینی.\n\nباید دام بیندازیم.\n\nاین soul gem را بردار و موجوداتی را که در Acropolis زندگی می‌کنند شکار کن. از انرژی void همین جا علیه خودشان استفاده می‌کنیم.", o = { "آغشته با انرژی void خودت", "آغشته با انرژی void خودت", "جذب موجودات void" }, p = "برای طعمه‌ای مثل این، دام مناسب لازم است.", c = "آه، عالی. گوهر با ضرباهنگ Void وفق گرفت." }
WoWFQ[96496] = { t = "راهی که دوباره پیموده نمی‌شود", d = "در شناسایی‌مان از این بیابان یخ‌زده، پیشاهنگان دو منطقه را شایستهٔ رصد یافتند اما با یک مشکل اساسی: فقط از یک نقطهٔ ورود قابل دسترس‌اند.\n\nقبل از آنکه با خیال راحت نیروی بیشتری بفرستم، باید راه‌های خروج‌شان را امن کنیم.\n\nروی بلورهای تلپورت‌شونده‌ای کار می‌کنیم که برای سفر محلی سریع‌تر از شبکهٔ درگاه موجود domanaarها استفاده کند و به راه‌حل نزدیک شده‌ایم. فقط باید آن‌ها را در میدان بیازمایی کنی.\n\nاین prototypeهای Rift Slipper را نصب کن و برگرد گزارش بده.", o = { "سوار شدن به درگاه به Forgotten Chamber", "قرار دادن Rift Slipper", "سوار شدن به درگاه به Void Acropolis", "قرار دادن Rift Slipper" }, p = "برای گسترش امن عملیات‌مان در Val به آن rift slipperها نیاز داریم، و همین نخستین قدم شبکهٔ تلپورت محلی‌مان است.", c = "کارت عالی بود که سالم برگشتی. حالا پیشاهنگان‌مان آزادتر حرکت می‌کنند بدون ریسک به دام افتادن." }
WoWFQ[96497] = { t = "استدلال فضایی", d = "domanaarها اینجا بیشتر از تصورمان مستحکم شده‌اند و این طوفان‌ها هم حتی یک لحظه رحم نمی‌کنند.\n\nبالاخره با زحماتی که برای نصب rift slipperها کشیدی فهمیدیم چطور شبکهٔ درگاهشان را برای جابه‌جایی برد کوتاه بدزدیم. حالا فقط برای برپا کردن پل‌های درگاه به کمکت نیاز داریم.\n\nچهار نقطهٔ راهبردی به تو می‌دهم، از جمله همین پادگان، برای نصب پل‌های درگاه. وقتی فعال شدند، در برابر تهدیدها با سرعت بیشتری واکنش نشان می‌دهیم.\n\nوقت کار است.", o = { "قرار دادن پل درگاه Umbral Base Camp", "قرار دادن پل درگاه Steam Ravine", "قرار دادن پل درگاه The Devouring Ingress", "قرار دادن پل درگاه Void Acropolis" }, p = "پل‌های درگاه را تمام کردی؟", c = "بی‌نقص. حالا می‌توانیم در یک لحظه به دشمنانمان ضربه بزنیم.\n\nهرگز نخواهند فهمید چه به‌شان آمد." }
WoWFQ[96547] = { t = "تضعیف نیروهایشان", d = "من از این «Hal'hadar»ها خیلی کم می‌دانم، اما به نظر از Shadowguard نیرومندتر می‌آیند. پیشنهاد می‌کنم شمارشان را کم کنی تا بعداً زیر آوارشان نروی.", o = { "تضعیف نیروها" }, c = "ضربهٔ نیرومند دیگر. هر جا نقطه ضعف دیدی، بزن!" }
WoWFQ[96548] = { t = "هاگِ برتر", o = { "بررسی Spore نامنظم", "در هم کوبیدن کلاهک سرریز‌شده" } }
WoWFQ[96557] = { t = "آوار پرنده", d = "Hal'hadarها قایق‌های پرنده‌شان را به turretهای انرژی برای «محافظت» مجهز کرده‌اند. ببینیم چه‌قدر محافظت‌شده‌اند، قبول می‌کنی؟", o = { "کار انداختن Remote Detonatorها", "منفجر شدن Remote Detonatorها" }, c = "تقریباً چنگ‌شان را از این دنیا کندی‌ایم. فشار را نگه دار." }
WoWFQ[96567] = { t = "فاجعهٔ رمزگشایی داده", d = "برای فهمیدن نیت Hal'hadarها با این دنیا، باید به اطلاعات دست پیدا کنیم.\n\nبا شناختی که از طرز کارشان داریم، کنسول‌های داده‌شان را با تدابیر امنیتی قفل کرده‌اند.\n\n<Y'mera smiles as she hands you a rune-carved crystal.>\n\nاین رمزگشا خودش از پس تدابیر امنیتی‌شان برمی‌آید. اگر بخواهی، می‌توانی حالت دستی را فعال کنی تا پروتکل تندتر برود.\n\nفقط هر هشدار امنیتی را نادیده بگیر. دستگاه من می‌تواند و ردش می‌کند.", o = { "رمزگشایی Intel Sphere", "کلید رمزگشایی Firewall", "نادیده گرفتن هشدار امنیتی", "رمزگشایی Data Record", "Lightveil Data Decrypter (provided)" }, p = "در گذشته Hal'hadarها هرگز زیاد در یک مکان نمی‌ماندند؛ هرچه از جهانی می‌چیدند، به همان سرعت ترکش می‌کردند.\n\nبه هر دلیلی، نیت‌شان با این دنیا به نظر فرق می‌کند.", c = "یک لحظه، از این داده‌ها خیلی چیز می‌شود درآورد...\n\n<Y'mera murmurs under her breath as she works.>\n\nجالب است. آنها زیر باتلاق گورستانی خاصی پیدا کرده‌اند و...\n\nاوه، این چیست؟ مکالمات رهگیری‌شده!\n\nبه نظر می‌رسد حمله‌های Leth'ir به Azeroth بدون مجوز بوده. رهبری Hal'hadar اصلاً خوشش نیامده.\n\nاین اطلاعات به‌شدت به کار می‌آید، <name>.\n\nکار خوبی بود." }
WoWFQ[96568] = { t = "Hal'hadar، جرئت نکن!", d = "نقشهٔ Y'mera برای رهگیری کنسول‌های داده‌شان بی‌شک پروتکل‌های امنیتی را به اوج می‌رساند.\n\nمعمولاً در چنین وضعیتی شناسایی بدون تماس توصیه می‌شود، اما به نظرم پا کردن هرج‌ومرج مفیدتر است.\n\nHal'hadarها اگر کل manaforge‌شان زیر حمله باشد، اصلاً حواسشان به داده‌های دزدیده‌شده نخواهد بود.\n\nهر مأمور Hal'hadar را که پیدا کردی از پا درآور.", o = { "کشته شدن Hal'hadarهای Arterial Mana-Forge" }, p = "...", c = "با هر Hal'hadar که کشته می‌شود، بدگمانی مثل بیماری در میانشان رشد می‌کند.\n\nوقتی بی‌اعتمادی و ترس تنها چیزی است که می‌ماند، ساختارشان می‌پوسد و عملیات‌شان فرو می‌ریزد.\n\nپیشاهنگان‌مان از آشوبی که ساخته‌ای استفاده خواهند کرد.\n\nکارت خوب بود، <name>." }
WoWFQ[96569] = { t = "بلورهای رسانا", d = "<به نظر می‌رسد بلورِ درخشانِ نشان‌دار روی دستگاه Hal'hadarها دارد هاگ‌های arcane را از هوا می‌مکد.\n\nهرچند دقیقاً نمی‌دانم دستگاه چیست، اما حس می‌کنم این بلور اصالت اترئالی ندارد.\n\nY'mera حتماً علاقه‌مند است چند تا از این بلورها را بررسی کند.>", o = { "Energized Crystal Conductor", "بازگرداندن Energized Crystal Conductorها به Y'mera" }, p = "بله، دوست من؟ چه خبر؟", c = "چه جالب!\n\nفهمم از draenic کمی زنگ زده است، اما به باورم این نشان‌ها روی شبکهٔ بلورها می‌گویند که آن‌ها نوعی باتری خود‌شارژند!\n\nبه نظر می‌رسد Hal'hadarها راه‌های تازه‌ای برای مکیدن انرژی arcane این دنیا یافته‌اند!\n\nاما این بلورها را از کجا آورده‌اند؟\n\nیافتهٔ کنجکاوکننده‌ای است!" }
WoWFQ[96570] = { t = "انتقال فناوری", d = "Hal'hadarها به غارت و دزدی فناوری از هر دنیایی که پا در آن می‌گذارند معروف‌اند.\n\nبه لطف اطلاعاتی که کمک کردی به دست بیاوریم، می‌دانیم از manaforge در شرق‌مان برای آزمایش روی هر salvage که پیدا کرده‌اند استفاده می‌کنند.\n\nاین translocator را بردار و هر چیزی را که شبیه فناوری اترئالی نیست نشانه‌گذاری کن.\n\nمن برای بررسی بیشتر به اینجا منتقلش می‌کنم.", o = { "بازیابی فناوری به‌غارت‌رفته" }, p = "هرچه فناوری بیشتری از عملیاتشان برداریم، زرادخانهٔ Hal'hadarها ضعیف‌تر می‌شود.", c = "انتظار داشتم فناوری Legion یا شاید Lightforged پیدا کرده باشند، اما draenei؟!\n\nبه نظر می‌رسد vigilant به‌شدت آسیب دیده... هستهٔ سازه‌اش را به‌کلی درآورده‌اند.\n\nو بلور دفاعی هم جز اصلاح شدنی خرد شده است.\n\nمگر این را همین Naigtal پیدا کرده‌اند؟ پس برای چه اینجا آورده‌اند؟\n\nپشت این ماجرا چیزی است. عمیق‌تر در داده‌هایی که پیدا کردی می‌کاوم." }
WoWFQ[96571] = { t = "گره می‌داند", d = "manaforge در شرق هم محل پژوهش است و هم قرارگاه نظامی؛ همین آن را هدفی ارزشمند می‌کند.\n\nبخش زیادی از پژوهش‌شان، شامل نقشه‌های holoprint، دور و بر forge افتاده است.\n\nHal'hadarهای مستقر در اینجا هم گره‌هایی حمل می‌کنند که داده‌های آزمایشی و پشتیبانی در آن‌هاست.\n\nاز این اطلاعات در دسترس استفاده کن و هر چه می‌توانی بیاور پیشم.", o = { "Data-Node پیاده‌نظام", "Holoprint ساخت Nullframe", "Holoprint ساخت Soul Lattice", "Holoprint ساخت گورستان براق" }, p = "گاهی شناسایی مؤثر نیازمند نقشه و پنهان‌کاری دقیق است. گاهی هم کمین ناگهانی و آزاد کردن آشوب کارآمدتر.\n\nمی‌دانم چطور. مانیفست Lightveil را من نوشته‌ام، بعد از همه.", c = "<Taka'saan's brow furrows in disbelief as he examines the holoprints.>\n\nاین گورستانی که پیدا کرده‌اند را... draeneiها ساخته‌اند؟\n\nاین توضیح می‌دهد اترئال‌ها آن بلورهای رسانا را از کجا آورده‌اند.\n\nاما چه ربطی به این «Nullframe»‌ای که می‌سازند دارد؟\n\nwarframeهای ما اصلاً با فناوری استاندارد بلوری سازگار نیستند.\n\nشاید Y'mera در همین data-nodeها جواب را پیدا کند." }
WoWFQ[96572] = { t = "Nullframe خرابکار", d = "<از ارتباط‌گر رونی، تصویری از زره مکانیکی بال‌دار می‌بینی که یک اترئال خلبانی‌اش می‌کند. صدایی از دستگاه بیرون می‌آید:\n\n«Nullframe Soul-Fuse ناموفق بود. استقرار از Nexus Port متوقف شد. رفع اشکال در جریان است.»>\n\nهر سلاحی که Hal'hadarها ساخته‌اند به نظر در Transit Hub خراب می‌شود.\n\nرهگیری و انتقال آن سلاح پیش Y'mera، اترئال‌ها را از یک سلاح دیگر محروم می‌کند.", o = { "اعمال Translocator روی Nullframe", "رهگیری Nullframe" }, p = "چه چیزی پیدا کرده‌ای، <name>؟", c = "وضعیت این Nullframe به‌شدت نگران‌کننده است.\n\nبا قضاوت‌کُرده‌ای که از بدنهٔ اصلی‌اش کنده شده، راهی برای کنترل این مکانیزم نیست...\n\nHal'hadarها حتماً راه دیگری برای خلبانی این آفرینش پیچ‌خورده‌شان امتحان می‌کنند.\n\nVerann و Kifaan با فناوری‌رانی اترئالی آشناترند.\n\nوقتی آن‌ها از نزدیک بررسی می‌کنند، من بانک‌های داده‌ای را که جمع کرده‌ایم می‌کاوم." }
WoWFQ[96573] = { t = "آشکارسازی Soul Lattice", d = "کمی دردسر داشت، اما رمزهای‌شان را شکستیم.\n\nHal'hadarها می‌خواهند Nullframeهای‌شان را با فناوری vigilantهای draenei نیرو بدهند.\n\n«Soul Lattice» قلبی است برای Nullframe که از هستهٔ یک vigilant ساخته می‌شود.\n\nبا آن، می‌توانند انرژی پیچیده‌نشده‌شان را به هسته گره بزنند و زره را مثل جامه بر تن کنند.\n\nنباید بگذاریم Hal'hadarها ساخت این prototype را تمام کنند.\n\nY'mera نقشهٔ بعدی را می‌چیند. با او صحبت کن.", o = { "با Archmage Y'mera صحبت کن", "گزارش Soul Lattice وران (provided)" }, p = "Riftblade Maella هم قبول دارد که Hal'hadarهای درون گورستان باید متوقف شوند.\n\nشاید رکِ عملیات‌شان در Naigtal نباشد، اما تهدیدی است که نمی‌شود نادیده گرفت.", c = "داده‌های Y'mera می‌گویند گورستان از Hal'hadarها انباشته است.\n\nوقتی بقیهٔ نیروهایمان اترئال‌های اطراف جزیره را می‌رانند، ما راه ظریف‌تری را برمی‌گزینیم.\n\nAllari the Souleater سواحل شمال را زیر نظر داشته و به نفوذ ما به گورستان می‌پیوندد.\n\nطنزِ لقبش در چنین مکانی از من دور نمانده است." }
WoWFQ[96574] = { t = "قرار پشت دروازهٔ گورستان", d = "نام گورستان Vilaldoun است. یعنی «جزیرهٔ آرام‌گرفتگان». ورودیش در ساحل شمالی است.\n\nمی‌دانیم Hal'hadarها بیرون گورستان پایگاه استخراجی برپا کرده‌اند و گیاهان بومی آنجا را برای سوخت پژوهش‌شان می‌چینند.\n\nوقتی نزدیک شوی، مقاومت سنگینی در انتظارت است.\n\nراهی در صف‌هایشان باز کن تا ما داخل جا باز کنیم؛ بعد به درون بپیوند.", o = { "کشته شدن Hal'hadarهای Extraction Shore" }, p = "برای عده‌ای چپاولگر، این اترئال‌ها بسیار شیطان‌تر از تصورم‌اند. این کار کشتن‌شان را شیرین‌تر می‌کند.", c = "نمی‌گویم وسوسه نشدم بیایم بالا کمکت، اما یکی باید حواسش به پشت سر Y'mera باشد.\n\nTala'saan رفته پیش تا معمار این عملیات را پیدا کند.\n\nموضع‌مان را در همین پلکان امن کردیم و راه برگشت را روی هر Hal'hadar که دنبال‌مان بیاید بستیم.\n\nپس کار توست که از میان این مکان آلوده راه باز کنی." }
WoWFQ[96575] = { t = "قفس‌های روح", d = "بدون دفاع‌های گورستان، جان‌های مردگان هدفی راحت برای Hal'hadarها بودند.\n\nاترئال‌ها می‌خواهند از ارواح برای سوخت‌رسانی به Soul Latticeهای Nullframe استفاده کنند.\n\nنمی‌توانیم بگذاریم این شود.\n\nعصای مرا بردار و با آن wardهای دفاعی را ترمیم کن و قفس‌های انرژی‌ای که مردگان را بسته را بشکن.\n\nوقتی تمام شد، در طبقات پایینی با Tala'saan دوباره جمع شو.", o = { "باز شدن قفس‌های انرژی", "آزادسازی ارواح draenei", "ترمیم wardهای دفاعی Vilaldoun" }, c = "بی‌اختیار فکر می‌کنم این draeneiها چقدر است اینجا خاک خورده‌اند...\n\nچند دور و بر از این گوشهٔ کوچک تمدن draenei محو شده است.\n\nسال‌ها پیش Legion بود که آن‌ها را به بی‌قراری انداخت، یا چپاول Hal'hadarها بیدارشان کرد؟\n\nالان فقط یک چیز مهم است: برگردند به آسودگی‌شان.\n\nwardها مواظبت می‌کنند دیگر کسی مزاحمشان نشود." }
WoWFQ[96576] = { t = "یادگارهای مردگان", d = "بی‌حرمتی به گورستان‌ها... کشیدن جان بی‌گناهان به‌عنوان سوخت...\n\nHal'hadarها از دیوها هم پست‌ترند.\n\nاگر مهارشان نکنیم، اترئال‌ها هر گور و هر مذبحی را که این پایین باشد بالا می‌کشند.\n\nشاید لقبم «خورندهٔ روح» باشد، اما یعنی نمی‌توانم در این مکان فراموش‌شده به مردگان احترام بگذارم؟\n\nنذوراتی را که اترئال‌ها دزدیده‌اند بازیاب. پیش Tala'saan در طبقات پایینی ببر.", o = { "Forgotten Memorial Tribute", "در طبقات Vilaldoun با Commander Tala'saan صحبت کن." }, p = "<Tala'saan appears quite clam, his armor flecked with arcane smatterings of the ethereals he slew.>\n\nچه چیزی پیدا کردی؟", c = "<Tala'saan is silent for a moment as he examines the mementos you recovered.>\n\nAllari از تو خواست این‌ها را بازیابی کنی؟\n\nو من این‌همه فکر می‌کردم دل‌بستگی‌اش به مأموریت‌مان فقط بهانه‌ای است برای قصابی اترئال‌ها.\n\nممنونم، <name>.\n\nخودم مواظب هستم این یادگارها در جایی امن‌تر به خاک سپرده شوند." }
WoWFQ[96577] = { t = "معمار روح", d = "معماری که رهبری عملیاتشان را بر عهده دارد، یک vigilant با هستهٔ سازهٔ سالم پیدا کرده است.\n\nبقیهٔ vigilants این تالار به نظر تخلیه‌شده‌اند.\n\nاگر در ساختن Soul Lattice موفق شود، Hal'hadarها راهی خواهند داشت که warframeهای ما را بدل کند به بدن‌های زرهی تازه برای سربازانشان.\n\nباید همین حالا جلویش را بگیریم و prototype Soul Lattice را پس بگیریم.", o = { "شکست Artiseer Ahl'syraz", "Soul Lattice خردشده" }, p = "اگر Hal'hadarها در ریختن Soul Lattice موفق شوند، شاید راهی برای به‌کارگیری فناوری خودمان علیه خودمان پیدا کنند.", c = "تمام شد و با این حال...\n\n<Tala'saan trails off for a moment as he thinks, his brow furrowed.>\n\nSoul Lattice شکسته است، اما هنوز چیزی کم داریم.\n\nvigilantهایی که برداشت واکشده بودند؛ هسته‌های‌شان از روحانی که در آن‌ها می‌زیست خالی بود.\n\nاگر دنبال هستهٔ سازه نبود، آن «کلید حقیقی» چه بود؟ چرا پوسته‌های خالی را برد؟" }
WoWFQ[96578] = { t = "رفتنی رمزآلود", d = "هرچند گریخت، prototype را از معمار گرفتیم... فعلاً.\n\nاین Soul Lattice ترک‌خورده است، اما هستهٔ درونش هنوز با انرژی کم‌رمقی می‌خواند.\n\nشاید روح این vigilant هنوز باقی باشد...\n\nاگر تند باشیم، شاید وران و برادرش بتوانند آسیب را تثبیت کنند تا از بین نرود.\n\nمن پیش Y'mera و Allari برمی‌گردم و در اردوگاه به تو می‌پیوندم.", o = { "بازگشت به Umbral Base Camp." }, c = "<Veraan examines the Soul Lattice.>\n\nمن کارشناس کارهای Hal'hadarها نیستم، اما خودم هم می‌فهمم این آسیب جدی است.\n\nبا این روند، هستهٔ vigilant زیاد سالم نمی‌ماند.\n\nاگر من و Kifaan با وسواس شبکه را باز کنیم، شاید بتوانیم هسته را جدا کنیم.\n\nاگر خیلی مراقب باشیم، شاید خود شبکه هم سالم بماند.\n\nقولی نمی‌دهم، <name>." }
WoWFQ[96600] = { t = "علف‌هرزکنی در گورستان", d = "دشمنانمان هرگز دست برنمی‌دارند... این تهدید را سر و کلاه بگذار و تند باش!", o = { "کشته شدن Crypt Raider", "کشته شدن Artificer's Haulnaught" }, c = "لحظه‌ای نفس تازه کن. دشمنانمان هنوز از پا نیفتاده‌اند." }
WoWFQ[96611] = { t = "کاهش طوفان", o = { "شکست دادن Elementalهای جنون‌آمیز" }, c = "..." }
WoWFQ[96623] = { t = "کود پشیمان", d = "پسابِ محل‌های فرآوری manaforge بر جانوران بومی اثر گذاشته است. چند نمونه برای پژوهش‌مان جمع کن.", o = { "جمع‌آوری Salt Cap" }, c = "به نفع خودت امیدوارم همهٔ مأموریت‌هایت این‌طور تمام نشود." }
