WoWFQ[96691] = { t = "فلاخن شاخک Command Point", o = { "پیچک گرفته شد", "Coalescing Leaf Storm تجزیه شد (4)" }, c = "..." }
WoWFQ[96809] = { t = "Translocator بیرونی Manaforge", d = "مسیر بازی کردن در این سنگ آلوده به هاگ دارد به کار روزمره بدل می‌شود، مطمئنم با من هم‌نظری.\n\nخوشبختانه راهی پیدا کرده‌ام که از شبکهٔ Manaforge Translocator موجود، که خیلی مرتب قبل از آمدن ما ساخته شده بود، استفاده کنیم.\n\nمی‌توانم نشان بدهم چطور برای مصرف خودمان آن‌ها را «فعال» کنی. با همان یکی شروع کن که... خودش به اردوگاه منتقل شد.", o = { "فعال کردن Translocator اردوگاه Umbral Base Camp", "فعال کردن Translocator نقطهٔ Nexus", "فعال کردن Translocator Sporeforge", "فعال کردن Translocator ساحل استخراج" }, c = "فوق‌العاده! حالا می‌توانیم سریع و نامرئی جابه‌جا شویم." }
WoWFQ[97031] = { t = "بدرقهٔ Vilaldoun", d = "<برق گذرایی که در سایه‌ها می‌درخشد نظرت را جلب می‌کند.\n\nهمین که شیء را برمی‌داری، گوهر وسطش لحظه‌ای می‌سوسد و رون‌های غریبه‌ای بیگانه روی سطحش رد می‌شوند.\n\nبرای لحظه‌ای، تصویر ضبط‌شدهٔ لرزانی از یک draenei مذکر می‌بینی که بی‌صدا حرف می‌زند.\n\nY'mera حتماً به این شیء علاقه‌مند خواهد شد.>", o = { "رساندن Hologem به Archmage Y'mera در اردوگاه Umbral Base Camp." }, c = "این را در گورستان پیدا کردی؟\n\nاین یک hologem است--ابزاری draenei برای ارتباط و ذخیرهٔ اطلاعات.\n\nبه نظر تقریباً ته‌کشیده است. اترئال‌ها باید فکر کرده‌اند همین یک خرده‌زدگی ساده است.\n\nببینم می‌توانم انرژی‌اش را برگردانم و به اطلاعات درونش دست پیدا کنم.\n\nشاید دربارهٔ کسانی که در Vilaldoun خفته‌اند بیشتر نشان دهد." }
WoWFQ[97034] = { t = "سرکوب جنگ‌افروز", d = "جانور کوچک Impotus باور ندارد می‌توانیم کنترل را از خویشاوندان پلیدش بگیریم. تنگ‌نظری‌اش جانگداز است.\n\nفقط باید نمونه‌ای از قدرت جمعی‌مان به او نشان بدهیم. آن خشمگین تازه‌وارد، Ignedus، را بکش. فکر کنم زره‌اش روی منجی تازه‌مان خوب بنشیند.\n\nIgnedus خیلی مراقب است کسی صورتش را نبیند، اما واضح است که عصبانیتش ترکیده است. برو در و دیوار را بریز، همان‌طور که بهش عادت داری. انتظار دارم به همان روش جواب بدهد.", o = { "سفر به درون Void Acropolis", "به هم زدن نیروهای domanaar", "به چالش کشیدن Ignedus با دستگاه تصویر", "Warmonger's Voidplate" }, p = "احمقی اگر فکر می‌کنی می‌شود این‌طور سریع سر و کلهٔ Ignedus را گذاشت.", c = "تو واقعاً... یعنی البته که موفق شدی. معلوم است، من که هرگز طرف بازنده را نمی‌گیرم." }
WoWFQ[97035] = { t = "دفع دیوانگان", d = "شکست دادن Ignedus که کار قابل احترامی است، فرض می‌کنم، اما یعنی به فتح Val نزدیک‌تر نشده‌ای. Periculus نمی‌گذارد به اسباب‌بازی‌هایش دست بزنی.\n\nاو یک... عجیب‌وغریب است، دست‌کم، و به‌طرز هولناکی شیفتهٔ موجودات گوشت‌پوست توست.\n\nاحتمالاً همان تاریک‌ترین چاله‌ای را که این دنیا دارد پیدا می‌کنی، جایی که دام‌هایی را که Pertinax جمع کرده می‌شکافد.\n\nعاشق بازی با طعمه‌هایش است، پس حذر کن.", o = { "سوار شدن به درگاه به Forgotten Depths", "بررسی سرنخ اول", "بررسی سرنخ دوم", "بررسی سرنخ سوم", "کشته شدن Periculus" }, p = "تا وقتی Periculus در این اطراف پرسه می‌زند، فرماندهی این دنیا را نمی‌پذیرم. او... وحشتم می‌کند...", c = "پس تمام شد؟ برای هر موجود زنده در کیهان، این یک آرامش است." }
WoWFQ[97036] = { t = "میدان عنوان‌های Umbral", d = "خب، به نظر می‌رسد هدف‌های‌مان این بار هم‌راستاتر از قبل است. تحت تأثیر قرارم دادی. با حل شدن Ignedus و Periculus، فقط همکار سابق من باقی مانده است.\n\nGladius Reginax را همان بالا، روی سکوی مرتفع، مشغول تماشای شکارش می‌یابی. از قبل می‌داند که می‌آیی، پس دنبال غافلگیری نرو. به‌هرحال فقط یک راه به آنجاست: از همان درگاه در Glacial Reservoir.\n\nمن هم نقشم را بازی می‌کنم و به تو می‌پیوندم. نشانه‌ای از... همکاری‌مان.", o = { "سوار شدن به درگاه به Transit Platform", "کشته شدن Gladius Reginax" }, c = "وای، تو چه موجود موذی‌ای هستی. چه حسی دارد بازی کردن با مهره‌های خودت؟" }
WoWFQ[97071] = { t = "استقبال سرد Val", d = "حتی با عنصر غافلگیری، بدون متحد در موضع ضعیفیم.\n\nتکیه دادن تنها بر سنگر Pertinax حکم حکم مرگ است.\n\nاین نشانگر را که Tala'saan به ما داد بردار و با آن به نقطهٔ ورودمان برگرد.\n\nآنجا به تو می‌پیوندم و گزارشم را به Maella می‌دهم.\n\nبیایید امیدوار باشیم جایی برای پناه گرفتن منتظرمان باشد.", o = { "استفاده از Lightveil Recall Beacon برای بازگشت به اردوگاه" }, c = "دست‌کم سرما نکشتت.\n\nبه لطف Y'mera، نقطهٔ ورود پایدارتری به این دنیای یخ‌زده داریم.\n\nنشانگرش به Silvermoon هم وصل است؛ اگر لازم شد، نقطهٔ تخلیهٔ سریع‌مان می‌شود.\n\nبا نشانگرهای دیدبانی سر جایشان و سنگر محکم، می‌شود کار را شروع کرد.\n\nبه Val خوش آمدی، <name>." }
WoWFQ[97072] = { t = "استقبال باتلاقی Naigtal", d = "Nexus Captain پشت همان تپه است، بی‌خبر از آمدن ما.\n\nحمله کردن همین حالا ارتشش را غافلگیر می‌کند... و احتمالاً ما را نابود.\n\nدر هر صورت، برای موفقیت به متحد نیاز داریم.\n\nاز این نشانگر استفاده کن تا به نقطهٔ یورش‌مان در صخره‌های جنوبی برگردی.\n\nتا الان Y'mera باید بقیهٔ نیروها را برای پشتیبانی آورده باشد.\n\nوقتی رسیدی با Maella صحبت کن.", o = { "استفاده از Lightveil Recall Beacon برای بازگشت به اردوگاه", "با Riftblade Maella در Umbral Base Camp در Naigtal صحبت کن." }, c = "خوشحالم که باتلاق نبلعیدت.\n\nزحمات Y'mera نقطهٔ ورود پایدارتری به این دنیا برایمان فراهم کرد.\n\nنشانگرش به Silvermoon هم وصل است؛ اگر لازم شد، نقطهٔ عقب‌نشینی سریع‌مان می‌شود.\n\nبا نشانگرهای دیدبانی سر جایشان و سنگر محکم، می‌شود کار را شروع کرد.\n\nبه Naigtal خوش آمدی، <name>." }
WoWFQ[97077] = { t = "شلیکی به تاریکی", d = "حالا که دام‌مان هم‌آوا شد، فقط باید طعمه را به فضای باز بکشانیم.\n\nمن راهبردانه... بعضی قطعات دستگاه تصویری را که به دست آوردم... از کار انداخته‌ام. Impotus در دیدن و شنیدن تو دچار مشکل خواهد شد.\n\nادعا کن یکی از متحدانش و همین حالا جلسه‌ای بخواه. امیدواریم کنجکاوی بر او چیره شود.\n\nو بعد... <Leona holds up the void-infused gem, glances at it for a moment, then nods at you.>", o = { "فریب دادن Impotus با Projection Amplifier.", "به دام افتادن Impotus." }, p = "طعمه‌مان در دل همین دیوارهای یخ‌زده کمین کرده. ما هم پشت سرت می‌آییم.", c = "می‌دانستم آرزو داریم قراردادی خوش‌برخوردتر به دست آوریم، اما لازم است این‌قدر... بی‌روح باشد؟" }
WoWFQ[97256] = { t = "برکندن سرستون (قهرمانانه)", d = "حتی بی‌رحم‌ترین موجودات هم وقتی ببینند بزرگ‌ترین قهرمانانشان خاکستر می‌شوند، سست می‌شوند.\n\nبه دشمنان اینجا یادآوری کن رهبرانشان چه‌قدر زود از پا درمی‌آیند!\n\nبگذار بفهمند هیولاهای Azeroth واقعاً چه‌قدر بی‌امان و بی‌رحم‌اند! نشان‌های Void Commander را برایم بیاور و به‌اندازه پاداش می‌گیرم.", o = { "نشان Void Commander" }, p = "همین حالا تمامش کردی؟", c = "مثل همیشه شیطانی. هم‌نوع تو مدام به من یادآوری می‌کنند چرا برای یاری خودت انتخابت کردم.\n\nبه‌عنوان پاداش، وسایلی برای آیندهٔ کارهای‌مان تهیه کرده‌ام. لازم نیست به متحدانت بگویی." }
WoWFQ[97621] = { t = "The Singularity Anchor", d = "سفرمان به این دنیا شناخت ren'dorei از Void را عمیق‌تر از همیشه کرده است. این domanaarها که دشمن مشترکی با ما دارند به‌طرزی عجیب با دانش‌شان دست‌ودل‌بازند. گمان می‌کنم می‌خواهند ما هم به تهدیدی مثل خودشان بدل شویم.\n\nلنگرگاهی از جنس Singularity در Stormarion Citadel هست. یاد گرفته‌ام چطور از بخشی از قدرتش برای ساختن شیئی نیرومند برای تو بهره بگیرم.\n\nاما اول باید مطمئن شویم به دست دشمنان نمی‌افتد.", o = { "دفاع از Singularity Anchor" }, p = "لنگرگاه را از یورش نیروهای void محافظت کردی؟", c = "خوب بود، <name>." }
WoWFQ[97945] = { t = "در سایهٔ Catalyst", d = "آه، <name>! خوب. حالا که کمکم کردی این‌همه انبوهی از منابع جمع کنم، وقتش رسیده سراغ علایق... دیگری بروم.\n\nچه؟ انتظار خیانتی پرحاشیه‌تر داشتی؟ هرگز!\n\nنگران نباش، <name>، هر جا سرم گرم باشد، از تماشای ماجراجویی‌هایت خسته نمی‌شوم.\n\nماجراجویی‌هایی که البته همچنان با هدایای من تقویت می‌شوند. خیلی‌ها علاقه نشان دادند، اما فقط یک void elf را پیدا کردم که... به‌طرز خنده‌داری آن‌قدر عجیب باشد که شاگردش شوم.\n\nاسمش Orin Straylight است. او را کنار Catalyst در Silvermoon پیدا می‌کنی.", o = { "با پرتال از Voidstorm به Silvermoon برو" }, c = "آه، پس با Decimus صحبت کردی؟ به نظر می‌رسد از این به بعد فقط خودمانیم. بهتر است شروع کنیم." }
WoWFQ[97981] = { t = "برکت‌های Umbral Catalyst", c = "با کامل شدن این پژوهش، می‌توانم بافتن Nebulous Voidcoreها را از انرژی Catalyst آغاز کنم. برای این کار به مواد خام نیاز دارم و گمان کنم به پای Decimus که با Voidforge کار می‌کرد، کارآمد نباشم." }
WoWFQ[98390] = { t = "ارتقا با Venomstone‌ها", c = "با Catalyst، زهرِ نخستینی را که آوردی به یک Ascendant Venomstone تبدیل کردم. می‌توانم این توانایی را در تو القا کنم که هنگام رویارویی با دشمنان قدرتمند، بیشمارِ این‌ها را پیدا کنی. باید آن‌ها را همین‌جا نزد Catalyst بیاوری تا قدرتشان را در تجهیزاتت بافته کنم. به نظر می‌رسد فقط سلاح‌های قدرتمند، ترینکت‌ها و گردنبندها می‌توانند انرژی‌های رهاشده را در خود نگه دارند." }
